REPLACE INTO `x_config_general` (`GeneralID`, `GeneralValue`, `GeneralDesc`, `GeneralStamp`) VALUES (10, '-1', 'GEN_SIRES_TEST', CURRENT_TIMESTAMP());
REPLACE INTO `x_config_reports` (`ReportName`, `ReportClinicID`, `ReportTechDesc`, `ReportTechVersion`, `ReportText`, `ReportGroup`, `ReportGroupOrder`, `ReportInvisible`) VALUES ('SIRES_EXPORT', 0, 'Exportar al SIRES', '1', '<!--#include virtual="/_include/report_head.asp"-->\r\n\r\n<%\r\n\r\n\' ===============================================================================================\r\n\' FLOWww System for Aesthetic Clinics                         Copyright 2024 Integra Digital S.L.\r\n\' http://www.integradigital.com                                           info@integradigital.com\r\n\'\r\n\' INFORME: Integración con el SIRES - Sistema de Registro electonico de salud en MX (sires_export)\r\n\'\r\n\' @Created: 31/03/2025 \r\n\' @HS:22055276319. Conciliación de requisitos y puesta en marcha.\r\n\' @Autor: ARA. \r\n\' @Description: Se conforma de 3 bloque visuales. 1 - Datos del paciente.2 - Regisro de consultas. 3 - Formulario de consulta\r\n\' ===============================================================================================\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE ETIQUETAS. Se determinan las etiquetas por bloques.\r\n\r\n\'ETIQUETAS GENERALES\r\n  slbl_select_one_m = fsGetLabel("lbl_select_one_m") \r\n  slbl_rpt_go_back = fsGetLabel("lbl_rpt_go_back")\r\n  slbl_go_back = fsGetLabel("lbl_go_back")\r\n  slbl_exportar_file_sires = fsGetLabel("lbl_exportar_file_sires")\r\n  slbl_export = fsGetLabel("lbl_exportar_file_sires_txt")\r\n  slbl_search_for = fsGetLabel("lbl_search_for")  \r\n  slbl_date = fsGetLabel("lbl_date")  \r\n  slbl_clinic = fsGetLabel("lbl_clinic")  \r\n  slbl_user = fsGetLabel("lbl_user")  \r\n  slbl_date_ini = fsGetLabel("lbl_date_ini")  \r\n  slbl_date_fin = fsGetLabel("lbl_date_fin")  \r\n  slbl_type_diary = fsGetLabel("lbl_type_diary")  \r\n  slbl_export_confirmed = fsGetLabel("lbl_export_confirmed")  \r\n  slbl_export_confirmed_min = fsGetLabel("lbl_export_confirmed_min")  \r\n  slbl_registry_exports = fsGetLabel("lbl_registry_exports") \r\n  slbl_show_rows = fsGetLabel("lbl_show_rows") \r\n  slbl_pagination = fsGetLabel("lbl_pagination") \r\n  slbl_encripted_file = fsGetLabel("lbl_encripted_file")    \r\n  slbl_not_encripted_file = fsGetLabel("lbl_not_encripted_file")    \r\n\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE VARIABLE AUXILIARES\r\n\r\n\'Se determina si el filtro de fecha es seleccionando periodo a un mes\r\nfilterByMonth = true \r\n\r\n\'Se obtienen las variables de sesión necesarias\r\nsS_ClinicID = CStr(Session(SES_USER_CLINICID))\r\nsS_UserID = CStr(Session(SES_USERID))\r\n\r\n\'Se obtienen los parámetros enviados por GET (URL) utilizado para la exportación csv.\r\nIf Request.ServerVariables("REQUEST_METHOD") = "GET" Then\r\n  sReportName =  fsCheckString(Request.QueryString("name"), "", "", 1, 128, True, "", False)\r\n  sReportTitle = fsCheckString(Request.QueryString("tit"), "", "", 0, 0, True, "", False)    \r\n  sReportPar1 = fsCheckString(Request.QueryString("par1"), "", "", 0, 0, True, "", False)    \r\n  sFile = fsCheckString(Request.QueryString("file"), "", "", 0, 0, True, "", False)    \r\n  sFormat = fsCheckString(Request.QueryString("ft"), "", "", 0, 0, True, "", False)    \r\nEnd If\r\n\r\n\'Se obtienen los parámetros enviados por POST (AJAX) utilizado para peticiones .\r\nIf Request.ServerVariables("REQUEST_METHOD") = "POST" Then\r\n     \r\n  \'Limpiamos la respuesta\r\n  Response.Clear()\r\n  \r\n  \'Creamos el objeto JSON de respuesta\r\n  Set objJSON = CreateObject("Scripting.Dictionary")\r\n\r\n  \'Parámetros enviados POST\r\n  formtype = Request.Form("form")\r\n  sR_DateStart = Request.Form("ds") \r\n  sR_DateEnd = Request.Form("de") \r\n  sR_ClinicID = Request.Form("xcid") \r\n  sR_ClientID = Request.Form("cid") \r\n  sR_UserID = Request.Form("uid")    \r\n  sR_Limit = Request.Form("lm") \r\n  sR_Start = Request.Form("st")   \r\n  sR_STypeDiary = Request.Form("tf")  \r\n  sR_SExportID = Request.Form("eid")  \r\n    \r\nEnd If\r\n\r\n\'Se guarda URL y nombre del reporte\r\nSession("prev_url") = Request.ServerVariables("PATH_INFO")   \r\nSession("report_name") = sReportName\r\n\r\n\'Variables auxiliares para identificar carga de datos.\r\n\r\nCurPag = 0\r\nicountpage = 0\r\ndCurrentDate = Date()\r\n\r\nIf sR_DateStart = "" Then\r\n    sR_DateStart = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2) & "-01" \r\nEnd If\r\n\r\nIf sR_Month = "" Then\r\n   sR_Month = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2)  \r\nEnd If\r\n\r\nIf sR_UserID = "" Then\r\n    sR_UserID = sS_UserID \r\nEnd If\r\n\r\nIf sR_DateEnd = "" Then\r\n    sR_DateEnd = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2) & "-" & Right("0" & Day(dCurrentDate), 2)\r\nEnd If\r\n\r\nIf sReportPar1 = 1 then\r\n    slbl_ReportName = slbl_ReportName_Bucal\r\n    sHeightframe = "6200px"\r\nElse\r\n    slbl_ReportName = slbl_ReportName_CE\r\n    sHeightframe = "9800px"\r\nEnd If\r\n\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE FUNCIONES AUXILIARES DE CARGA DE DATOS\r\n\r\n\'Se exporta fichero al SIRES\r\nFunction ExportData(datestart,datend,clinicid,typediaryid,userid,formatexp)\r\n\r\n    Dim jsonResult,filename,sFolder,filepath,lblencript\r\n\r\n    \'Se determina el nombre del fichero a exportar\r\n    Set rs5Data = Server.CreateObject("ADODB.RecordSet") \r\n    sRSQL = "SELECT __fRptGetData_SIRES_Filename(\'" & clinicid & "\',\'" & typediaryid & "\',\'" & datestart & "\'"  & ") AS filename;"\r\n    rs5Data.Open sRSQL, objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    filename = rs5Data("filename")\r\n    rs5Data.Close: Set rs5Data = Nothing   \r\n    \r\n    \'Elimina el archivo si existe\r\n    sFolder = "C:\\ProgramData\\MySQL\\MySQL Server 5.7\\Uploads\\cifrado\\"  \r\n    filepath = sFolder & filename\r\n    \r\n    Set fso = Server.CreateObject("Scripting.FileSystemObject")\r\n\r\n    If fso.FileExists(filepath) Then    \r\n        fso.DeleteFile filepath, True    \r\n    End If  \r\n    Set fso = Nothing \r\n\r\n    \'Se crea el fichero\r\n    Set rs4Data = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';")\r\n    sR0SQL = "CALL __fRptGetData_SIRES_Export(\'" & datestart & "\',\'" & datend & "\',\'" & clinicid & "\',\'" & typediaryid & "\',\'" & userid & "\');"\r\n    rs4Data.Open sR0SQL, objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    If Not rs4Data.EOF Then\r\n        msg = rs4Data("msg")\r\n        success = rs4Data("success")\r\n    End If        \r\n    rs4Data.Close: Set rs4Data = Nothing \r\n\r\n    \'Se encripta el fichero\r\n    lblencript = EncriptingFile(filename)\r\n    encriptfile = filename\r\n    IF formatexp = 1 Then\r\n        encriptfile = Replace(filename,".txt",".cif")\r\n    End IF\r\n    jsonResult = jsonResult & "{""results"" : [{" & vbCrLf \r\n    jsonResult = jsonResult &  """success"" : """ & success & """," & vbCrLf\r\n    jsonResult = jsonResult &  """msg"" : """ & fsGetLabel(msg) & """," & vbCrLf\r\n    jsonResult = jsonResult &  """msgencript"" : """ & fsGetLabel(lblencript) & """," & vbCrLf\r\n    jsonResult = jsonResult &  """filename"" : """ & encriptfile & """" & vbCrLf\r\n    jsonResult = jsonResult &  "}]}"\r\n\r\n    ExportData = jsonResult \r\n\r\nEnd Function\r\n\r\n\'Se obtienen el listado de exportaciones\r\nFunction GetListExports(datestart,datend,clinicid,typediaryid,userid,limit,start)\r\n\r\n    Dim jsonResult\r\n    Dim iCount \r\n\r\n    jsonResult = "{" & vbCrLf\r\n\r\n    \'Se determinan el total de registro sspor página\r\n    limitt = 429496729\r\n    startt = 0\r\n\r\n    Set rsDataTotal = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';")        \r\n    rsDataTotal.Open "CALL __fRptGetData_SIRES_ListExportsTotal(\'" & datestart & "\',\'" & datend & "\',\'" & clinicid & "\',\'" & typediaryid & "\',\'" & limitt & "\',\'" & startt & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    \'Atributos del objeto JSON  \r\n    jsonResult = jsonResult & """totals"" : [{" & vbCrLf \r\n    jsonResult = jsonResult &  """countpage"" : """ & rsDataTotal("CountPage")  & """," & vbCrLf\r\n    jsonResult = jsonResult &  """counttotal"" : """ & rsDataTotal("CountTotal") & """" & vbCrLf  \r\n    jsonResult = jsonResult &  "}],"\r\n\r\n    \'Cerramos el RecordSet.\r\n    rsDataTotal.Close: Set rsDataTotal = Nothing   \r\n\r\n    \'Se determina los registros a mostrar en la página seleccionada.\r\n    Set rs4Data = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';")\r\n    rs4Data.Open "CALL __fRptGetData_SIRES_ListExports(\'" & datestart & "\',\'" & datend & "\',\'" & clinicid & "\',\'" & typediaryid & "\',\'" & userid & "\',\'" & limit & "\',\'" & start & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    jsonResult = jsonResult & """results"" : [" & vbCrLf \r\n\r\n    \'Contador de iteraciones para saber cuando es la 1 iteración.            \r\n    iCount = 0      \r\n\r\n    Do While Not (rs4Data.EOF) \r\n\r\n        \'Se escribe el primer objeto JSON.\r\n        If iCount = 0 Then\r\n        jsonResult = jsonResult & "{" & vbCrLf                    \r\n        Else\r\n        jsonResult = jsonResult & "," & vbCrLf & "{" & vbCrLf\r\n        End If \r\n\r\n        \'Se determina el contador de filas\r\n        iCount=iCount + 1 \r\n\r\n        \'Atributos del objeto JSON  \r\n        jsonResult = jsonResult &  """id"" : """ & rs4Data("SExportID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """datetime"" : """ & rs4Data("SExportDateTime") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """username"" : """ & rs4Data("UserName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """clinicname"" : """ & rs4Data("ClinicName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """clinicid"" : """ & rs4Data("SExportClinicID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """datestart"" : """ & rs4Data("SExportDateStart") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """dateend"" : """ & rs4Data("SExportDateEnd") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """typediary"" : """ & rs4Data("SExportTypeDiary") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """confirmed"" : """ & rs4Data("SExportDateConfirmed") & """" & vbCrLf\r\n        jsonResult = jsonResult &  "}"\r\n        rs4Data.MoveNext\r\n    Loop\r\n\r\n    \'Se finaliza arreglo de registros.\r\n    jsonResult = jsonResult & "]" & vbCrLf   \r\n\r\n    \'Se finaliza cadena JSON\r\n    jsonResult = jsonResult & "}" & vbCrLf  \r\n\r\n    \'Cierre el RecordSet.\r\n    rs4Data.Close: Set rs4Data = Nothing     \r\n\r\n    \'Si no se encuentra la cadena\r\n    GetListExports = jsonResult \r\n\r\nEnd function\r\n\r\n\'Permite confirmar que se ha importado el registro al SIRES.\r\nFunction ConfirmExportID(exportid,userid)\r\n\r\n    Dim jsonResult\r\n\r\n    \'Se determina el nombre del fichero a exportar\r\n    Set rsConfirmData = Server.CreateObject("ADODB.RecordSet") \r\n    sRSQL = "CALL __fRptSaveData_SIRES_ConfirmExport(\'" & exportid & "\',\'" & userid & "\');"\r\n    rsConfirmData.Open sRSQL, objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    msg = rsConfirmData("msg")\r\n    rsConfirmData.Close: Set rsConfirmData = Nothing \r\n\r\n    jsonResult = jsonResult & "{""results"" : [{" & vbCrLf \r\n    jsonResult = jsonResult &  """success"" : """ & success & """," & vbCrLf\r\n    jsonResult = jsonResult &  """msg"" : """ & fsGetLabel(msg) & """" & vbCrLf\r\n    jsonResult = jsonResult &  "}]}"\r\n\r\n    ConfirmExportID = jsonResult \r\n\r\nEnd Function\r\n\r\n\'Se exporta el listada de clínicas\r\nFunction GetSelectClinics(clinicidselected)\r\n    Dim sR2SQL,sOptions,sRestrictPermission\r\n\r\n	If Session(SES_USERCLASS) <> DEF_USER_SUPER And Not Session(SES_USER_CALLCENTER) Then \r\n		sRestrictPermission = " INNER JOIN x_config_workplaces ON (WorkPlaceClinicID=ClinicID OR WorkPlaceClinicID=0) AND WorkPlaceUserID=" & CStr(Session(SES_USERID))\r\n	Else\r\n		sRestrictPermission = ""\r\n	End If\r\n\r\n    sR2SQL = "SELECT xc.ClinicID,CONCAT(xc.ClinicPrefix,\' - \', xc.ClinicCommercialName) AS ClinicName FROM x_config_clinics xc " & sRestrictPermission & " WHERE xc.ClinicDisabled=0"						\r\n    sOptions =  ""\r\n    \r\n    Set rsR2Data = Server.CreateObject("ADODB.Recordset")\r\n    rsR2Data.Open sR2SQL, objConnection, adOpenForwardOnly, adLockReadOnly\r\n    Do While Not (rsR2Data.EOF) \r\n        If  CStr(rsR2Data("ClinicID")) = clinicidselected  Then\r\n            sOptions = sOptions & "<OPTION VALUE=""" & rsR2Data("ClinicID") & """ SELECTED >" & rsR2Data("ClinicName") & "</OPTION>"\r\n        Else\r\n            sOptions = sOptions & "<OPTION VALUE=""" & rsR2Data("ClinicID") & """ >" & rsR2Data("ClinicName") & "</OPTION>"\r\n        End If \r\n        rsR2Data.MoveNext\r\n    Loop\r\n    rsR2Data.Close: Set rsR2Data = Nothing\r\n    \r\n    GetSelectClinics = sOptions\r\n\r\nEnd Function\r\n\r\n\'Se exporta el listada de guías\r\nFunction GetSelectTypeDiary(typediaryselected)\r\n    Dim sR1SQL,sOptions\r\n    sR1SQL = "SELECT STypeDiaryID, STypeDiaryDesc FROM __sires_type_diary ORDER BY STypeDiaryID DESC;"						\r\n    sOptions =  ""\r\n    \r\n    Set rsR1Data = Server.CreateObject("ADODB.Recordset")\r\n    rsR1Data.Open sR1SQL, objConnection, adOpenForwardOnly, adLockReadOnly\r\n    Do While Not (rsR1Data.EOF) \r\n        If  CStr(rsR1Data("STypeDiaryID")) = typediaryselected  Then\r\n            sOptions = sOptions & "<OPTION VALUE=""" & rsR1Data("STypeDiaryID") & """ SELECTED >" & rsR1Data("STypeDiaryDesc") & "</OPTION>"\r\n        Else\r\n            sOptions = sOptions & "<OPTION VALUE=""" & rsR1Data("STypeDiaryID") & """ >" & rsR1Data("STypeDiaryDesc") & "</OPTION>"\r\n        End If \r\n        rsR1Data.MoveNext\r\n    Loop\r\n    rsR1Data.Close: Set rsR1Data = Nothing\r\n    \r\n    GetSelectTypeDiary = sOptions\r\n\r\nEnd Function\r\n\r\nSub GetFileExport(filename,format)\r\n	\r\n	Dim objStream,filePath,sFolder\r\n	\r\n    sFolder = "C:\\ProgramData\\MySQL\\MySQL Server 5.7\\Uploads\\cifrado\\" \r\n    strfilename = filename\r\n    IF format=1 Then\r\n        strfilename = Replace(filename,"txt","cif")\r\n    End IF\r\n	filePath = sFolder & strfilename\r\n\r\n    Set objFSO = Server.CreateObject("Scripting.FileSystemObject")\r\n\r\n    If objFSO.FileExists(filePath) Then\r\n\r\n        \'Preparar respuesta binaria\r\n        Response.Clear\r\n        Response.ContentType = "application/octet-stream"\r\n        Response.AddHeader "Content-Disposition", "attachment; filename=" & strfilename\r\n\r\n        \'Leer archivo como binario\r\n        Set objStream = Server.CreateObject("ADODB.Stream")\r\n        objStream.Type = 1 \' Binary\r\n        objStream.Open\r\n        objStream.LoadFromFile filePath\r\n\r\n        \'Enviar el contenido al navegador\r\n        Response.BinaryWrite objStream.Read\r\n        objStream.Close\r\n        Set objStream = Nothing\r\n        Set objFSO = Nothing\r\n        Response.End\r\n\r\n    End If\r\n\r\n    Set fso = Nothing\r\nEnd Sub \r\n\r\nFunction EncriptingFile(filename)\r\n\r\n    Dim cmd,sFolder,file,keystore,jarPath,outputFile,lblmsg, exitCode\r\n\r\n    \'Ruta al archivo JAR, al archivo a cifrar y al keystore\r\n    sFolder = "C:\\ProgramData\\MySQL\\MySQL Server 5.7\\Uploads\\cifrado"    \r\n    jarPath =  "cifrado.jar"\r\n    file = sFolder & "\\" & filename\r\n    keystore =  "keystore/"\r\n\r\n    Set fso = CreateObject("Scripting.FileSystemObject")\r\n\r\n    If fso.FileExists(file) Then\r\n\r\n        \'Comandos shell\r\n        cmd = "cmd /c ""cd """ & sFolder & """ && ""C:\\Program Files (x86)\\Common Files\\Oracle\\Java\\java8path\\java"" -jar """ & jarPath & """ """ & Replace(filename,".txt","") & """ """ & keystore & """ "".txt"""""\r\n\r\n        \'Ejecutar el comando\r\n        Set shell = CreateObject("WScript.Shell")\r\n        exitCode = shell.Run(cmd, 1, True)\r\n\r\n        If exitCode <> 0 Then\r\n            lblmsg = "lbl_not_encripted_file"\r\n            \'Response.Write "Error ejecutando el comando. Código de salida: " & exitCode\r\n        Else\r\n            \'Leer el archivo de salida    \r\n            outputFile = Replace(file,".txt",".cif")\r\n\r\n            If fso.FileExists(outputFile) Then\r\n                lblmsg = "lbl_encripted_file"        \r\n            Else\r\n                lblmsg = "lbl_not_encripted_file"\r\n            End If\r\n        End If  \r\n\r\n    Else\r\n        lblmsg = "lbl_file_not_found"\r\n    End If\r\n\r\n\r\n    EncriptingFile = lblmsg\r\n\r\nEnd Function\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE RESPUESTAS DEL LADO DEL SERVIDOR SEGUN LA EVALUACIÓN DE LOS PARAMETROS RECIBIDOS\r\nIf sFile <> "" Then\r\n    GetFileExport sFile,sFormat\r\nEnd If\r\n\r\nSelect Case formtype\r\n    Case "export_data"\r\n\r\n        result = ExportData(sR_DateStart, sR_DateEnd,sR_ClinicID,sR_STypeDiary,sS_UserID,sFormat)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n\r\n    Case "show_data"\r\n\r\n        result = GetListExports(sR_DateStart, sR_DateEnd,sR_ClinicID,sR_STypeDiary,sS_UserID,sR_Limit,sR_Start)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n    \r\n    Case "confirm_export"\r\n\r\n        result = ConfirmExportID(sR_SExportID, sR_UserID)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n    \r\nEnd Select\r\n\r\n\'Se crean los scripts html y js para visualizar y darle funcionamiento a la página que se muestra con el report.\r\n%>\r\n\r\n<HTML>\r\n	<HEAD>\r\n			<META http-equiv="Content-Type" content="text/html; charset=windows-1252">   \r\n            <SCRIPT src="https://code.jquery.com/jquery-3.6.0.min.js"></SCRIPT> \r\n            <SCRIPT src="https://cdn.jsdelivr.net/npm/xlsx/dist/xlsx.full.min.js"></SCRIPT>                          \r\n            <STYLE>\r\n                .left {text-align:left;}\r\n                .right {text-align:right;}\r\n                .center {text-align:center;} \r\n                .pag {background-color:#f3f3f3; border-radius: 0px 0px 15px 15px; height:40px; width:98%; padding-top: 1px; display:flex; align-items: center;}\r\n                .label_singer {text-align:center; font-weight: bold; color: var(--flowww-primary-color);}\r\n                .label_title {text-align:left; font-weight: bold; color: #6E5EE0;}\r\n                .div_total {display: flex; justify-content: center; align-items: center; height:52px;width:90% !important;border-radius: 10px; background: #e2dff9; color:var(--flowww-primary-color); font-weight: bold;  margin:5px; font-family: DMSans, OpenSans, sans-serif;}\r\n                .spinner-container {position: fixed;top: 0;left: 0;width: 100%;height: 100%;background-color: rgba(0, 0, 0, 0.5); display: flex;justify-content: center;align-items: center;z-index: 9999;}\r\n                .spinner {border: 4px solid rgba(255, 255, 255, 0.3);border-top: 4px solid #ffffff;border-radius: 50%;width: 30px;height: 30px;animation: spin 1s linear infinite;}\r\n                .select_rows_pag {margin-top: 1px !important;width:15%;height:70% !important;}\r\n                .lbl_rows_pag {margin-top: 8px !important;width:30%;margin-left:60%;height:70% !important;}\r\n                .input-field.input-outlined > input[type="month"] {box-sizing: border-box;border: 1px solid #ced4da;border-radius: 10px;padding: 0 16px;height: 47px;width: 100%;font-family: DMSans, OpenSans, sans-serif;font-size: 14px;background-color: #fff;appearance: none;-webkit-appearance: none;cursor: pointer;}\r\n                .monthpicker + label {transform: translateY(-8px) scale(.8);transform-origin: 0 0;color: var(--flowww-primary-color);background: #fff;padding: 0 6px;left: 16px;top: 0;position: absolute;pointer-events: none;}\r\n                .__select-container {position: relative;width: 100%; padding: 5px; appearance: none;}\r\n                .__search_box {width: 100%; height:100%;}\r\n                .__options {font-family: DMSans, OpenSans, sans-serif;font-size:16px;position: absolute;width: 100%;max-height: 200px;overflow-y: auto;border: 1px solid #ccc;background: white;display:block;z-index: 9999;border-radius: 10px;}\r\n                .__option {padding: 8px;cursor: pointer; color: var(--flowww-primary-color); }\r\n                .__option:hover {background:#1967d2; color:#ffffff;}\r\n                .__not_valid {border-bottom: 2px solid red !important;}\r\n                .__multiselect {border-radius: .25rem !important;border: 0.5px solid lightgrey !important;height: 400px;overflow-y: scroll;padding-top: 10px;margin-top: -5px;box-sizing: border-box;z-index: 200;background-color: white;width: calc(100% - 2px);position: absolute;}\r\n                .__multiselect::-webkit-scrollbar {width: 8px;height: 8px;}\r\n                .__multiselect::-webkit-scrollbar-thumb, {background: #888;border-radius: 6px;}\r\n                .__multiselect::-webkit-scrollbar-thumb:hover {background: var(--grey-4-color);}\r\n                .__multiselect_option {display: block;padding: 6px 20px 6px;border-radius: 10px;}\r\n                .__multiselect_container_fieldset {padding-bottom: 4px;}\r\n                .__multiselect_container_name {text-align: left;border: 1px solid lightgrey;padding: 0 16px;width: calc(100% - .05rem)!important;border-radius: 10px;background: url(\'data:image/svg+xml, <svg  width="24px" height="24px"  xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="rgba(50, 46, 45, 0.2)" d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"  /></svg>\')!important;background-size: 24px!important;background-position: calc(100% - 6px) center!important;background-repeat: no-repeat!important;height: calc(3rem + 2px)!important;}\r\n                .__multiselect_none {display: none !important;}\r\n                .__multiselect_container {width: 100% !important;}\r\n                .__multiselect_container_fieldset>div+label {transform: translateY(-8px) scale(.8);transform-origin: 0 0;color: var(--flowww-primary-color);margin-top: -.1rem;left: 23px;background: #fff;border-left: 4px solid #fff;border-right: 4px solid #fff;}\r\n                .__multiselectfont{  font-family: DMSans, OpenSans, sans-serif;font-size:16px;}\r\n                #main_div {overflow:auto;}\r\n                @media print {#main_div {overflow:visible;}}\r\n                @keyframes spin {0% { transform: rotate(0deg); }100% { transform: rotate(360deg); }}\r\n            </STYLE> \r\n            <SCRIPT language="JavaScript" TYPE="text/javascript">\r\n                \r\n            function fInit(){}\r\n                            \r\n            function __pagesCmp(limit, start, rows){                    \r\n                \r\n                let newcurpage = 0,\r\n                    countpage = Math.ceil(rows/limit),\r\n                    tdatainfo_pag_cur = document.getElementById("tdatainfo_pag_cur"),\r\n                    tdatainfo_pag_current = document.getElementById("tdatainfo_pag_Current"),    \r\n                    tdatainfo_pag_prev = document.getElementById("tdatainfo_pag_Prev_li"),     \r\n                    tdatainfo_pag_next = document.getElementById("tdatainfo_pag_Next_li"); \r\n                \r\n                if(start == 0){\r\n                    newcurpage = 1;\r\n                    tdatainfo_pag_prev.setAttribute("CLASS","disabled");\r\n\r\n                    if(countpage > 1){\r\n                        tdatainfo_pag_next.classList.remove("disabled");\r\n                    }else {\r\n                        tdatainfo_pag_next.setAttribute("CLASS","disabled");\r\n                    }\r\n                    \r\n                }else{\r\n                    newcurpage = Math.ceil(start/limit) + 1; \r\n                    tdatainfo_pag_prev.classList.remove("disabled");\r\n                    \r\n                    if(newcurpage == countpage){\r\n                        tdatainfo_pag_next.setAttribute("CLASS","disabled");\r\n                    }\r\n                }                                            \r\n                tdatainfo_pag_current.setAttribute("data-curpage",newcurpage);\r\n                tdatainfo_pag_cur.textContent = ("<%=slbl_pagination%>").replace("###1###",newcurpage);  \r\n                tdatainfo_pag_cur.textContent = (tdatainfo_pag_cur.textContent).replace("###2###",countpage);\r\n            }\r\n\r\n            function fR_Fit_Sec_Report_iframe(tabla){           \r\n\r\n                // Se ajusta tamaño del marco del reporte con cada línea insertada     \r\n                if (tabla !== false){                        \r\n                    let row = tabla.rows[tabla.rows.length - 1],                            \r\n                        iSEC_REPORT_iframe = window.parent.document.getElementById("SEC_REPORT_iframe"),     \r\n                        currentHeightIFrame = parseInt(iSEC_REPORT_iframe.style.height, 10);\r\n                        currentHeightIFrameEnd = currentHeightIFrame + parseInt(row.offsetHeight, 10);  \r\n                    \r\n                    iSEC_REPORT_iframe.setAttribute("style", "height: " + currentHeightIFrameEnd +"px !important;");   \r\n                }\r\n            }\r\n\r\n            utilFunctions = {\r\n                onChangeDatePickerSearch:function(){\r\n                    const inputStart = document.getElementById(\'StatsStartDate\');\r\n                    const inputEnd   = document.getElementById(\'StatsEndDate\');\r\n\r\n                    inputStart.addEventListener(\'change\', function () {\r\n                    if (!this.value) return;\r\n\r\n                    const [year, month] = this.value.split(\'-\');\r\n\r\n                    // Último día del mes de StatsStartDate\r\n                    const lastDay = new Date(year, month, 0).getDate();\r\n                    this.value = `${year}-${month}-01`;\r\n                    inputEnd.value = `${year}-${month}-${String(lastDay).padStart(2, \'0\')}`;\r\n                    });\r\n                },\r\n                onChangeMonthPickerSearch:function(){\r\n                    const monthInput = document.getElementById("StatsMonth");\r\n\r\n                    // Establecer el valor máximo permitido como el mes actual\r\n                    const today = new Date();\r\n                    const year = today.getFullYear();\r\n                    const month = String(today.getMonth() + 1).padStart(2, \'0\'); // Enero = 0\r\n                    monthInput.max = `${year}-${month}`;\r\n\r\n                    // Validación adicional al cambiar el input\r\n                    monthInput.addEventListener("change", () => {\r\n                        const selectedMonth = monthInput.value;\r\n                        if (selectedMonth > monthInput.max) {\r\n                        alert("No se puede seleccionar un mes futuro.");\r\n                        monthInput.value = monthInput.max; // Opcional: vuelve al mes máximo permitido\r\n                        }\r\n                    });\r\n\r\n                }\r\n            }  \r\n            sortFunctions = {                \r\n                sortArrRows:function (rows,fieldIndex,order){\r\n                     \r\n                     rows.sort((a, b) => {\r\n                        let textA = a.cells[fieldIndex].innerText.toLowerCase(),\r\n                            textB = b.cells[fieldIndex].innerText.toLowerCase(),\r\n                            orderByType = "String";\r\n\r\n                        //Tipos de ordenaciones\r\n                        if(textA.includes("€") || typeof textA == "number" ){\r\n                            orderByType = "Number";\r\n                        }\r\n                        if(textA.includes("/") || typeof textA == "date" ){\r\n                            orderByType = "Date";\r\n                        }\r\n\r\n                        switch (orderByType) {\r\n                            case "Number":\r\n                                let floatA = parseFloat(((textA.replace("€","")).replace(".","")).replace(",",".")),\r\n                                    floatB = parseFloat(((textB.replace("€","")).replace(".","")).replace(",","."));\r\n                            \r\n                                if (order == "asc") {\r\n                                    return floatA - floatB; // Orden ascendente\r\n                                } else {\r\n                                    return floatB - floatA; // Orden descendente\r\n                                };\r\n\r\n                            case "Date":\r\n                                let dateA = getDateFromStringDMY(textA),\r\n                                    dateB = getDateFromStringDMY(textB); \r\n                            \r\n                                if (order == "asc") {\r\n                                    return dateA - dateB; // Orden ascendente\r\n                                } else {\r\n                                    return dateB - dateA; // Orden descendente\r\n                                };\r\n\r\n                            default:\r\n                                if (order == "asc") {\r\n                                    return textA.localeCompare(textB); // Orden ascendente\r\n                                } else {\r\n                                    return textB.localeCompare(textA); // Orden descendente\r\n                                }                            \r\n                        }\r\n                    \r\n                    });\r\n                    return rows;\r\n                },\r\n                sortArrRowsByGroups: function (rows,fieldIndex,order) {\r\n                    const result = [];\r\n                    let subgroup = [];\r\n                    \r\n                    rows.forEach(row => {\r\n                        if (row.cells[0].colSpan > 1 ) {\r\n                        \r\n                            if (subgroup.length > 0) {\r\n                                // Se ordena el subgrupo actual antes de agregarlo al resultado\r\n                                sortFunctions.sortArrRows(subgroup,fieldIndex,order);                                \r\n                                result.push(...subgroup);\r\n                                subgroup = []; // Reiniciar subgrupo\r\n                            }\r\n                            //Se agrega el marcador de inicio al resultado\r\n                            result.push(row);\r\n                        } else {\r\n                        //Se agrega el elemento al subgrupo actual\r\n                        subgroup.push(row);\r\n                        }\r\n                    });\r\n\r\n                    // Se ordenar y agrega el último subgrupo al resultado si existe\r\n                    if (subgroup.length > 0) {\r\n                        sortFunctions.sortArrRows(subgroup,fieldIndex,order);    \r\n                        result.push(...subgroup);\r\n                    }\r\n\r\n                    return result;\r\n                },\r\n                sortTable:function (__this,tableid,fieldIndex,hasGroup=false) {\r\n                    \r\n                    let order = "asc";\r\n\r\n                    switch(__this.textContent ){\r\n                        case "unfold_more": \r\n                            __this.textContent = "keyboard_arrow_up";\r\n                            order = "asc";\r\n                            break;\r\n                        case "keyboard_arrow_down": \r\n                            __this.textContent = "keyboard_arrow_up";\r\n                            order = "asc";\r\n                            break;\r\n                        case "keyboard_arrow_up": \r\n                            __this.textContent = "keyboard_arrow_down";\r\n                            order = "desc";\r\n                            break;\r\n                    }                \r\n                    \r\n                    // Se selecciona la tabla\r\n                    let table = document.getElementById(tableid),\r\n                        tbody = table.getElementsByTagName("tbody")[0];\r\n\r\n                    // Se convierte las filas a un array\r\n                    let rows = Array.from(tbody.rows),\r\n                        rowsOrded = [];\r\n\r\n                    //Se ordena las filas basándose en la columna que se desea ordenar\r\n                    if(hasGroup){\r\n                        rowsOrded = sortFunctions.sortArrRowsByGroups(rows,fieldIndex,order);\r\n                    }else {\r\n                        rowsOrded = sortFunctions.sortArrRows(rows,fieldIndex,order);\r\n                    }   \r\n\r\n                    // Reordena las filas en el cuerpo de la tabla\r\n                    tbody.innerHTML = "";\r\n                    rowsOrded.forEach(row => tbody.appendChild(row));\r\n\r\n                    // Selecciona todos los elementos <i> dentro de la tabla\r\n                    let icons = table.querySelectorAll("i");\r\n\r\n                    // Cambia el textContent de cada elemento <i> unfold_more para resetear la ordenación\r\n                    icons.forEach((icon, index) => {\r\n                        if(index != fieldIndex){\r\n                            icon.textContent = "unfold_more";\r\n                        }\r\n                    });\r\n                }\r\n            } \r\n\r\n            spinnerFunctions = {\r\n                showSpinner: function () {\r\n                    document.getElementById("spinnerContainer").style.display = "flex";\r\n                },\r\n                hideSpinner: function () {\r\n                    document.getElementById("spinnerContainer").style.display = "none";\r\n                }\r\n            }\r\n\r\n            actionFunctions= {\r\n\r\n                showData: function(nextpage=0){\r\n\r\n                    //Se muestra el spinner\r\n                    spinnerFunctions.showSpinner();\r\n\r\n                    //Variables auxiliares\r\n                    const iClinicID = document.getElementById("ClinicID").value;\r\n                    const iTypeDiaryID = document.getElementById("TypeDiaryID").value;\r\n                    const StatsMonth = "<%=filterByMonth%>";   \r\n                    let sStatsStartDate = "";\r\n                    let sStatsEndDate = "";\r\n\r\n                    if(StatsMonth){                        \r\n                        const sStatsMonth = document.getElementById("StatsMonth").value;\r\n                        const [year, month] = sStatsMonth.split("-");  \r\n\r\n                        // Inicio del mes\r\n                        sStatsStartDate = `${year}-${month}-01`;\r\n\r\n                        //Fecha actual\r\n                        const today = new Date();\r\n                        const currentYear  = today.getFullYear();\r\n                        const currentMonth = String(today.getMonth() + 1).padStart(2, \'0\');\r\n\r\n                        if (year == currentYear && month == currentMonth) {\r\n                            // Mes actual: fecha de hoy \r\n                            sStatsEndDate = today.toISOString().split(\'T\')[0];\r\n                        } else {\r\n                            // Otro mes: último día del mes\r\n                            const lastDay = new Date(year, month, 0).getDate();\r\n                            sStatsEndDate = `${year}-${month}-${String(lastDay).padStart(2, \'0\')}`;\r\n                        }\r\n\r\n                    }else {\r\n                        sStatsStartDate = document.getElementById("StatsStartDate").value;\r\n                        sStatsEndDate = document.getElementById("StatsEndDate").value;\r\n                    }\r\n                    \r\n                    const iRowsPag = document.getElementById("tdatainfo_numpag").value; \r\n                    let sR_Limit = iRowsPag;                  \r\n                    let sR_Start = 0;\r\n\r\n                    //Se determina la página actual \r\n                    let tdatainfo_pag_Current = document.getElementById("tdatainfo_pag_Current"),\r\n                        icurpage = tdatainfo_pag_Current.getAttribute("data-curpage");\r\n\r\n                    switch (nextpage) {\r\n                        case 1:  sR_Start = (parseInt(icurpage) * sR_Limit); \r\n                            break;\r\n                        case 2:  sR_Start = ((parseInt(icurpage)-2) * sR_Limit);\r\n                            break;\r\n                    } \r\n\r\n                    //Se evalúa que las fechas se encuentren en el rango de 1 año.\r\n                    if(sStatsStartDate != ""  && sStatsEndDate != ""){\r\n                        let dStatsStartDate = Date.parse(sStatsStartDate),\r\n                            dStatsEndDate = Date.parse(sStatsEndDate),\r\n                            diffTime = dStatsEndDate - dStatsStartDate,\r\n                            diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)),\r\n                            msgCheckDate = "";     \r\n\r\n                            if(dStatsStartDate > dStatsEndDate) { msgCheckDate = "<% = slbl_rpt_check_date %>"}                                                        \r\n                            if(diffDays > 365) {msgCheckDate = msgCheckDate + "<%=slbl_rpt_check_date_one_year%>"}                                                         \r\n                            if( msgCheckDate != ""){ alert(msgCheckDate); return;}\r\n                    }                                \r\n\r\n                    //Se reliza la petición al servidor\r\n                    $.ajax({\r\n                                url: "",\r\n                                method: "POST",\r\n                                dataType: "JSON",\r\n                                data: { form: "show_data",\r\n                                        ds:sStatsStartDate,\r\n                                        de:sStatsEndDate,\r\n                                        xcid:iClinicID,\r\n                                        tf:iTypeDiaryID,\r\n                                        st:sR_Start,\r\n                                        lm:sR_Limit                                \r\n                                    },\r\n                                success:function(data){\r\n                                        \r\n                                        // Se oculta el spinner\r\n                                        spinnerFunctions.hideSpinner();\r\n                                        \r\n                                        //Se establece tamaño estandar de SEC_REPORT_iframe\r\n                                        fR_Fit_Sec_Report_iframe(false); \r\n                                        \r\n                                        //Se obtienen los datos \r\n                                        let jsonString = JSON.stringify(data), \r\n                                            results = JSON.parse(jsonString).results,                                \r\n                                            totals = JSON.parse(jsonString).totals;                    \r\n\r\n                                        //Se obtienen la tabla html en la que se mostrarán los resultados\r\n                                        let table = document.getElementById("tdatainfo"),\r\n                                            tablebody = table.getElementsByTagName("tbody")[0];\r\n\r\n                                        //Se comprueba si hay resultado para mostrar\r\n                                        if (results.length == 0 ) {                                \r\n                                            tablebody.innerHTML = "";  \r\n                                            let row = document.createElement("tr");                                     \r\n                                            let  td_nodata = document.createElement("td");\r\n                                            td_nodata.setAttribute("class", "thCenterVertically");\r\n                                            td_nodata.setAttribute("colspan", "100%");\r\n                                            td_nodata.innerHTML = "<% = fsGetLabel("rep_without_results") %>"; \r\n                                            row.appendChild(td_nodata); \r\n                                            tablebody.appendChild(row);   \r\n                                            return;                \r\n                                        } \r\n                                        \r\n                                        // Si hay resultados se muestran \r\n                                        table.removeAttribute("hidden");                                \r\n                                        tablebody.innerHTML = "";\r\n                                \r\n                                        //Se determina la página activa y total de páginas de la petición\r\n                                        __pagesCmp(sR_Limit, sR_Start, totals[0].counttotal);\r\n                                \r\n                                        for (var i = 0; i < results.length; i++) {\r\n\r\n                                            //Se definen las columnas a mostrar en la tabla\r\n                                            let row = document.createElement("tr"),                                                                               \r\n                                                datetime = document.createElement("td"),\r\n                                                username = document.createElement("td"),\r\n                                                clinicname = document.createElement("td"),\r\n                                                datestart = document.createElement("td"),\r\n                                                dateend = document.createElement("td"),\r\n                                                typediary = document.createElement("td"),\r\n                                                confirmed = document.createElement("td");    \r\n\r\n                                            datetime.innerHTML = results[i].datetime;\r\n                                            username.innerHTML = results[i].username;\r\n                                            clinicname.innerHTML = results[i].clinicname;\r\n                                            datestart.innerHTML = results[i].datestart;\r\n                                            dateend.innerHTML = results[i].dateend;\r\n                                            typediary.innerHTML = results[i].typediary;\r\n\r\n                                            let exportid = results[i].id;                                             \r\n                                            let typeclass = (results[i].confirmed == "")?" btn__action_disable":" btn__action_confirm disabled";\r\n                                            let strclick = (results[i].confirmed == "")? \'onclick="actionFunctions.confirmImpSIRES(\'+exportid+\')"\':\'\';\r\n                                            let title = (results[i].confirmed == "") ? "<%=slbl_export_confirmed_min%>":"<%=slbl_export_confirmed%>";\r\n\r\n                                            confirmed.innerHTML = \'<a href="#" \'+strclick+\'><img src="images/action_delete.gif"></a>\';   \r\n                                            confirmed.setAttribute("class", "thCenterVertically btn__action"+typeclass);     \r\n                                            confirmed.setAttribute("title", title);     \r\n                                            confirmed.style.width="1%";\r\n                                            confirmed.style.align="center";                                                                       \r\n\r\n                                            //Se añaden las columnas a la fila a mostrar\r\n                                            row.appendChild(datetime);\r\n                                            row.appendChild(username);\r\n                                            row.appendChild(clinicname);\r\n                                            row.appendChild(datestart);\r\n                                            row.appendChild(dateend);\r\n                                            row.appendChild(typediary);\r\n                                            row.appendChild(confirmed);\r\n\r\n                                            //Se añade fila a la tabla\r\n                                            tablebody.appendChild(row);\r\n                                            table.style.tableLayout = "fixed";\r\n\r\n                                            // Se ajusta tamaño del marco del reporte con cada línea insertada\r\n                                            fR_Fit_Sec_Report_iframe(table); \r\n                                        }//for \r\n                                },//success\r\n                                error: function(xhr, status, error) {                                    \r\n                                    alert("Error:" + status + " " + error);\r\n                                    spinnerFunctions.hideSpinner();\r\n                                }\r\n\r\n                    });\r\n                },\r\n                exportData: function(format=0){\r\n\r\n                                        spinnerFunctions.showSpinner();\r\n\r\n                                        const iClinicID = document.getElementById("ClinicID").value;\r\n                                        const iTypeDiaryID = document.getElementById("TypeDiaryID").value;\r\n                                        const StatsMonth = "<%=filterByMonth%>";\r\n                                        let sStatsStartDate = "";\r\n                                        let sStatsEndDate = "";\r\n\r\n                                            if(StatsMonth){                        \r\n                                                const sStatsMonth = document.getElementById("StatsMonth").value;\r\n                                                const [year, month] = sStatsMonth.split("-");    \r\n                                                                    \r\n                                                // Inicio del mes\r\n                                                sStatsStartDate = `${year}-${month}-01`;\r\n\r\n                                                //Fecha actual\r\n                                                const today = new Date();\r\n                                                const currentYear  = today.getFullYear();\r\n                                                const currentMonth = String(today.getMonth() + 1).padStart(2, \'0\');\r\n\r\n                                                if (year == currentYear && month == currentMonth) {\r\n                                                    // Mes actual: fecha de hoy \r\n                                                    sStatsEndDate = today.toISOString().split(\'T\')[0];\r\n                                                } else {\r\n                                                    // Otro mes: último día del mes\r\n                                                    const lastDay = new Date(year, month, 0).getDate();\r\n                                                    sStatsEndDate = `${year}-${month}-${String(lastDay).padStart(2, \'0\')}`;\r\n                                                }\r\n                                            }else {\r\n                                                sStatsStartDate = document.getElementById("StatsStartDate").value;\r\n                                                sStatsEndDate = document.getElementById("StatsEndDate").value;\r\n                                            }\r\n\r\n                                        //Se evalúa que las fechas se encuentren en el rango de 1 año.\r\n                                        if(sStatsStartDate != ""  && sStatsEndDate != ""){\r\n                                            let dStatsStartDate = Date.parse(sStatsStartDate),\r\n                                                dStatsEndDate = Date.parse(sStatsEndDate),\r\n                                                diffTime = dStatsEndDate - dStatsStartDate,\r\n                                                diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)),\r\n                                                msgCheckDate = "";     \r\n\r\n                                                if(dStatsStartDate > dStatsEndDate) { msgCheckDate = "<% = slbl_rpt_check_date %>"}                                                        \r\n                                                if(diffDays > 365) {msgCheckDate = msgCheckDate + "<%=slbl_rpt_check_date_one_year%>"}                                                         \r\n                                                if( msgCheckDate != ""){ alert(msgCheckDate); return;}\r\n                                        }\r\n                            \r\n                                        //Se realiza la petición al servidor\r\n                                        $.ajax({\r\n                                                url: "",\r\n                                                method: "POST",\r\n                                                dataType: "JSON",\r\n                                                data: { \r\n                                                    form: "export_data",\r\n                                                    ds:sStatsStartDate,\r\n                                                    de:sStatsEndDate,\r\n                                                    xcid:iClinicID,\r\n                                                    tf:iTypeDiaryID                                   \r\n                                                    },\r\n                                                success:function(data){  \r\n\r\n                                                    spinnerFunctions.hideSpinner();   \r\n\r\n                                                    //Se obtienen los datos enviados por la petición                                        \r\n                                                    let jsonString = JSON.stringify(data), \r\n                                                        results = JSON.parse(jsonString).results; \r\n\r\n                                                    alert(results[0].msg + "\\n", results[0].msgencript);\r\n                                                    actionFunctions.showData();\r\n\r\n                                                    if(results[0].success==1 && results[0].filename!=""){                                                               \r\n                                                        \r\n                                                        let ObjHref = new URL(window.location.href);\r\n                                                        ObjHref.searchParams.set("file", results[0].filename);           \r\n                                                        ObjHref.searchParams.set("ft",format );           \r\n                                                        window.location.href = ObjHref.href; \r\n                                                    }\r\n\r\n                                                },//success\r\n                                                error: function(xhr, status, error) {\r\n                                                        spinnerFunctions.hideSpinner(); \r\n                                                        alert("Error:" + status + " " + error);\r\n                                                    }\r\n                                        });\r\n\r\n                                        //}\r\n                \r\n                \r\n                },\r\n                confirmImpSIRES: function (exportid){ \r\n                    let result = confirm("Se procederá a confirmar el registro como importado en el SIRES. No podrá generar más exportaciones del periodo seleccionado. Pulse ACEPTAR para confirmar el registro como importado al SIRES.");\r\n                    if (result) {	\r\n                        //Se realiza la petición al servidor\r\n                                $.ajax({\r\n                                        url: "",\r\n                                        method: "POST",\r\n                                        dataType: "JSON",\r\n                                        data: { form: "confirm_export",\r\n                                                eid:exportid                              \r\n                                              },\r\n                                        success:function(data){  \r\n\r\n                                            spinnerFunctions.hideSpinner();   \r\n\r\n                                            //Se obtienen los datos enviados por la petición                                        \r\n                                            let jsonString = JSON.stringify(data), \r\n                                                results = JSON.parse(jsonString).results; \r\n\r\n                                            alert(results[0].msg);\r\n                                            actionFunctions.showData();\r\n\r\n                                        },//success\r\n                                        error: function(xhr, status, error) {\r\n                                                spinnerFunctions.hideSpinner(); \r\n                                                alert("Error:" + status + " " + error);\r\n                                            }\r\n                                }); \r\n                    }\r\n                }\r\n\r\n            }\r\n\r\n            $(document).ready(function() {            \r\n                const typeform = "<%=sReportPar1%>"; \r\n                const heightframe = "<%=sHeightframe%>"; \r\n\r\n                var iSEC_REPORT_iframe = window.parent.document.getElementById("SEC_REPORT_iframe");\r\n                iSEC_REPORT_iframe.setAttribute("style", "height: " + heightframe + " !important;");  \r\n                iSEC_REPORT_iframe.parentElement.style.padding="0px";    \r\n                \r\n                spinnerFunctions.showSpinner();\r\n                actionFunctions.showData();\r\n\r\n                const StatsMonth = "<%=filterByMonth%>";\r\n                if(StatsMonth){ \r\n                    utilFunctions.onChangeMonthPickerSearch();                    \r\n                }else{\r\n                    utilFunctions.onChangeDatePickerSearch();\r\n                }\r\n\r\n            });\r\n\r\n            </SCRIPT>\r\n        </HEAD>\r\n\r\n    <BODY>        \r\n        <DIV class="main__title"><%=slbl_ReportName%></DIV>\r\n        <DIV CLASS="spinner-container" id="spinnerContainer" style="display: none;"><DIV CLASS="spinner"></DIV></DIV>\r\n        <DIV CLASS="main__container">\r\n              <FORM ID="FilterRegistryPanel">\r\n                <DIV CLASS="row">\r\n                    <DIV CLASS="col s12 m12 l12 input-field input-outlined">\r\n                        <FIELDSET CLASS="text_7">\r\n                            <LEGEND><%=fsGetLabel("lbl_filters")%></LEGEND>                            \r\n                                <DIV CLASS="col s12 m12 l12">   \r\n                                    <% If filterByMonth then %>         \r\n                                        <DIV CLASS="input-field input-outlined col s12 m4 l4">\r\n                                            <SELECT ID="ClinicID"><% Response.Write GetSelectClinics(sS_ClinicID)%></SELECT>\r\n                                            <LABEL FOR="ClinicID"><% = fsGetLabel("lbl_clinic")%></LABEL>\r\n                                        </DIV>\r\n                                        <DIV CLASS="input-field input-outlined col s12 m4 l4">\r\n                                            <SELECT ID="TypeDiaryID"><% Response.Write GetSelectTypeDiary(1)%></SELECT>\r\n                                            <LABEL FOR="TypeDiaryID"><% = fsGetLabel("lbl_type_diary")%></LABEL>\r\n                                        </DIV>\r\n                                        <DIV CLASS="input-field input-outlined col s12 m4 l4">\r\n                                            <INPUT id="StatsMonth" CLASS="monthpicker" type="month" value=<% = sR_Month %>>\r\n                                            <LABEL FOR="StatsMonth"><% = fsGetLabel("lbl_month")%></LABEL>\r\n                                        </DIV>                                        \r\n                                    <% Else %>    \r\n                                        <DIV CLASS="input-field input-outlined col s12 m3 l3">\r\n                                            <SELECT ID="ClinicID"><% Response.Write GetSelectClinics(sS_ClinicID)%></SELECT>\r\n                                            <LABEL FOR="ClinicID"><% = fsGetLabel("lbl_clinic")%></LABEL>\r\n                                        </DIV>\r\n                                        <DIV CLASS="input-field input-outlined col s12 m3 l3">\r\n                                            <SELECT ID="TypeDiaryID"><% Response.Write GetSelectTypeDiary(1)%></SELECT>\r\n                                            <LABEL FOR="TypeDiaryID"><% = fsGetLabel("lbl_type_diary")%></LABEL>\r\n                                        </DIV>\r\n                                        <DIV CLASS="input-field input-outlined col s12 m3 l3">\r\n                                            <INPUT id="StatsStartDate" CLASS="datepicker" type="date" value=<% = sR_DateStart %>>\r\n                                            <LABEL FOR="StatsStartDate"><% = fsGetLabel("lbl_date_ini")%></LABEL>\r\n                                        </DIV>\r\n                                        <DIV CLASS="input-field input-outlined col s12 m3 l3">\r\n                                            <INPUT id="StatsEndDate" CLASS="datepicker" type="date" value=<% = sR_DateEnd%> readonly>\r\n                                            <LABEL FOR="StatsEndDate"><% = fsGetLabel("lbl_date_fin")%></LABEL>\r\n                                        </DIV>   \r\n                                    <% End IF %>                                                              \r\n                                </DIV>                                                                                             \r\n                        </FIELDSET>\r\n                    </DIV>     \r\n                 </DIV> \r\n                <DIV CLASS="row">\r\n                    <DIV CLASS="col s12 m6 5"></DIV>\r\n                    <DIV CLASS="col s12 m6 5" STYLE="text-align: right; margin-button:10px">\r\n                        <%                      \r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""javascript:parent.fBack();"" title="""  & slbl_rpt_go_back & """>" & slbl_go_back & "</BUTTON>")\r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.exportData(0);"" title=""" & slbl_export & """>" & slbl_export & "</BUTTON>")\r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.exportData(1);"" title=""" & slbl_exportar_file_sires & """>" & slbl_exportar_file_sires & "</BUTTON>")\r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__primary btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.showData();"" title="""  & slbl_search_for & """>" & slbl_search_for & "</BUTTON>")\r\n                        %>\r\n                    </DIV>       \r\n                </DIV>\r\n              </FORM>\r\n            </DIV>\r\n            <DIV CLASS="main__container">\r\n                <DIV class="main__section_title"><%=slbl_registry_exports%></DIV>\r\n                <DIV CLASS="table__responsive table__container">\r\n                    <TABLE id="tdatainfo" CLASS="table__list highlight" cellpadding="0" cellspacing="0" style="height: auto;">\r\n                        <THEAD>\r\n                            <TR style="height:65px;">                                              \r\n                            <%\r\n                                Response.Write("<TH title=""" & slbl_date &""" CLASS=""thWithSort thCenterVertically thIconGray"" STYLE=""width:10%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_date & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',0,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_user &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:15%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_user & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',1,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_clinic &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:15%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_clinic & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_date_ini &""" CLASS=""thWithSort thCenterVertically thIconGray"" STYLE=""width:10%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_date_ini & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',0,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_date_fin &""" CLASS=""thWithSort thCenterVertically thIconGray"" STYLE=""width:10%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_date_fin & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',0,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_type_diary &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:13%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_type_diary & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_export_confirmed &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:5%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_export_confirmed_min & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                            %>\r\n                            </TR>\r\n                        </THEAD>\r\n                        <TBODY  style="height: auto;">                    \r\n                        <%\r\n                        If Not iLoadData Then\r\n                            Response.Write("<TR HEIGHT=""12"">")\r\n                            Response.Write("<TD CLASS=""thCenterVertically td_date"" COLSPAN=""100%"">" & fsGetLabel("rep_without_results") &"</TD>")       \r\n                            Response.Write("</TR>") \r\n                        End If \r\n                        %>                    \r\n                        </TBODY>\r\n                    </TABLE>\r\n                </DIV>	\r\n                <DIV id="tdatainfo_pag" name="tdatainfo_pag" CLASS="row pag">\r\n                    <ul CLASS="pagination" style="margin-top: -2px !important;width: 85% !important;">\r\n                        <li id="tdatainfo_pag_Prev_li" CLASS="disabled"><a id="tdatainfo_pag_Prev" name="tdatainfo_pag_Prev" href="javascript:actionFunctions.showData(2);" tabindex="-1"><i CLASS="material-icons">chevron_left</i></a></li>\r\n                        <li CLASS="active"><a id="tdatainfo_pag_cur" name="tdatainfo_pag_cur" align="center" style="font-size:120%;">Página <%=CurPag%> de <%=icountpage%></a></li>\r\n                        <li id="tdatainfo_pag_Next_li" CLASS="waves-effect"><a id="tdatainfo_pag_Next" name="tdatainfo_pag_Next" href="javascript:actionFunctions.showData(1);"><i CLASS="material-icons">chevron_right</i></a></li>\r\n                        <li CLASS="waves-effect"><a id="tdatainfo_pag_Current" name="tdatainfo_pag_Current" href="" data-curpage="1"></a></li>\r\n                    </ul>\r\n                    <LABEL FOR="tdatainfo_numpag" CLASS="lbl_rows_pag"><%=slbl_show_rows%></LABEL>\r\n                    <select id="tdatainfo_numpag" onchange="actionFunctions.showData(0)" CLASS="select_rows_pag">\r\n                        <option value="10">10</option>\r\n                        <option value="50">50</option>\r\n                        <option value="100">100</option>\r\n                    </select>\r\n                    \r\n                </DIV>\r\n            </DIV>	 \r\n\r\n      </DIV>\r\n        \r\n	</BODY>\r\n</HTML>\r\n\r\n', NULL, NULL, 0);
REPLACE INTO `x_config_reports` (`ReportName`, `ReportClinicID`, `ReportTechDesc`, `ReportTechVersion`, `ReportText`, `ReportGroup`, `ReportGroupOrder`, `ReportInvisible`) VALUES ('SIRES_FORM', 0, 'Consultas (SIRES)', '1', '<!--#include virtual="/_include/report_head.asp"-->\r\n\r\n<%\r\n\' ===============================================================================================\r\n\' FLOWww System for Aesthetic Clinics                         Copyright 2024 Integra Digital S.L.\r\n\' http://www.integradigital.com                                           info@integradigital.com\r\n\'\r\n\' INFORME: Integración con el SIRES - Sistema de Registro electrónico de salud en MX (sires_form)\r\n\'\r\n\' @Created: 31/03/2025\r\n\' @Last Update: 02/02/2025\r\n\' @HS:22055276319. Conciliación de requisitos y puesta en marcha.\r\n\' @Autor: ARA. \r\n\' @Description: Se conforma de 3 bloque visuales.1 - Regisro de consultas.  2 - Datos del paciente 3 - Formulario de consulta\r\n\' ===============================================================================================\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE ETIQUETAS. Se determinan las etiquetas por bloques.\r\n\r\n\'ETIQUETAS GENERALES\r\n  slbl_sires_fill_data_section = fsGetLabel("lbl_sires_fill_data_section") \r\n  slbl_select_one_m = fsGetLabel("lbl_select_one_m") \r\n  slbl_multiselect_placeholder = "(" & fsGetLabel("lbl_multiselect_placeholder") & ")"\r\n  slbl_all_m = fsGetLabel("lbl_all_m") \r\n  slbl_search_for = fsGetLabel("lbl_search_for") \r\n  slbl_insert_option = fsGetLabel("lbl_insert_option") \r\n  slbl_error_format = "error de formato"\r\n  slbl_update = fsGetLabel("lbl_save")\r\n  slbl_ReportName_Bucal = fsGetLabel("lbl_sires_form")\r\n  slbl_ReportName_CE = fsGetLabel("lbl_sires_form_ce")\r\n  slbl_InvalidFields = fsGetLabel("lbl_invalid_field")\r\n  slbl_delete = fsGetLabel("lbl_delete")\r\n  slbl_check_exists_diaryondate = fsGetLabel("lbl_check_exists_diaryondate")\r\n  slbl_not_allowed_stafftype = fsGetLabel("lbl_not_allowed_stafftype")\r\n  slbl_update_data_clients = fsGetLabel("lbl_update_data_clients")\r\n  slbl_update_data_users = fsGetLabel("lbl_update_data_users")\r\n  slbl_invalid_user_curp = fsGetLabel("lbl_invalid_user_curp")\r\n  slbl_invalid_fields = fsGetLabel("lbl_invalid_fields")\r\n  slbl_notice_before_delete = fsGetLabel("lbl_notice_before_delete")\r\n  slbl_load_spinner = fsGetLabel("lbl_load_spinner")\r\n  slbl_press_enter = fsGetLabel("lbl_press_enter")\r\n  slbl_check_curp = fsGetLabel("lbl_check_curp")\r\n  \r\n\'ETIQUETAS BLOQUE 1 y 3\r\n  slbl_save = fsGetLabel("lbl_save") \r\n  slbl_sires_fill_data = fsGetLabel("lbl_sires_fill_data") \r\n\r\n\'ETIQUETAS BLOQUE 2\r\n  slbl_searcher = fsGetLabel("lbl_searcher") \r\n  slbl_go_back = fsGetLabel("lbl_go_back")\r\n  slbl_search_for = fsGetLabel("lbl_search_for")  \r\n  slbl_sires_diary_date = fsGetLabel("lbl_sires_diary_date")  \r\n  slbl_sires_service = fsGetLabel("lbl_sires_service")  \r\n  slbl_see = fsGetLabel("lbl_see+")  \r\n  slbl_assistant = fsGetLabel("lbl_assistant")  \r\n  slbl_clinic = fsGetLabel("lbl_clinic")  \r\n  slbl_registry_date = fsGetLabel("lbl_registry_date")  \r\n  slbl_registry_date_export = fsGetLabel("lbl_registry_date_export")  \r\n  slbl_add_new_diary = fsGetLabel("lbl_add_new_diary")  \r\n  slblPagination = fsGetLabel("lbl_pagination") \r\n\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE VARIABLE AUXILIARES\r\n\r\n\'Se determina qué vista es la que se pretende mostrar. Reducida o con listados de consultas.\r\nminView = true \' Reducida\r\n\r\n\'Se obtienen los parámetros enviados por GET (URL) utilizado para la exportación csv.\r\nIf Request.ServerVariables("REQUEST_METHOD") = "GET" Then\r\n  sReportName =  fsCheckString(Request.QueryString("name"), "", "", 1, 128, True, "", False)\r\n  sReportTitle = fsCheckString(Request.QueryString("tit"), "", "", 0, 0, True, "", False)    \r\n  sReportPar1 = fsCheckString(Request.QueryString("par1"), "", "", 0, 0, True, "", False)    \r\nEnd If\r\n\r\n\'Se obtienen los parámetros enviados por POST (AJAX) utilizado para peticiones .\r\nIf Request.ServerVariables("REQUEST_METHOD") = "POST" Then\r\n     \r\n  \'Limpiamos la respuesta\r\n  Response.Clear()\r\n  \r\n  \'Creamos el objeto JSON de respuesta\r\n  Set objJSON = CreateObject("Scripting.Dictionary")\r\n\r\n  \'Parámetros enviados POST\r\n  formtype = Request.Form("form")\r\n  sR_DateStart = Request.Form("ds") \r\n  sR_DateEnd = Request.Form("de") \r\n  sR_ClinicID = Request.Form("xcid") \r\n  sR_ClientID = Request.Form("cid") \r\n  sR_UserID = Request.Form("uid") \r\n  sR_ServiceSearch = Request.Form("ss") \r\n  sR_ServiceID = Request.Form("si") \r\n  sR_Limit = Request.Form("lm") \r\n  sR_Start = Request.Form("st") \r\n  sR_SDiaryID = Request.Form("did") \r\n  sR_SDiaryDate = Request.Form("dd") \r\n  sR_SFilterText = Request.Form("fil") \r\n  sR_STypeForm = Request.Form("tf") \r\n  sR_SSex = Request.Form("sx") \r\n  sR_SBirthDate = Request.Form("bd") \r\n  sR_SRelationTmp = Request.Form("rt") \r\n  sR_SData = Request.Form("dt") \r\n    \r\nEnd If\r\n\r\n\'Se obtienen las variables de sesión necesarias\r\nsS_ClinicID = CStr(Session(SES_USER_CLINICID))\r\nsS_UserID = CStr(Session(SES_USERID))\r\n\r\n\'Se determina el tipo de formulario a mostrar\r\nIf sReportPar1 = "" Then\r\n    sSTypeDiary = sR_STypeForm\r\nElse\r\n    sSTypeDiary = sReportPar1\r\nEnd If\r\n\r\n\'Se determina el tipo de personal con acceso según el tipo de consulta\r\nsS_StaffTypeByDiary = GetStaffTypeByDiary(sSTypeDiary)\r\nsCluesFrendly = GetCluesFrendly(sS_ClinicID)\r\nsAbrTipAndSub = GetDataUnitInSires(sS_ClinicID)\r\nsServiceValues = GetServiceJsonValues()\r\n\r\n\'Se determina el tipo de personal y CURP del usuario activo.\r\nsStaffTypeAndCurp = GetStaffTypeAndCurp(sS_UserID)\r\narrStaffTypeAndCurp = Split(sStaffTypeAndCurp,"|")\r\nsS_StaffType=arrStaffTypeAndCurp(0)\r\nsUserCurp=arrStaffTypeAndCurp(1)\r\n\r\n\'Se guarda URL y nombre del reporte\r\nSession("prev_url") = Request.ServerVariables("PATH_INFO")   \r\nSession("report_name") = sReportName\r\n\r\n\'Variables auxiliares para identificar carga de datos.\r\ndCurrentDate = Date()\r\n\r\nIf sR_DateStart = "" Then\r\n    \'sR_DateStart = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2) & "-01" \r\n    sR_DateStart = "2025-01-01"\r\nEnd If\r\n\r\nIf sR_DateEnd = "" Then\r\n    sR_DateEnd = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2) & "-" & Right("0" & Day(dCurrentDate), 2)\r\nEnd If\r\n\r\nIf sR_SDiaryDate = "" Then\r\n    sR_SDiaryDate = Year(dCurrentDate) & "-" & Right("0" & Month(dCurrentDate), 2) & "-" & Right("0" & Day(dCurrentDate), 2)\r\nEnd If\r\n\r\nIf sReportPar1 = 1 then\r\n    slbl_ReportName = slbl_ReportName_Bucal\r\n    sHeightframe = "6200px"\r\nElse\r\n    slbl_ReportName = slbl_ReportName_CE\r\n    sHeightframe = "2495px"\r\nEnd If\r\n\r\n\'Id de la consulta que se muesta en el formulario. Inicialmente se asume que el formulario corresponde a una nueva consulta.\r\niDiarySGID = 0\r\niDiaryGIdExport = 0\r\n\r\n\'Paginado\r\nCurPag = 0\r\nicountpage = 0\r\n\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE FUNCIONES AUXILIARES\r\n\r\n\'Se obtiene la cadena JSON con los datos de las variables por cliente\r\nFunction ShowClientData(clientid, diaryid,diarygdate,serviceid,typeform,clinicid,userid)\r\n\r\n    Dim jsonResult\r\n    Dim iCount \r\n\r\n    jsonResult = "{" & vbCrLf\r\n\r\n    \'0. Se determina si los datos minimos de personas (cliente y usuarios están correctos)\r\n    Set rsPersonsData = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rsPersonsData.Open "CALL __fRptCheckData_SIRES_CheckPersonalData(\'"& userid &"\',\'" & clientid & "\',\'" & diarygdate &"\')", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    If Not (rsPersonsData.EOF) Then\r\n        iUserValidated = rsPersonsData("UserValidated")\r\n        iClientValidated =  rsPersonsData("ClientValidated")\r\n        sUserMsgReturned = rsPersonsData("UserMsgReturned")\r\n        sClientMsgReturned =  rsPersonsData("ClientMsgReturned")\r\n        iClientLockData =  rsPersonsData("ClientLockData")\r\n    Else \r\n        iUserValidated=0\r\n        iClientLockData=0\r\n        iClientValidated=0\r\n        sUserMsgReturned=""\r\n        sClientMsgReturned=""\r\n    End If\r\n\r\n    jsonResult = jsonResult &  """personaldata"" : [{" & vbCrLf \r\n    jsonResult = jsonResult &  """uservalidated"" : """ & iUserValidated & """," & vbCrLf\r\n    jsonResult = jsonResult &  """usermsgreturned"" : """ & sUserMsgReturned & """," & vbCrLf\r\n    jsonResult = jsonResult &  """clientlockdata"" : """ & iClientLockData & """," & vbCrLf\r\n    jsonResult = jsonResult &  """clientvalidated"" : """ & iClientValidated & """," & vbCrLf\r\n    jsonResult = jsonResult &  """clientmsgreturned"" : """ & sClientMsgReturned & """" & vbCrLf\r\n    jsonResult = jsonResult &  "}],"\r\n    \r\n    rsPersonsData.Close: Set rsPersonsData = Nothing \r\n\r\n    \'1. Se obtienen las variables del cliente y consulta especificada\r\n    Set rsData = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rsData.Open "CALL __fRptGetData_SIRES_ClientData(\'" & clientid & "\',\'" & diaryid & "\',\'" & diarygdate & "\',\'" & serviceid & "\',\'" & typeform & "\',\'" & clinicid & "\',\'" & userid & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        \r\n    jsonResult = jsonResult & """results"" : [" & vbCrLf \r\n\r\n    \'Contador de iteraciones para saber cuando es la 1 iteración.            \r\n    iCount = 0      \r\n\r\n    Do While Not (rsData.EOF) \r\n\r\n        \'Se escribe el primer objeto JSON.\r\n        If iCount = 0 Then\r\n          jsonResult = jsonResult & "{" & vbCrLf                    \r\n        Else\r\n          jsonResult = jsonResult & "," & vbCrLf & "{" & vbCrLf\r\n        End If \r\n\r\n        \'Se determina el contador de filas\r\n        iCount=iCount + 1 \r\n\r\n        \'Atributos del objeto JSON  \r\n        jsonResult = jsonResult &  """fieldid"" : """ & rsData("FieldID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldname"" : """ & rsData("FieldName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldesc"" : """ & rsData("FieldDesc") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldsectionid"" : """ & rsData("FieldSectionID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldtypeview"" : """ & rsData("FieldTypeView") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldjsonvalues"" : """ & rsData("FieldJSONValues") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldcheckfn"" : """ & rsData("FieldCheckFn") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldcheckfndesc"" : """ & rsData("FieldCheckFnDesc") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fielddefaultvalue"" : """ & rsData("FieldDefaultValue") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldmandatory"" : """ & rsData("FieldMandatory") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldvalue"" : """ & rsData("FieldValue") & """" & vbCrLf\r\n        jsonResult = jsonResult &  "}"\r\n        rsData.MoveNext\r\n    Loop\r\n\r\n    \'Se finaliza arreglo de registros.\r\n    jsonResult = jsonResult & "]," & vbCrLf   \r\n\r\n    \'Cierre el RecordSet.\r\n    rsData.Close: Set rsData = Nothing  \r\n\r\n    \'2. Se obtienen las secciones en las que se devide las variables\r\n    Set rs0Data = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rs0Data.Open "SELECT FieldSectionID, FieldSectionDesc, FieldSectionCheckFn FROM __sires_x_config_field_section WHERE FieldSectionDisabled=0 AND FieldSectionTypeData<2 ORDER BY FieldSectionOrder ASC;", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        \r\n    jsonResult = jsonResult &  """sections"" : [" & vbCrLf \r\n\r\n    \'Contador de iteraciones para saber cuando es la 1 iteración.            \r\n    iCount = 0      \r\n\r\n    Do While Not (rs0Data.EOF) \r\n\r\n        \'Se escribe el primer objeto JSON.\r\n        If iCount = 0 Then\r\n          jsonResult = jsonResult & "{" & vbCrLf                    \r\n        Else\r\n          jsonResult = jsonResult & "," & vbCrLf & "{" & vbCrLf\r\n        End If \r\n\r\n        \'Se determina el contador de filas\r\n        iCount=iCount + 1 \r\n\r\n        \'Atributos del objeto JSON  \r\n        jsonResult = jsonResult &  """fieldsectionid"" : """ & rs0Data("FieldSectionID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldsectiondesc"" : """ & rs0Data("FieldSectionDesc") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """fieldsectioncheckfn"" : """ & rs0Data("FieldSectionCheckFn") & """" & vbCrLf\r\n        jsonResult = jsonResult &  "}"\r\n        rs0Data.MoveNext\r\n    Loop\r\n\r\n        \'Se finaliza arreglo de registros.\r\n        jsonResult = jsonResult & "]," & vbCrLf   \r\n\r\n        \'Cierre el RecordSet.\r\n        rs0Data.Close: Set rs0Data = Nothing \r\n\r\n    \'3. Se obtiene el identificador de la consulta\r\n    Set rsDiaryData = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rsDiaryData.Open "SELECT sdg.SDiaryGID, sdg.SDiaryGIdExport, c.ClientLockData, IFNULL((SELECT COUNT(SDiaryGID) FROM __sires_diary_gen WHERE SDiaryGClientID=" & clientid & " AND SDiaryGID!=" & diaryid & " ),0) AS TotalSDiaryGID FROM __sires_diary_gen sdg INNER JOIN clients c ON c.ClientID=sdg.SDiaryGClientID WHERE sdg.SDiaryGID=" & diaryid & " OR ((sdg.SDiaryGClientID=" & clientid & " AND sdg.SClinicID=" & clinicid & " AND sdg.SDiaryGDate=\'" & diarygdate & "\' AND FIND_IN_SET(" & serviceid & ",sdg.SDiaryGServiceID)>0)) LIMIT 1;", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    iTotalSDiaryGID = 0\r\n\r\n    If Not (rsDiaryData.EOF) Then\r\n        iDiarySGID = rsDiaryData("SDiaryGID")\r\n        iDiaryGIdExport = rsDiaryData("SDiaryGIdExport")\r\n        iClientLockData = rsDiaryData("ClientLockData")\r\n        iTotalSDiaryGID = rsDiaryData("TotalSDiaryGID")\r\n    End If\r\n\r\n    jsonResult = jsonResult &  """diarydata"" : [{" & vbCrLf \r\n    jsonResult = jsonResult &  """clientlockdata"" : """ & iClientLockData & """," & vbCrLf\r\n    jsonResult = jsonResult &  """totaldiarygid"" : """ & iTotalSDiaryGID & """," & vbCrLf\r\n    jsonResult = jsonResult &  """diarysgid"" : """ & iDiarySGID & """," & vbCrLf\r\n    jsonResult = jsonResult &  """diarysgidexport"" : """ & iDiaryGIdExport & """" & vbCrLf\r\n    jsonResult = jsonResult &  "}]"\r\n    \r\n    rsDiaryData.Close: Set rsDiaryData = Nothing \r\n        \r\n    \'Se finaliza cadena JSON\r\n    jsonResult = jsonResult & "}" & vbCrLf  \r\n    \r\n    \' Si no se encuentra la cadena\r\n    ShowClientData = jsonResult\r\n\r\nEnd Function\r\n\r\n\'Se muestra el listado de consutas del cliente\r\nFunction ShowRegistryData(clientId,datestart,dateend,typeform,serviceid,limit,start)\r\n\r\n    Dim jsonResult\r\n    Dim iCount \r\n\r\n    jsonResult = "{" & vbCrLf\r\n    \r\n    \'PENDIENTE - obtener registro de consultas de un cliente para una fecha determinada, de las clínicas habilitadas para el ussuario activo. Mostrar todas las consultas solo permitir modificar las de las clinicas que tienen acceso el cliente activo.\r\n    Set rs1Data = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rs1Data.Open "CALL __fRptGetData_SIRES_RegistryData(\'" & clientid & "\',\'" & datestart & "\',\'" & dateend & "\',\'" & typeform & "\',\'" & serviceid & "\',\'" & limit & "\',\'" & start & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    jsonResult = jsonResult & """results"" : [" & vbCrLf \r\n\r\n    \'Contador de iteraciones para saber cuando es la 1 iteración.            \r\n    iCount = 0      \r\n\r\n    Do While Not (rs1Data.EOF) \r\n\r\n        \'Se escribe el primer objeto JSON.\r\n        If iCount = 0 Then\r\n          jsonResult = jsonResult & "{" & vbCrLf                    \r\n        Else\r\n          jsonResult = jsonResult & "," & vbCrLf & "{" & vbCrLf\r\n        End If \r\n\r\n        \'Se determina el contador de filas\r\n        iCount=iCount + 1 \r\n\r\n        \'Atributos del objeto JSON  \r\n        jsonResult = jsonResult &  """diarygid"" : """ & rs1Data("SDiaryGID") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """diarydate"" : """ & rs1Data("SDiaryGDate") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """clinicname"" : """ & rs1Data("ClinicName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """service"" : """ & rs1Data("ServiceName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """diarygusername"" : """ & rs1Data("UserName") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """diarygdatetime"" : """ & rs1Data("SDiaryGDateTime") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """diarygdatetimeexport"" : """ & rs1Data("SExportDateTime") & """" & vbCrLf\r\n        jsonResult = jsonResult &  "}"\r\n        rs1Data.MoveNext\r\n    Loop\r\n\r\n    \'Se finaliza arreglo de registros.\r\n    jsonResult = jsonResult & "]," & vbCrLf   \r\n\r\n    \'Cierre el RecordSet.\r\n    rs1Data.Close: Set rs1Data = Nothing  \r\n\r\n    \'Se obtiene el total de registros para definir el paginado\r\n    limit = 429496729\r\n    start = 0\r\n    Set rsDataTotal = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rsDataTotal.Open "CALL __fRptGetData_SIRES_RegistryDataTotal(\'" & clientid & "\',\'" & datestart & "\',\'" & dateend & "\',\'" & typeform & "\',\'" & serviceid & "\',\'" & limit & "\',\'" & start & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    \r\n    \'Atributos del objeto JSON \r\n    icountpage = rsDataTotal("CountPage")\r\n    rows = rsDataTotal("CountTotal")\r\n\r\n    jsonResult = jsonResult & """totals"" : [{" & vbCrLf \r\n    jsonResult = jsonResult & """countpage"" : """ & icountpage & """," & vbCrLf  \r\n    jsonResult = jsonResult & """rows"" : """ & rows & """" & vbCrLf\r\n    jsonResult = jsonResult & "}]"\r\n\r\n    \'Cerramos el RecordSet.\r\n    rsDataTotal.Close: Set rsDataTotal = Nothing     \r\n\r\n    \'Se finaliza cadena JSON\r\n    jsonResult = jsonResult & "}" & vbCrLf  \r\n  \r\n    \'Si no se encuentra la cadena\r\n    ShowRegistryData = jsonResult\r\n\r\nEnd Function\r\n\r\n\'Se obtienen el catálogo de diagnósticos(al ser 12mil registros se hace una petición directa al base de datos)\r\nFunction ShowSearchDiagnosis(diagnosisname,sex,birthdate,userid,diarytype,diarydate,relationtmp)\r\n\r\n    Dim jsonResult\r\n    Dim iCount \r\n\r\n    jsonResult = "{" & vbCrLf\r\n\r\n    Set rs4Data = Server.CreateObject("ADODB.RecordSet") \r\n    objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n    rs4Data.Open "CALL __fRptGetData_SIRES_Diagnosis(\'" & diagnosisname & "\',\'" & sex & "\',\'" & birthdate & "\',\'" & userid & "\'," & diarytype & ",\'" & diarydate & "\',\'" & relationtmp & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n    jsonResult = jsonResult & """results"" : [" & vbCrLf \r\n\r\n    \'Contador de iteraciones para saber cuando es la 1 iteración.            \r\n    iCount = 0      \r\n\r\n    Do While Not (rs4Data.EOF) \r\n\r\n        \'Se escribe el primer objeto JSON.\r\n        If iCount = 0 Then\r\n        jsonResult = jsonResult & "{" & vbCrLf                    \r\n        Else\r\n        jsonResult = jsonResult & "," & vbCrLf & "{" & vbCrLf\r\n        End If \r\n\r\n        \'Se determina el contador de filas\r\n        iCount=iCount + 1 \r\n\r\n        \'Atributos del objeto JSON  \r\n        jsonResult = jsonResult &  """id"" : """ & rs4Data("id") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """code"" : """ & rs4Data("code") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """name"" : """ & rs4Data("name") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """lsex"" : """ & rs4Data("lsex") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """linf"" : """ & rs4Data("linf") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """lsup"" : """ & rs4Data("lsup") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """cachildday"" : """ & rs4Data("cachildday") & """," & vbCrLf\r\n        jsonResult = jsonResult &  """chronicday"" : """ & rs4Data("chronicday") & """" & vbCrLf\r\n        jsonResult = jsonResult &  "}"\r\n        rs4Data.MoveNext\r\n    Loop\r\n\r\n    \'Se finaliza arreglo de registros.\r\n    jsonResult = jsonResult & "]" & vbCrLf   \r\n\r\n    \'Se finaliza cadena JSON\r\n    jsonResult = jsonResult & "}" & vbCrLf  \r\n\r\n    \'Cierre el RecordSet.\r\n    rs4Data.Close: Set rs4Data = Nothing     \r\n\r\n    \'Si no se encuentra la cadena\r\n    ShowSearchDiagnosis = jsonResult \r\n\r\nEnd function\r\n\r\n\'Se guardan las variables por consulta\r\nFunction SaveDataDiary(clientid,data,typeform,clinicid,userid,diarygdate)\r\n\r\n        \r\n        \'Variables a utilizar\r\n        Dim arrdata, msg, strItem,srtdata,arrItem\r\n\r\n        arrdata = Split(Replace(Replace(data,"{",""),"}",""),",")\r\n        srtdata = ""\r\n        counter = 0\r\n\r\n        \'0. Se determina si los datos mínimos de personas (cliente y usuarios están correctos)\r\n        Set rsPersonsData = Server.CreateObject("ADODB.RecordSet") \r\n        objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n        rsPersonsData.Open "CALL __fRptCheckData_SIRES_CheckPersonalData(\'"& userid &"\',\'" & clientid & "\',\'" & diarygdate &"\')", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        \r\n        If Not (rsPersonsData.EOF) Then\r\n            iUserValidated = rsPersonsData("UserValidated")\r\n            iClientValidated =  rsPersonsData("ClientValidated")\r\n            sUserMsgReturned = rsPersonsData("UserMsgReturned")\r\n            sClientMsgReturned =  rsPersonsData("ClientMsgReturned")\r\n        Else \r\n            iUserValidated="0"\r\n            iClientValidated="0"\r\n            sUserMsgReturned=""\r\n            sClientMsgReturned=""\r\n        End If\r\n\r\n        rsPersonsData.Close: Set rsPersonsData = Nothing \r\n\r\n        If iUserValidated="0" Or iClientValidated="0" Then\r\n\r\n            jsonResult = jsonResult &  "{""results"" : [{" & vbCrLf \r\n            jsonResult = jsonResult &  """uservalidated"" : """ & iUserValidated & """," & vbCrLf\r\n            jsonResult = jsonResult &  """usermsgreturned"" : """ & sUserMsgReturned & """," & vbCrLf\r\n            jsonResult = jsonResult &  """clientvalidated"" : """ & iClientValidated & """," & vbCrLf\r\n            jsonResult = jsonResult &  """clientmsgreturned"" : """ & sClientMsgReturned & """" & vbCrLf\r\n            jsonResult = jsonResult &  "}]}"\r\n\r\n        Else\r\n\r\n            \'1. Se obtienen los valores pasados por parámetro y se asegura que a la data sea una combinación de clave valor.\r\n            For Each strItem In arrdata\r\n\r\n                IF counter > 0 Then\r\n                srtdata = srtdata & ","\r\n                END IF\r\n\r\n                arrItem = Split(strItem,":")\r\n\r\n                srtdata = srtdata & arrItem(0) & ":" & arrItem(1)\r\n                counter = counter + 1\r\n\r\n            Next\r\n            \r\n            Set rsSData = Server.CreateObject("ADODB.RecordSet") \r\n            objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n            rsSData.Open "CALL __fRptSaveData_SIRES_Diary(\'" & clientid & "\', \'" & srtdata & "\', \'" & typeform & "\', \'" & clinicid & "\', \'" & userid & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n            jsonResult =  " {""results"" : [{""msg"" : """ & fsGetLabel(rsSData("msg")) & """ }]}" & vbCrLf\r\n            rsSData.Close: Set rsSData = Nothing\r\n        End If\r\n\r\n    SaveDataDiary = jsonResult\r\n\r\nEnd Function\r\n\r\n\'Se elimina la consulta seleccionada\r\nFunction DeleteDataDiary(clientid, diaryid,diarygdate,serviceid,typeform,clinicid,userid)\r\n\r\n        \'Variables a utilizar\r\n        Dim jsonResult, msg\r\n    \r\n        \'Se llama el procedimiento almacenado que elimina la consulta\r\n        Set rsDData = Server.CreateObject("ADODB.RecordSet") \r\n        objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n        rsDData.Open "CALL __fRptDeleteData_SIRES_Diary(\'" & clientid & "\',\'" & diaryid & "\',\'" & diarygdate & "\',\'" & serviceid & "\',\'" & typeform & "\',\'" & clinicid & "\',\'" & userid & "\');", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        jsonResult =  " {""results"" : [{""msg"" : """ & fsGetLabel(rsDData("msg")) & """ }]}" & vbCrLf\r\n        rsDData.Close: Set rsDData = Nothing\r\n\r\n    DeleteDataDiary = jsonResult\r\n\r\nEnd Function\r\n\r\n\'Se construye opciones a mostrar en el multiselector de servicios.\r\nFunction GetServiceJsonValues()\r\n\r\n    Dim sR2SQL,sValues   \r\n    sR2SQL = "SELECT __fRptGetData_SIRES_SerializedCatalog(\'25\') AS FieldJsonValues;"\r\n    Set rsR2Data = Server.CreateObject("ADODB.Recordset")\r\n    rsR2Data.Open sR2SQL, objConnection, adOpenForwardOnly, adLockReadOnly\r\n    sValues = rsR2Data("FieldJsonValues")\r\n    rsR2Data.Close: Set rsR2Data = Nothing \r\n    GetServiceJsonValues = sValues\r\n\r\nEnd Function\r\n\r\n\'Se determina la clasificación tipo de personal del usuario activo\r\nFunction GetStaffTypeAndCurp(userid)\r\n        \r\n        \'Variables a utilizar\r\n        Dim staffType\r\n\r\n        Set rs6Data = Server.CreateObject("ADODB.RecordSet") \r\n        objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n        rs6Data.Open "SELECT UserCollegeTypeID,UserCURP FROM x_config_users WHERE UserID=\'" & userid & "\';", objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        staffType=rs6Data("UserCollegeTypeID")\r\n        curp=rs6Data("UserCURP")\r\n        rs6Data.Close: Set rs6Data = Nothing\r\n\r\n    GetStaffTypeAndCurp = staffType & "|" & curp\r\n\r\nEnd Function\r\n\r\n\'Se determina la clasificación tipo de personal del usuario activo\r\nFunction GetStaffTypeByDiary(diarytype)\r\n        \r\n        \'Variables a utilizar\r\n        Dim staffTypeByDiary, sql\r\n\r\n        Set rs5Data = Server.CreateObject("ADODB.RecordSet") \r\n        objConnection.Execute("SET lc_time_names = \'es_ES\';") \r\n        sql = "SELECT STypeDiaryStaff FROM __sires_type_diary WHERE STypeDiaryID=\'" & diarytype & "\';"\r\n        rs5Data.Open sql , objConnection, adOpenForwardOnly, adLockReadOnly          \r\n        staffTypeByDiary=rs5Data("STypeDiaryStaff")\r\n        rs5Data.Close: Set rs5Data = Nothing\r\n\r\n    GetStaffTypeByDiary = staffTypeByDiary\r\n\r\nEnd Function\r\n\r\n\'Se determina la clínica se encuentra en el directorio de servicios amigables.\r\nFunction GetCluesFrendly(clinicid)\r\n        \r\n        \'Variables a utilizar\r\n        Dim sql\r\n\r\n        Set rsData = Server.CreateObject("ADODB.RecordSet")     \r\n        sql = "SELECT COUNT(xc.ClinicID)AS isCluesFrendly FROM x_config_clinics xc INNER JOIN __sires_clues_frendly cf ON cf.FriendlyClues=xc.ClinicCLUES WHERE xc.ClinicID=\'" & clinicid & "\';"\r\n        rsData.Open sql, objConnection, adOpenForwardOnly, adLockReadOnly  \r\n        isCluesFrendly=rsData("isCluesFrendly")\r\n        rsData.Close: Set rsData = Nothing\r\n\r\n    GetCluesFrendly = isCluesFrendly\r\n\r\nEnd Function\r\n\r\n\'Se determina las abreviatura de la clínica para las validaciones de primera consulta.\r\nFunction GetDataUnitInSires(clinicid)\r\n        \r\n        \'Variables a utilizar\r\n        Dim abr, sql\r\n        abr = ""\r\n\r\n        Set rsData = Server.CreateObject("ADODB.RecordSet")     \r\n        sql = "SELECT CONCAT_WS(\',\',ss.CluesTypeAbbreviation,ss.CluesSubAbbreviation) AS abr FROM x_config_clinics xc INNER JOIN x_config_sires_clues ss ON ss.CluesID=xc.ClinicCLUES WHERE xc.ClinicID=\'" & clinicid & "\';"\r\n        rsData.Open sql, objConnection, adOpenForwardOnly, adLockReadOnly  \r\n\r\n        If Not (rsData.EOF)  Then\r\n            abr  = rsData("abr")             \r\n        End If\r\n        \r\n        rsData.Close: Set rsData = Nothing\r\n\r\n    GetDataUnitInSires = abr\r\n\r\nEnd Function\r\n\r\n\'________________________________________________________________________________________________\r\n\'SECCION DE RESPUESTAS DEL LADO DEL SERVIDOR SEGUN LA EVALUACIÓN DE LOS PARAMETROS RECIBIDOS\r\n\r\nSelect Case formtype\r\n    Case "show_client_data"\r\n\r\n        result = ShowClientData(sR_ClientID, sR_SDiaryID,sR_SDiaryDate,sR_ServiceSearch,sR_STypeForm,sS_ClinicID,sS_UserID)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n    Case "save_data"\r\n\r\n        result = SaveDataDiary(sR_ClientID, sR_SData,sR_STypeForm,sS_ClinicID,sS_UserID,sR_SDiaryDate)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n\r\n    Case "delete_data"\r\n\r\n        result = DeleteDataDiary(sR_ClientID, sR_SDiaryID,sR_SDiaryDate,sR_ServiceSearch,sR_STypeForm,sS_ClinicID,sS_UserID)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()  \r\n\r\n    Case "__sires_x_config_diagnosis"\r\n\r\n        result = ShowSearchDiagnosis(sR_SFilterText, sR_SSex, sR_SBirthDate,sR_UserID,sSTypeDiary,sR_SDiaryDate,sR_SRelationTmp)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finaliza la respuesta.\r\n        Response.End()     \r\n      \r\n    Case "show_diary_data"\r\n\r\n        result = ShowClientData(sR_ClientID, 2)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finalizamos la respuesta.\r\n        Response.End()   \r\n\r\n    Case "show_registry_data"\r\n\r\n        result = ShowRegistryData (sR_ClientID,sR_DateStart,sR_DateEnd,sR_STypeForm,sR_ServiceID,sR_Limit,sR_Start)\r\n\r\n        \'Se construye el JSON para mostrar la información en la tabla del informe      \r\n        Response.ContentType = "application/json"\r\n        Response.CodePage = 65001\r\n        Response.Write result\r\n\r\n        \'Se finalizamos la respuesta.\r\n        Response.End()   \r\nEnd Select\r\n\r\n\'Se crean los scripts html y js para visualizar y darle funcionamiento a la página que se muestra con el report.\r\n%>\r\n\r\n<HTML>\r\n	<HEAD>\r\n			<META http-equiv="Content-Type" content="text/html; charset=windows-1252">   \r\n            <SCRIPT src="https://code.jquery.com/jquery-3.6.0.min.js"></SCRIPT> \r\n            <SCRIPT src="https://cdn.jsdelivr.net/npm/xlsx/dist/xlsx.full.min.js"></SCRIPT>                          \r\n            <STYLE>\r\n                .left {text-align:left;}\r\n                .right {text-align:right;}\r\n                .center {text-align:center;} \r\n                .pag {background-color:#f3f3f3; border-radius: 0px 0px 15px 15px; height:40px; width:98%; padding-top: 1px; display:flex; align-items: center;}\r\n                .label_singer {text-align:center; font-weight: bold; color: var(--flowww-primary-color);}\r\n                .label_title {text-align:left; font-weight: bold; color: #6E5EE0;}\r\n                .div_total {display: flex; justify-content: center; align-items: center; height:52px;width:90% !important;border-radius: 10px; background: #e2dff9; color:var(--flowww-primary-color); font-weight: bold;  margin:5px; font-family: DMSans, OpenSans, sans-serif;}\r\n                .spinner-container {position: fixed;top: 0;left: 0;width: 100%;height: 100%;background-color: rgba(0, 0, 0, 0.5); display: flex;justify-content: center;align-items: center;z-index: 9999;}\r\n                .spinner {border: 4px solid rgba(255, 255, 255, 0.3);border-top: 4px solid #ffffff;border-radius: 50%;width: 30px;height: 30px;animation: spin 1s linear infinite;}\r\n                .select_rows_pag {margin-top: 1px !important;width:15%;height:70% !important;}\r\n                .lbl_rows_pag {margin-top: 8px !important;width:30%;margin-left:60%;height:70% !important;}\r\n                .__select-container {position: relative;width: 100%; padding: 5px; appearance: none;}\r\n                .__search_box {width: 100%; height:100%;}\r\n                .__options {font-family: DMSans, OpenSans, sans-serif;font-size:16px;position: absolute;width: 100%;max-height: 190px;overflow-y: auto;border: 1px solid #ccc;background: white;display:block;z-index: 9999;border-radius: 10px;}\r\n                .__option {padding: 8px;cursor: pointer; color: var(--flowww-primary-color); }\r\n                .__option:hover {background:#1967d2; color:#ffffff;}\r\n                .__not_valid {border-bottom: 2px solid red !important;}\r\n                .__readonly {border-bottom: none !important;}\r\n                .__multiselect {border-radius: .25rem !important;border: 0.5px solid lightgrey !important;height: 180px;overflow-y: scroll;padding-top: 10px;margin-top: -5px;box-sizing: border-box;z-index: 200;background-color: white;width: calc(100% - 2px);position: absolute;}\r\n                .__multiselect::-webkit-scrollbar {width: 8px;height: 8px;}\r\n                .__multiselect::-webkit-scrollbar-thumb, {background: #888;border-radius: 6px;}\r\n                .__multiselect::-webkit-scrollbar-thumb:hover {background: var(--grey-4-color);}\r\n                .__multiselect_option {display: block;padding: 6px 20px 6px;border-radius: 10px;}\r\n                .__multiselect_container_fieldset {padding-bottom: 4px;}\r\n                .__multiselect_container_name {text-align: left;border: 1px solid lightgrey;padding: 0 16px;width: calc(100% - .05rem)!important;border-radius: 10px;background: url(\'data:image/svg+xml, <svg  width="24px" height="24px"  xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="rgba(50, 46, 45, 0.2)" d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"  /></svg>\')!important;background-size: 24px!important;background-position: calc(100% - 6px) center!important;background-repeat: no-repeat!important;height: calc(3rem + 2px)!important;}\r\n                .__multiselect_none {display: none !important;}\r\n                .__multiselect_container {width: 100% !important;}\r\n                .__multiselect_container_fieldset>div+label {transform: translateY(-8px) scale(.8);transform-origin: 0 0;color: var(--flowww-primary-color);margin-top: -.1rem;left: 23px;background: #fff;border-left: 4px solid #fff;border-right: 4px solid #fff;}\r\n                .__multiselectfont{  font-family: DMSans, OpenSans, sans-serif;font-size:16px;}\r\n                #main_div {overflow:auto;}\r\n                @media print {#main_div {overflow:visible;}}\r\n                @keyframes spin {0% { transform: rotate(0deg); }100% { transform: rotate(360deg); }}\r\n            </STYLE> \r\n            <SCRIPT language="JavaScript" TYPE="text/javascript">\r\n                \r\n                function fInit(){}              \r\n                \r\n                //Permite saber la página activa del registro de consultas\r\n                getPageCurrent = function (limit, start, rows){                    \r\n                    \r\n                    let newcurpage = 0,\r\n                        countpage = Math.ceil(rows/limit),\r\n                        tdatainfo_pag_cur = document.getElementById("tdatainfo_pag_cur"),\r\n                        tdatainfo_pag_current = document.getElementById("tdatainfo_pag_Current"),    \r\n                        tdatainfo_pag_prev = document.getElementById("tdatainfo_pag_Prev_li"),     \r\n                        tdatainfo_pag_next = document.getElementById("tdatainfo_pag_Next_li"); \r\n                    \r\n                    if(start == 0){\r\n                        newcurpage = 1;\r\n                        tdatainfo_pag_prev.setAttribute("CLASS","disabled");\r\n\r\n                        if(countpage > 1){\r\n                            tdatainfo_pag_next.classList.remove("disabled");\r\n                        }else {\r\n                            tdatainfo_pag_next.setAttribute("CLASS","disabled");\r\n                        }\r\n                        \r\n                    }else{\r\n                        newcurpage = Math.ceil(start/limit) + 1; \r\n                        tdatainfo_pag_prev.classList.remove("disabled");\r\n                        \r\n                        if(newcurpage == countpage){\r\n                            tdatainfo_pag_next.setAttribute("CLASS","disabled");\r\n                        }\r\n                    }                                            \r\n                    tdatainfo_pag_current.setAttribute("data-curpage",newcurpage);\r\n                    tdatainfo_pag_cur.textContent = ("<%=slblPagination%>").replace("###1###",newcurpage);  \r\n                    tdatainfo_pag_cur.textContent = (tdatainfo_pag_cur.textContent).replace("###2###",countpage);\r\n                }            \r\n\r\n                //Funciones que intervienen en un multiselect\r\n                multiselectFunctions ={\r\n\r\n                        selectOption: function (event,sElementId) {\r\n                            if (event.target.parentElement.children[1].classList.contains("__multiselect_none")) {\r\n                                event.target.parentElement.children[1].classList.remove("__multiselect_none");\r\n                            } else {\r\n                                let divElement = document.getElementById(sElementId),\r\n                                items = divElement.getElementsByClassName(\'__multiselect\');\r\n                                for (let i = 0; i < items.length; i++) {\r\n                                    items[i].classList.add("__multiselect_none");\r\n                                }\r\n                            }\r\n                        },\r\n\r\n                        collapse: function (event){                \r\n                                let items = document.getElementsByClassName(\'__multiselect\');\r\n                                for (let i = 0; i < items.length; i++) {\r\n                                    items[i].classList.add("__multiselect_none");\r\n                                }\r\n                        },\r\n\r\n                        selectAll: function (event,sElementId) {\r\n                            let divElement = document.getElementById(sElementId),\r\n                                items = divElement.getElementsByClassName(\'__multiselect_option\');\r\n                            if (event.target.checked) {                          \r\n                                for (let i = 0; i < items.length; i++) {\r\n                                    items[i].getElementsByTagName("input")[0].checked = true;\r\n                                }\r\n                                divElement.children[0].innerHTML = "<%= fsGetLabel("lbl_all_m") %>"; \r\n                                multiselectFunctions.collapse(); \r\n                            } else  {                        \r\n                                for (let i = 0; i < items.length; i++) {\r\n                                    items[i].getElementsByTagName("input")[0].checked = false;\r\n                                }\r\n                                divElement.children[0].innerHTML = "<%= fsGetLabel("lbl_multiselect_placeholder") %>";\r\n                            }\r\n                        },\r\n\r\n                        check: function (event,sElementId) {\r\n\r\n                            let divElement = document.getElementById(sElementId); \r\n                            let items = divElement.getElementsByClassName("__multiselect_option");\r\n                            let checkedItem = (event==null) ? true : !event.target.checked;\r\n\r\n                            if (checkedItem) {\r\n                                /*\r\n                                let allselected = document.getElementsByName("all_"+sElementId);\r\n                                allselected[0].getElementsByTagName("input")[0].checked = false;\r\n                                */\r\n                                \r\n                                let items_checked = 0;\r\n\r\n                                for (let i = 0; i < items.length; i++) {\r\n                                    if (items[i].getElementsByTagName("input")[0].checked) {\r\n                                        items_checked++;\r\n                                    }\r\n                                }\r\n\r\n                                if (items_checked == 0) {\r\n                                    divElement.children[0].innerHTML = "<%= fsGetLabel("lbl_multiselect_placeholder") %>"; \r\n                                } else {\r\n                                    divElement.children[0].innerHTML = items_checked + " <%= fsGetLabel("lbl_of") %> " + (items.length - 1) ;\r\n                                }\r\n\r\n                            } else {                    \r\n                                let items_length = items.length;\r\n                                let items_checked = 0;\r\n                                for (let i = 0; i < items_length; i++) {\r\n                                    if (items[i].getElementsByTagName("input")[0].checked) {\r\n                                        items_checked++;\r\n                                    }\r\n                                }\r\n\r\n                                divElement.children[0].innerHTML = items_checked + " <%= fsGetLabel("lbl_of") %> " + (items_length - 1);\r\n                                /*\r\n                                if (items_checked == (items_length - 1)) {\r\n                                    var allselected = document.getElementsByName("all_"+sElementId);\r\n                                    allselected[0].getElementsByTagName("input")[0].checked = true;\r\n                                }*/\r\n                            }\r\n                        },\r\n\r\n                        getValues: function (sElementId,attribute="value",checkoption=true){                    \r\n                            sElementIdList = \'\';\r\n                            let i = 0,IsChecked = true;\r\n                            Array.from(document.getElementById(sElementId).getElementsByTagName("input")).map(e => {  \r\n                                \r\n                                if(checkoption){\r\n                                    IsChecked=e.checked;\r\n                                }else{\r\n                                    IsChecked=true;\r\n                                }\r\n\r\n                                if (IsChecked) { \r\n                                    if (/*e.getAttribute(attribute) != 0 &&*/ e.getAttribute(attribute) != null && (!isNaN(e.getAttribute(attribute)) || !isNaN(new Date(e.getAttribute(attribute))))) { \r\n                                        if(i > 0) {\r\n                                            sElementIdList += ",";\r\n                                        } else {\r\n                                            i++;\r\n                                        }\r\n                                        sElementIdList += e.getAttribute(attribute);\r\n                                    }\r\n                                }\r\n                            });\r\n                            /*\r\n                            if (sElementIdList == \'\'){\r\n                                sElementIdList = \'0\'\r\n                            }*/\r\n\r\n                            return sElementIdList;\r\n                        },\r\n\r\n                        searchInput: function (event,sElementId){\r\n                            let divElement = document.getElementById(sElementId),                        \r\n                                searchtext = event.target.value.toLowerCase(),\r\n                                spanElements = divElement.querySelectorAll(\'[name="__multiselect_option"]\'); \r\n\r\n                                Array.from(spanElements).map(e => {  \r\n                                    let optionSpan = e.getElementsByTagName("span");                            \r\n                                        optionText = optionSpan[0].innerHTML.toLowerCase();\r\n                                \r\n                                    if (optionText.includes(searchtext)) {\r\n                                        e.style.display = \'block\'\r\n                                        e.classList.add(\'__multiselect_option\')\r\n                                    } else {\r\n                                        e.style.display = \'none\'\r\n                                    }\r\n                                });          \r\n                        },\r\n\r\n                        getValuesCombined: function (firstselectid,SecondSelectid){\r\n\r\n                            let sValuesFirstSelect = multiselectFunctions.getValues(firstselectid),\r\n                                divElement = document.getElementById(SecondSelectid),\r\n                                spanElements = divElement.querySelectorAll(\'[name="__multiselect_option"]\'),\r\n                                items_checked = 0;                       \r\n                                \r\n                            Array.from(spanElements).map(e => {  \r\n                                let objInput = e.getElementsByTagName("input")[0]\r\n                                    sDataFilterSecondSelect = objInput.getAttribute("data-filter") ?? \'0\';                                \r\n\r\n                                if(utilFunctions.arrHasCommonValues(sValuesFirstSelect,sDataFilterSecondSelect)){\r\n                                    e.style.display = \'block\';\r\n                                    e.classList.add(\'__multiselect_option\');\r\n                                    \r\n                                }else {\r\n                                    e.style.display = \'none\';\r\n                                }                            \r\n                            });  \r\n                            \r\n                        },\r\n\r\n                        getOuterHtml:function (sElementId, sListOptionsHtml, sLblElement) {\r\n                            \r\n                            // Etiquetas de idioma (se sugiere que estos valores vengan de algún objeto de etiquetas o traducciones)\r\n                            let sLabelSelect = "<%=slbl_multiselect_placeholder%>",\r\n                                sLabelAll = "<%=slbl_all_m%>",\r\n                                sLabelSearch = "<%=slbl_search_for%>",\r\n                                sLabelInputSearch = "<%=slbl_insert_option%>";\r\n\r\n                            // Crear contenedor del multiselect\r\n                            let MultiSelectElem = document.createElement("div");\r\n                            MultiSelectElem.className = "input-field input-outlined __multiselect_container_fieldset";\r\n\r\n                            sHeaderMultiselectHtml = \'    <DIV id="\' + sElementId + \'" CLASS="__multiselect_container">\';\r\n                            sHeaderMultiselectHtml += \'        <BUTTON onclick="multiselectFunctions.selectOption(event,\\\'\' + sElementId +\'\\\');" CLASS="__multiselect_container_name" type="button">\' + sLabelSelect + \'</BUTTON>\';\r\n                            sHeaderMultiselectHtml += \'        <DIV id="select_\' + sElementId + \'" CLASS="__multiselect_none __multiselect" onmouseleave="multiselectFunctions.collapse(event);">\';\r\n                            sHeaderMultiselectHtml += \'            <SPAN name="all_\' + sElementId + \'" CLASS="__multiselect_option">\';\r\n                            sHeaderMultiselectHtml += \'                <LABEL for="searchInput"><SPAN CLASS="__multiselectfont">\' + sLabelSearch + \'</SPAN></LABEL>\';\r\n                            sHeaderMultiselectHtml += \'                <INPUT type="text" id="searchInput" CLASS="searchInput" oninput="multiselectFunctions.searchInput(event,\\\'\' + sElementId +\'\\\')" name="\' + sElementId + \'" placeholder="\' + sLabelInputSearch + \'">\';\r\n                            //sHeaderMultiselectHtml += \'                <LABEL><INPUT type="checkbox" value="-2" onchange="multiselectFunctions.selectAll(event,\\\'\' + sElementId +\'\\\');"><span CLASS="__multiselectfont">\' + sLabelAll + \'</span></LABEL>\';\r\n                            sHeaderMultiselectHtml += \'            </SPAN>\';\r\n                            sHeaderMultiselectHtml += sListOptionsHtml\r\n                            sHeaderMultiselectHtml += \'</DIV></DIV>\';\r\n                            sHeaderMultiselectHtml += \'<LABEL FOR="\' + sElementId + \'">\' + sLblElement + \'</LABEL> \';\r\n\r\n                            MultiSelectElem.innerHTML = sHeaderMultiselectHtml;        \r\n\r\n                            return MultiSelectElem;\r\n                        },\r\n\r\n                        getOptionsOuterHtml:function (fieldjsonvalues, valueSelect,fieldname){\r\n\r\n                                const values = JSON.parse(fieldjsonvalues).values;\r\n                                const arrValuesSelect = valueSelect.split("&"); \r\n                                let optionHtml = "", checkedoption="";    \r\n                    \r\n                            for(var i=0;i<values.length;i++){ \r\n                            \r\n                                if (arrValuesSelect.includes(""+values[i].id)){\r\n                                    checkedoption = "checked"; \r\n                                }else {\r\n                                    checkedoption = "";\r\n                                }\r\n\r\n                                optionHtml += \'<span class="__multiselect_option" name="__multiselect_option">\' \r\n                                optionHtml += \'<label>\'\r\n                                optionHtml += \'<input type="checkbox" onchange="multiselectFunctions.check(event,\\\'\' + fieldname + \'\\\');"  value="\' + values[i].id + \'" \' + checkedoption + \'>\' \r\n                                optionHtml += \'<span class="__multiselectfont">\' + values[i].name + \'</span>\' \r\n                                optionHtml += \'</label>\' \r\n                                optionHtml += \'</span>\'\r\n\r\n                            }\r\n                            return optionHtml;\r\n                        }\r\n                };            \r\n                \r\n                //Funciones que permiten construir los elementos visuales del formulario y tipo de input de una consulta\r\n                elemFunctions = {\r\n                    \r\n                    getTableWithSiresField: function (arrObj){  //Se pinta un panel(div) con la una tabla cuyas columnas y valores de opcionen de un Json.\r\n\r\n                        //Se obtienen los datos                     \r\n                        let results = arrObj;\r\n\r\n                        //Se crean los elementos html\r\n                        let table = document.createElement("table"),                                            \r\n                            thead = document.createElement("thead"),\r\n                            tbody = document.createElement("tbody"),\r\n                            trhead = document.createElement("tr"),\r\n                            thfielddesc = document.createElement("th"),\r\n                            thfieldvalue = document.createElement("th");                    \r\n                        \r\n                        thfielddesc.innerHTML="";\r\n                        thfieldvalue.innerHTML="";\r\n                        thfielddesc.style.width="60%";\r\n                        thfieldvalue.style.width="40%";\r\n\r\n                        trhead.appendChild(thfielddesc);\r\n                        trhead.appendChild(thfieldvalue);\r\n\r\n                        //Contador de variables gestionadas por el usuario para la consulta que se carga\r\n                        let countFieldEdited = 0;\r\n\r\n                        for (var i = 0; i < results.length; i++) {\r\n\r\n                            //Se definen las columnas a mostrar en la tabla\r\n                            let row = document.createElement("tr"),\r\n                                tdfielddesc = document.createElement("td"),                                        \r\n                                tdfieldvalue = document.createElement("td");\r\n                                tdfielddesc.setAttribute("id","lbl"+results[i].fieldname);\r\n                            \r\n                            //Se agragar estilos\r\n                            tdfielddesc.style.width="60%";\r\n                            tdfieldvalue.style.width="40%";\r\n\r\n                            //Se determina si se marca la tabla como que tienen valores gestionados por el usuario para poder expandir el panel por defecto.\r\n                            if (results[i].fieldvalue != "" && (results[i].fieldvalue!=results[i].fielddefaultvalue) || results[i].fieldvalue=="0" || (results[i].fieldvalue=="-1" && results[i].fieldjsonvalues.includes("-1"))){\r\n                                countFieldEdited ++;\r\n                            }\r\n\r\n                            //Se determina el elemento visual a mostrar en la columnas de valores según el tipo de parámetro                        \r\n                            let fieldtypeview = results[i].fieldtypeview,\r\n                                addlblfielddesc = "",\r\n                                lblfielddesc = "",\r\n                                objElement = document.createElement("span");\r\n                                objElement.textContent= "Por definir";                                               \r\n                            \r\n                            switch (fieldtypeview) {\r\n\r\n                                case "SELECTSEACH": { \r\n                                    objElement = elemFunctions.getElementSelectSearch( results[i].fieldname, results[i].fieldvalue, results[i].fieldjsonvalues, results[i].fieldcheckfn, results[i].fieldcheckfndesc, results[i].fielddefaultvalue);\r\n                                    addlblfielddesc = "<%=slbl_press_enter%>";\r\n                                }break;\r\n\r\n                                case "SELECT": {   \r\n                                    objElement = elemFunctions.getElementSelect( results[i].fieldname, results[i].fieldvalue, results[i].fieldjsonvalues, results[i].fieldcheckfn, results[i].fieldcheckfndesc, results[i].fielddefaultvalue);\r\n                                    tdfieldvalue.classList.add("input-field", "input-outlined", "__multiselect_container_fieldset");\r\n                                }break;\r\n\r\n                                case "MULTISELECT": {\r\n                                    objElement = elemFunctions.getElementMultiSelect( results[i].fieldname, results[i].fieldvalue, results[i].fieldjsonvalues, results[i].fieldcheckfn, results[i].fieldcheckfndesc, results[i].fielddefaultvalue);\r\n                                }break;\r\n                                \r\n                                case "TEXT": {                                \r\n                                    objElement = elemFunctions.getElementText(results[i].fieldname,results[i].fieldvalue,results[i].fieldcheckfn,results[i].fieldcheckfndesc,results[i].fielddefaultvalue);\r\n                                }break;\r\n\r\n                                case "DATE": {                                \r\n                                    objElement = elemFunctions.getElementDate(results[i].fieldname,results[i].fieldvalue,results[i].fieldcheckfn,results[i].fieldcheckfndesc,results[i].fielddefaultvalue);\r\n                                }break;\r\n\r\n                                case "NUMERIC": {\r\n                                    objElement = elemFunctions.getElementNumeric(results[i].fieldname,results[i].fieldvalue,results[i].fieldcheckfn,results[i].fieldcheckfndesc,results[i].fielddefaultvalue);\r\n                                }break;\r\n                            }\r\n                            \r\n                            objElement.setAttribute("onchange", "checkFunctions."+results[i].fieldname+"();"); \r\n                            objElement.setAttribute("name", results[i].fieldname); \r\n\r\n                            if(fieldtypeview!="TEXT"){\r\n                                objElement.setAttribute("onblur", "checkFunctions."+results[i].fieldname+"();"); \r\n                            }\r\n\r\n                            tdfieldvalue.innerHTML = objElement.outerHTML;\r\n                            lblfielddesc = results[i].fieldesc+" "+addlblfielddesc;\r\n                            tdfielddesc.innerHTML = (results[i].fieldmandatory==-1)?lblfielddesc+\' <span style="color: red;">*</span>\':lblfielddesc; \r\n\r\n                            //Se añaden las columnas a la fila a mostrar\r\n                            row.appendChild(tdfielddesc);   \r\n                            row.appendChild(tdfieldvalue);                        \r\n                            \r\n                            //Se añade fila a la tabla\r\n                            tbody.appendChild(row); \r\n\r\n                            // Se ajusta tamaño del marco del reporte con cada línea insertada\r\n                            table.style.tableLayout = "fixed";\r\n                            //utilFunctions.fitIframe(table); \r\n\r\n                        }                 \r\n\r\n                        //Se añade el tbody a la tabla\r\n                        table.appendChild(tbody);                    \r\n                        table.style.width = "100%";\r\n                        table.setAttribute("class", "table__list highlight");   \r\n                        table.style.height = "auto";\r\n                        table.setAttribute("FieldsEdited", countFieldEdited);   \r\n                        table.setAttribute("TotalFields", results.length);   \r\n\r\n                        //Se reajusta el tamaño del SEC_REPORT_iframe por cada fila que se añada\r\n                        //utilFunctions.fitIframe(table);                         \r\n\r\n                        return table;\r\n                    },             \r\n\r\n                    filterOptionsSelectSearch: function (sElementId,sTableListName) {\r\n\r\n                        let searchInput = document.getElementById(sElementId), \r\n                            filterText = searchInput.value.toLowerCase();\r\n                            searchDivOptions = document.getElementById("options_"+sElementId),\r\n                            objAjaxData = { form: sTableListName, fil:filterText};\r\n                        const arrSelectSearch = ["codigoCIEDiagnostico1","codigoCIEDiagnostico2","codigoCIEDiagnostico3"] ;\r\n                        \r\n                        if(arrSelectSearch.includes(sElementId)){\r\n                            objAjaxData.sx = document.getElementById("sexoBiologico").value;    \r\n                            objAjaxData.bd = document.getElementById("fechaNacimiento").value;\r\n                            objAjaxData.uid =  "<%=sS_UserID%>";  \r\n                            objAjaxData.dd =  document.getElementById("fechaConsulta").value;\r\n                            objAjaxData.rt =  document.getElementById("relacionTemporal").value;                 \r\n                            objAjaxData.tf =  "<%=sSTypeDiary%>";  \r\n                        }\r\n                    \r\n                        //Se coloca spinner\r\n                        objselecthtml = \'<div class="__option"  >\' + "<%=slbl_load_spinner%>" + \'</div>\';\r\n                        searchDivOptions.innerHTML = objselecthtml;\r\n                        searchDivOptions.style.display = "block";\r\n\r\n                        //Se habilita la opción de modo qeu se oculte el div si se quita el mause.\r\n                        /*searchDivOptions.addEventListener("mouseout", function() { \r\n                                                                    searchDivOptions.style.display = "none";\r\n                                                                    });*/\r\n                        \r\n                        //Se realiza la petición al servidor\r\n                        $.ajax({\r\n                                url: "",\r\n                                method: "POST",\r\n                                dataType: "JSON",\r\n                                data: objAjaxData,\r\n                                success:function(data){   \r\n\r\n                                    //Se obtienen los datos enviados por la petición                                        \r\n                                    let jsonString = JSON.stringify(data), \r\n                                        results = JSON.parse(jsonString).results,\r\n                                        objselecthtml = ""; \r\n                                \r\n                                    for(var i=0;i<results.length;i++){ \r\n                                        objselecthtml += \'<div class="__option" data-id="\' + results[i].id + \'" data-code="\' + results[i].code + \'"  data-lsex="\'+results[i].lsex +\'" data-linf="\'+ results[i].linf +\'"  data-lsup="\'+results[i].lsup+\'" data-cachildday="\'+results[i].cachildday+\'" data-chronicday="\'+results[i].chronicday+\'"  onclick="elemFunctions.selectOptionSearch(this);" >\' + results[i].name + \'</div>\';\r\n                                    }\r\n\r\n                                    searchDivOptions.innerHTML = objselecthtml;\r\n                                    searchDivOptions.style.display = "block";                               \r\n                                    searchDivOptions.classList.add("__options"); \r\n                                },\r\n                                error: function(xhr, status, error) {                                    \r\n                                    alert("Error:" + status + " " + error);\r\n                                }\r\n                        });\r\n                        \r\n                    },            \r\n\r\n                    selectOptionSearch: function (element) {\r\n\r\n                        let optionsList = element.parentElement,\r\n                            divSearch = element.parentElement.parentElement,\r\n                            searchBox = document.getElementById((divSearch.id).replace("search_","") );\r\n                            code = element.getAttribute("data-code") || "";\r\n                            scachildday = element.getAttribute("data-cachildday") || "";\r\n                            schronicday = element.getAttribute("data-chronicday") || "";\r\n                            cachildday = (scachildday == "SI") ? 1 : 0;\r\n                            chronicday = (schronicday == "SI") ? 1 : 0;\r\n                        \r\n                        searchBox.setAttribute("code", code);\r\n                        searchBox.setAttribute("cachildday", cachildday);\r\n                        searchBox.setAttribute("chronicday", chronicday);\r\n                        searchBox.value = element.textContent;\r\n                        searchBox.classList.add("__not_valid");\r\n                        searchBox.setAttribute("validated", true);\r\n                        searchBox.setAttribute("title","");\r\n                        searchBox.classList.remove("__not_valid");    \r\n                        optionsList.classList.remove("__options");\r\n                        optionsList.style.display = "none";\r\n                    },\r\n\r\n                    getElementSelectSearch: function (fieldname="", fieldvalue="",fieldjsonvalues="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue="",fieldmandatory=-1){\r\n                        \r\n                        let jsonvalues = JSON.parse(fieldjsonvalues),\r\n                            objselecthtml = "",\r\n                            objselect = document.createElement("div");\r\n                            objselect.setAttribute("id", "search_"+fieldname);\r\n                            objselect.classList.add("__select-container");\r\n\r\n                        const arrFielValue = fieldvalue.split(","); \r\n                        const value = (arrFielValue!="") ? arrFielValue[0]+" - "+arrFielValue[1]:""; \r\n                        const cachildday = (arrFielValue[2] == "SI") ? 1 : 0;              \r\n                        const chronicday = (arrFielValue[3] == "SI") ? 1 : 0;              \r\n                            \r\n                        if (jsonvalues.hasOwnProperty("table")){\r\n                            tableListName = JSON.parse(fieldjsonvalues).table;\r\n                            objselecthtml += \'<input id="\'+fieldname+\'" name="\'+fieldname+\'" value="\'+value+\'"  code="\'+arrFielValue[0]+\'" cachildday="\'+cachildday+\'" chronicday="\'+chronicday+\'" type="text" class="__search_box" onkeydown="if(event.key === \\\'Enter\\\' && event.target.value.length>3){elemFunctions.filterOptionsSelectSearch(\\\'\'+fieldname+\'\\\',\\\'\'+tableListName+\'\\\');}" placeholder=" <%=slbl_select_one_m%>">\';\r\n                            objselecthtml += \'<div class="" id="options_\'+fieldname+\'">\';                    \r\n                            objselecthtml += \'</div>\';\r\n                            objselect.innerHTML=objselecthtml;\r\n                            \r\n                        }\r\n                        return objselect;  \r\n                    },\r\n                \r\n                    getElementSelect: function (fieldname="", fieldvalue="",fieldjsonvalues="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue="",fieldmandatory=-1){\r\n                        \r\n                        let objselect = document.createElement("select"),                    \r\n                            jsonvalues = JSON.parse(fieldjsonvalues); \r\n\r\n                        if (jsonvalues.hasOwnProperty("values")){\r\n                            values = JSON.parse(fieldjsonvalues).values; \r\n\r\n                            objselect.setAttribute("id", fieldname);                    \r\n                            \r\n                            let optfrst = document.createElement("option");\r\n                                    optfrst.value = -2;\r\n                                    optfrst.textContent = "<%=slbl_select_one_m%>";                        \r\n                                    optfrst.setAttribute("selected", "true");\r\n                                    objselect.appendChild(optfrst);\r\n                            \r\n                            for(var i=0;i<values.length;i++){ \r\n\r\n                                    let opt = document.createElement("option");\r\n                                    opt.value = values[i].id;\r\n                                    opt.textContent = values[i].name;\r\n                                    \r\n                                    let abr =values[i].abr || "";\r\n                                    opt.setAttribute("abr", abr );\r\n\r\n                                    if(String(values[i].id) === String(fieldvalue) ){  \r\n                                        optfrst.removeAttribute("selected");                          \r\n                                        opt.setAttribute("selected", "true");\r\n                                        objselect.setAttribute("abr", abr);  \r\n                                    }                                    \r\n\r\n                                    //Se determinan las opciones visibles en función del tipo de personal\r\n                                    if(values[i].hasOwnProperty("staff")){\r\n                                        \r\n                                        //Se determinan los servicios asociados al usuario activo\r\n                                        let stafftype = "<%=sS_StaffType%>";                                    \r\n                                        let arrStaffService = (values[i].staff).split(",");\r\n                                        let userInStaff = (arrStaffService.includes(stafftype));\r\n\r\n                                        //Se muestra el elemento aunque el tipo de personal del usuario activo no coincida con el del elemento seleccionado.\r\n                                        if(!userInStaff && (String(values[i].id) === String(fieldvalue))){\r\n                                            objselect.setAttribute("state", "readonly"); \r\n                                            objselect.appendChild(opt); \r\n                                            continue;\r\n                                        }\r\n                                        \r\n                                        //Si verifica si se ha configurado el elemento como deshabilitado.\r\n                                        if (values[i]?.disabled == 0 && userInStaff) {\r\n                                            objselect.appendChild(opt);\r\n                                            continue;\r\n                                        }\r\n\r\n                                        //Si no se encuentra definido el campo disabled se adiciona el elemento por defecto\r\n                                        if(!values[i]?.disabled && userInStaff ){\r\n                                            objselect.appendChild(opt); \r\n                                            continue;\r\n                                        }\r\n\r\n                                    }else{\r\n                                        objselect.appendChild(opt); \r\n                                    }\r\n                            }\r\n                        }                    \r\n                        return objselect;    \r\n                        \r\n                    }, \r\n\r\n                    getElementText: function (fieldname="", fieldvalue="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue=""){\r\n                    \r\n                        let objtextinput = document.createElement("input"); \r\n                            objtextinput.setAttribute("id", fieldname);\r\n                            objtextinput.setAttribute("value", fieldvalue);\r\n                            objtextinput.setAttribute("placeholder", "<%=slbl_sires_fill_data%>");\r\n                            objtextinput.setAttribute("onchange",fieldcheckfn);                        \r\n                        return objtextinput;\r\n                    },\r\n\r\n                    getElementMultiSelect: function (fieldname="", fieldvalue="",fieldjsonvalues="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue="",fieldmandatory=-1){\r\n                        sListOptionsHtml = multiselectFunctions.getOptionsOuterHtml(fieldjsonvalues,fieldvalue,fieldname);\r\n                        return multiselectFunctions.getOuterHtml(fieldname, sListOptionsHtml,"");\r\n                    }, \r\n\r\n                    getElementDate: function (fieldname="", fieldvalue="",fieldjsonvalues="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue="",fieldmandatory=-1){\r\n                    \r\n                        let value = (fieldvalue=="")? "<%=sR_DateEnd%>":fieldvalue;\r\n                    \r\n                        let objtextinput = document.createElement("input");\r\n                            objtextinput.classList.add("datepicker")\r\n                            objtextinput.setAttribute("id", fieldname);\r\n                            objtextinput.setAttribute("type", "date");\r\n                            objtextinput.setAttribute("value", value );\r\n                            objtextinput.setAttribute("onchange",fieldcheckfn);\r\n                        return objtextinput;\r\n                    },  \r\n\r\n                    getElementNumeric: function (fieldname="", fieldvalue="",fieldjsonvalues="",fieldcheckfn="(function(){})();",fieldcheckfndesc="",fielddefaultvalue="",fieldmandatory=-1){\r\n                        let max = 1000;\r\n                        if(fieldjsonvalues!==""){\r\n                            const values = JSON.parse(fieldjsonvalues).values;\r\n                            let max = (values.hasOwnProperty("maxvalue"))? values.maxvalue:1000;\r\n                        }\r\n                        let objtextinput = document.createElement("input"); \r\n                            objtextinput.setAttribute("id", fieldname);\r\n                            objtextinput.setAttribute("type", "number");\r\n                            objtextinput.setAttribute("value", fieldvalue);\r\n                            objtextinput.setAttribute("max", max);\r\n                            objtextinput.setAttribute("placeholder", "<%=slbl_sires_fill_data%>");\r\n                            //objtextinput.addEventListener("input",function(event){eval(fieldcheckfn)});\r\n                        return objtextinput;\r\n                    },\r\n\r\n                    getTitlePanelByFieldEdited:function(panelWithTableElement){\r\n                        let tablesElem = panelWithTableElement.getElementsByTagName("table"),\r\n                            fieldsEdited = parseInt(tablesElem[0].getAttribute("FieldsEdited")),\r\n                            totalFields = parseInt(tablesElem[0].getAttribute("TotalFields")),\r\n                            spanTitle = panelWithTableElement.previousElementSibling.getElementsByTagName("span"),                            \r\n                            titlePanel = spanTitle[0].textContent,\r\n                            delimiter = \'<%=fsGetLabel("lbl_of")%>\';\r\n\r\n                            spanTitle[0].textContent = (titlePanel.includes("|")) ? titlePanel : `${titlePanel} | ${fieldsEdited}  ${delimiter}  ${totalFields}` ;\r\n                            \r\n                        return { edited:fieldsEdited, total:totalFields};\r\n                    },\r\n                    getCountInvalidField:function(panelWithTableElement){\r\n                        return (panelWithTableElement.querySelectorAll(\'[validated="false"]\')).length;\r\n                    }\r\n                };\r\n\r\n                //Funciones de ordenación de las columnas del regisro de consultas\r\n                sortFunctions = {\r\n                    sortArrRows:function (rows,fieldIndex,order){\r\n                        \r\n                        rows.sort((a, b) => {\r\n                            let textA = a.cells[fieldIndex].innerText.toLowerCase(),\r\n                                textB = b.cells[fieldIndex].innerText.toLowerCase(),\r\n                                orderByType = "String";\r\n\r\n                            //Tipos de ordenaciones\r\n                            if(textA.includes("€") || typeof textA == "number" ){\r\n                                orderByType = "Number";\r\n                            }\r\n                            if(textA.includes("/") || typeof textA == "date" ){\r\n                                orderByType = "Date";\r\n                            }\r\n\r\n                            switch (orderByType) {\r\n                                case "Number":\r\n                                    let floatA = parseFloat(((textA.replace("€","")).replace(".","")).replace(",",".")),\r\n                                        floatB = parseFloat(((textB.replace("€","")).replace(".","")).replace(",","."));\r\n                                \r\n                                    if (order == "asc") {\r\n                                        return floatA - floatB; // Orden ascendente\r\n                                    } else {\r\n                                        return floatB - floatA; // Orden descendente\r\n                                    };\r\n\r\n                                case "Date":\r\n                                    let dateA = utilFunctions.getDateFromStringDMY(textA),\r\n                                        dateB = utilFunctions.getDateFromStringDMY(textB); \r\n                                \r\n                                    if (order == "asc") {\r\n                                        return dateA - dateB; // Orden ascendente\r\n                                    } else {\r\n                                        return dateB - dateA; // Orden descendente\r\n                                    };\r\n\r\n                                default:\r\n                                    if (order == "asc") {\r\n                                        return textA.localeCompare(textB); // Orden ascendente\r\n                                    } else {\r\n                                        return textB.localeCompare(textA); // Orden descendente\r\n                                    }                            \r\n                            }\r\n                        \r\n                        });\r\n                        return rows;\r\n                    },\r\n\r\n                    sortArrRowsByGroups:function (rows,fieldIndex,order) {\r\n                        const result = [];\r\n                        let subgroup = [];\r\n                        \r\n                        rows.forEach(row => {\r\n                            if (row.cells[0].colSpan > 1 ) {\r\n                            \r\n                                if (subgroup.length > 0) {\r\n                                    // Se ordena el subgrupo actual antes de agregarlo al resultado\r\n                                    sortFunctions.sortArrRows(subgroup,fieldIndex,order);                                \r\n                                    result.push(...subgroup);\r\n                                    subgroup = []; // Reiniciar subgrupo\r\n                                }\r\n                                //Se agrega el marcador de inicio al resultado\r\n                                result.push(row);\r\n                            } else {\r\n                            //Se agrega el elemento al subgrupo actual\r\n                            subgroup.push(row);\r\n                            }\r\n                        });\r\n\r\n                        // Se ordenar y agrega el último subgrupo al resultado si existe\r\n                        if (subgroup.length > 0) {\r\n                            sortFunctions.sortArrRows(subgroup,fieldIndex,order);    \r\n                            result.push(...subgroup);\r\n                        }\r\n\r\n                        return result;\r\n                    },     \r\n                    \r\n                    sortTable:function (__this,tableid,fieldIndex,hasGroup=false) {\r\n                        \r\n                        let order = "asc";\r\n\r\n                        switch(__this.textContent ){\r\n                            case "unfold_more": \r\n                                __this.textContent = "keyboard_arrow_up";\r\n                                order = "asc";\r\n                                break;\r\n                            case "keyboard_arrow_down": \r\n                                __this.textContent = "keyboard_arrow_up";\r\n                                order = "asc";\r\n                                break;\r\n                            case "keyboard_arrow_up": \r\n                                __this.textContent = "keyboard_arrow_down";\r\n                                order = "desc";\r\n                                break;\r\n                        }                \r\n                        \r\n                        // Se selecciona la tabla\r\n                        let table = document.getElementById(tableid),\r\n                            tbody = table.getElementsByTagName("tbody")[0];\r\n\r\n                        // Se convierte las filas a un array\r\n                        let rows = Array.from(tbody.rows),\r\n                            rowsOrded = [];\r\n\r\n                        //Se ordena las filas basándose en la columna que se desea ordenar\r\n                        if(hasGroup){\r\n                            rowsOrded = sortFunctions.sortArrRowsByGroups(rows,fieldIndex,order);\r\n                        }else {\r\n                            rowsOrded = sortFunctions.sortArrRows(rows,fieldIndex,order);\r\n                        }   \r\n\r\n                        // Reordena las filas en el cuerpo de la tabla\r\n                        tbody.innerHTML = "";\r\n                        rowsOrded.forEach(row => tbody.appendChild(row));\r\n\r\n                        // Selecciona todos los elementos <i> dentro de la tabla\r\n                        let icons = table.querySelectorAll("i");\r\n\r\n                        // Cambia el textContent de cada elemento <i> unfold_more para resetear la ordenación\r\n                        icons.forEach((icon, index) => {\r\n                            if(index != fieldIndex){\r\n                                icon.textContent = "unfold_more";\r\n                            }\r\n                        });\r\n                    }\r\n                };\r\n\r\n                // Funciones para mostrar o ocultar spinner\r\n                spinnerFunctions = {\r\n                    \r\n                    showSpinner: function () {\r\n                        document.getElementById("spinnerContainer").style.display = "flex";\r\n                    },\r\n\r\n                    hideSpinner: function () {\r\n                        document.getElementById("spinnerContainer").style.display = "none";\r\n                    }\r\n\r\n                };                \r\n                \r\n                //Funciones auxiliares varias\r\n                utilFunctions = {\r\n                    getDateFromStringDMY:  function (dateStrDMY) {\r\n\r\n                        // Dividir la cadena en día, mes y año\r\n                        const [iday, imonth, iyear] = dateStrDMY.split("/").map(Number);\r\n\r\n                        // Crear un objeto Date (mes - 1 porque los meses en Date comienzan en 0)\r\n                        return new Date(iyear, imonth - 1, iday);\r\n                    },\r\n                    fitIframe: function (tabla=false){     \r\n\r\n                        iSEC_REPORT_iframe = window.parent.document.getElementById("SEC_REPORT_iframe")\r\n\r\n                        if (tabla !== false){  \r\n\r\n                            //Se ajusta tamaño del marco del reporte con cada línea insertada     \r\n                            let row = tabla.rows[tabla.rows.length - 1],  \r\n                                currentHeightIFrame = parseInt(iSEC_REPORT_iframe.style.height, 10);\r\n                                currentHeightIFrameEnd = currentHeightIFrame + parseInt(row.offsetHeight, 10);  \r\n                            \r\n                            iSEC_REPORT_iframe.setAttribute("style", "height: " + currentHeightIFrameEnd +"px !important;");   \r\n                        }else{\r\n                            const iframeDoc = iSEC_REPORT_iframe.contentDocument || iSEC_REPORT_iframe.contentWindow.document;\r\n                            const elem = iframeDoc.getElementById("FormPanelActionBar");\r\n                            const rect = elem.getBoundingClientRect();\r\n                            const bottom = rect.bottom + window.scrollY;\r\n\r\n                            iSEC_REPORT_iframe.style.height = bottom + "px";\r\n\r\n                        }\r\n                    },\r\n                    arrHasCommonValues: function (valuesA, valuesB) {\r\n                            \r\n                            let arrValuesA = valuesA.split(\',\').map(val => val.trim()); \r\n                            let arrValuesB = valuesB.split(\',\').map(val => val.trim()); \r\n                        \r\n                            for (let value of arrValuesA) {\r\n                                if (arrValuesB.includes(value)) {\r\n                                    return true; \r\n                                }\r\n                            }\r\n                            return false;\r\n                    },\r\n                    checkCURP: function (curp) {\r\n\r\n                        utilFunctions.fitIframe();\r\n\r\n                        const result = confirm("<%=slbl_check_curp%>");\r\n                        \r\n                        if(result){\r\n                            //Se muestra el spinner\r\n                            spinnerFunctions.showSpinner();                        \r\n\r\n                            //Se realiza la petición a RENAPO\r\n                            fetch("https://api.verificamex.com/identity/v1/scraping/renapo", {\r\n                                    method: \'POST\',\r\n                                    headers: {\r\n                                        \'Accept\': \'application/json\',\r\n                                        \'Content-Type\': \'application/json\',\r\n                                        //\'Authorization\': \'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiJ9.eyJhdWQiOiIxIiwianRpIjoiMGU0NDUxYmUzMzQ1Y2YxYWU2MjI0MGI1ZTc2OTM2ZjNmOGFlZjBmM2FmNzhhM2M3YmIxZjgwNjZiNTBkMzc2Zjg5YmQyNDBkZTM2YzkyYTMiLCJpYXQiOjE3NTM3OTg3ODYuOTE1NTcsIm5iZiI6MTc1Mzc5ODc4Ni45MTU1NzMsImV4cCI6MTc4NTMzNDc4Ni45MDQ1Niwic3ViIjoiNjg3OCIsInNjb3BlcyI6W119.M8Nl-UozOVjzvm8ZzZBO3lslIfcSgqBcBql7DG2KANXAcQlfl576hE1YL7Yt8o5TSEuNfucjL5MzatdugE-IhNgxUP5hqF49GJYz2_aWy5IUwQIc9yy1kh124S367IBmJ7mK8V-bSXyFvIWM649Q85QfWBioaVV2Sx0WvXRKYQyrPuMT0gh1nXQJGIdQXJLwKODBE-3OwQITLT_25Nte80tbgzIonwkbiiCTbHA_p1J-vbmzP9RqlVK6don2VZQEwwbdBrXSGyrJkmHLS0EMFw6Ov8mzY5VAkehic6YTBnB3cAJLoyRRn1KZS9KaL7QZJEHomV5eYwmx6FZjxWgMbpxn8fk4hJebjN8mXwS9xFapuSu_GDNRqUyNu7LC_OFM9NAPrWUM5Z4f5seR8RvpcUTeRfyrxSlr_s2m0yobp7QxcEmpbwB4OcPX6qpI1bz8oQf1H3cvN_dDpdR-wgaTk2Vu_RjkKXu8RTeKqr35qUAeVYVmc0U2ibQYbgn3zHEH612CDj8WMWLyY99NC7nbVa5OOlU88zYs-T19nkn6njnCQdbSobQi-ODaFbyA6cPC2QRi8C6_a7LKlujSH4FU9AsQ6Foz0QmHeAINomQ1UocS6YOOgtUWq6bhVsCkRWsiGFf1BShApD7Uy6iS7TnCKbVl7UtCwwYo6pu-W6YsUoQ\',\r\n                                        \'Authorization\': \'Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiJ9.eyJhdWQiOiIxIiwianRpIjoiYTQzMzUxZjA0MTYwNmRmZDk2NDhkNTliYTA1MWI0OTE4ZTk3ZTIzZDFmZmE3ODRhYzk4NTQ0OWM5ODg3NDk2ODg3YTJhNDMwNGY4OTQ4NTUiLCJpYXQiOjE3NTQzMTg3MDAuMjA3NDQ4LCJuYmYiOjE3NTQzMTg3MDAuMjA3NDUsImV4cCI6MTc4NTg1NDcwMC4xOTQzNzUsInN1YiI6IjY3NDQiLCJzY29wZXMiOltdfQ.BmKNx5vCkE_YEs5o9Ljq4mAArpDjpUhe2-rL4pwY__DubXRt9E4miSyzHZ_BFoAZuUdS483v0KCzXxs0jW-lhcYRlzhGqcqz_OkqsWbqp0_e6oP1J77BkJtvPC4LtYNKCWNZautGlllE0CtbqTlvonNne5SdP4y93N678PLBgEfY3X7KJ-sqIE1-JxSGJ0wneQGsli2oxXcPGgYyiufoLOIcID4Pri9HPHJoF-F9wjx9PWJhdhzIL01TO1ic9yCgKOkpRiqapOHNZlRejaQYO6m4qMmro1gVWhxqzqhe6oa7uzF8kHI067SO1m8vVXtD-OaiEzUpK5wFOXc563HXmGkl-Y4Fbz3q2ZjuL3nP9jetG2bCDE1Z_Do2Jp0IchEOzDgykWdDOHWeTWfmWnFUy0h_5pp76T7D2wef74HXC3WCZUDhq1gn7snIunSlzS43FPIituBWI-fsBv0x69tPg5F9GdfLdbdvImhUce7NWKcQVlRCpwqx0kbnVDqBM3bgGdHAfGkyO_RhPpI3k28Pee2WmcyZ_RWlDaw-Ro6sZRbElJLRyWRXX3ghKClx0ndETQzojgOBCvQISG8aInzxMHI6u8KSHD85SwAjJUOXwXRd92Ft4oDSio7TjtGF9jm63CgCz3_M_nuDwQ_do8Q0l_YEIGnI3S-4hdvz9wfgfLA\',\r\n                                        \'Cookie\': \'XSRF-%3D; %3D\',\r\n                                    },\r\n                                    body: JSON.stringify({\r\n                                        curp: curp \r\n                                    })\r\n                                })\r\n                                .then(response => response.json())\r\n                                .then(result => {\r\n                                    const data = result.data;\r\n                                    spinnerFunctions.hideSpinner(); // Oculta el spinner\r\n\r\n                                    const msg = result?.message || data?.citizen?.mensaje;\r\n                                    if (msg) alert(msg);\r\n\r\n                                    if (data?.citizen?.status && Array.isArray(data.citizen.registros) && data.citizen.registros.length > 0) {\r\n                                        /*const registro = data.citizen.registros[0];\r\n\r\n                                        const setValue = (id, value) => {\r\n                                            const el = document.getElementById(id);\r\n                                            if (el) el.value = value;\r\n                                        };\r\n\r\n                                        setValue("nombre", registro.nombres);\r\n                                        setValue("primerApellido", registro.primerApellido);\r\n                                        setValue("segundoApellido", registro.segundoApellido);\r\n\r\n                                        const select = document.getElementById("entidadNacimiento");\r\n                                        if (select) {\r\n                                            const option = select.querySelector(`option[abr="${registro.claveEntidad}"]`);\r\n                                            if (option) {\r\n                                                option.selected = true;\r\n                                                select.value = option.value;\r\n                                            }\r\n                                        }                                \r\n\r\n                                        if (document.getElementById("entidadNacimiento")?.value != -2) {\r\n                                            setValue("paisNacPaciente", 142);\r\n                                        } \r\n\r\n                                        const selectsex = document.getElementById("sexoCURP");                                    \r\n                                        const sex = (registro.sexo).toUpperCase();\r\n                                        const opt = Array.from(selectsex.options).find(o => o.text.trim().toUpperCase() == sex);\r\n                                        if (opt) {\r\n                                            opt.selected = true;                                   \r\n                                        }*/\r\n\r\n                                        let inputCURP =document.getElementById("curpPaciente");\r\n                                        inputCURP.setAttribute("validated", true);\r\n                                        inputCURP.classList.remove("__not_valid");\r\n                                    }else{\r\n                                        let inputCURP =document.getElementById("curpPaciente");\r\n                                        inputCURP.classList.add("__not_valid");\r\n                                        inputCURP.setAttribute(\'title\', \'Debe tener 18 caracteres y una estructura similar a XXXX999999XXXXXX99. Debe ser diferente al CURP del usuario que registra la consulta y corresponder con los datos personales.\'); \r\n                                    }\r\n                                })\r\n                                .catch(error => {\r\n                                    let inputCURP =document.getElementById("curpPaciente");\r\n                                        inputCURP.classList.add("__not_valid");\r\n                                        inputCURP.setAttribute(\'title\', \'Debe tener 18 caracteres y una estructura similar a XXXX999999XXXXXX99. Debe ser diferente al CURP del usuario que registra la consulta y corresponder con los datos personales.\'); \r\n                                        \r\n                                    alert("Error: "+ error);\r\n                                });                            \r\n                    \r\n                        }\r\n                    },\r\n                    filterServicesByStaff:function (sJsonServices, staffId) {\r\n                        if (!staffId) return [];\r\n\r\n                        const staffIds = String(staffId)\r\n                            .split(",")\r\n                            .map(s => s.trim());\r\n\r\n                        return sJsonServices.filter(service => {\r\n                            if (!service.staff) return false;\r\n\r\n                            const serviceStaff = service.staff\r\n                                .split(",")\r\n                                .map(s => s.trim());\r\n\r\n                            return staffIds.some(id => serviceStaff.includes(id));\r\n                        });\r\n                    }\r\n\r\n                };\r\n                \r\n                //Funciones para colapsar o expandir los paneles del formulario de consultas según las reglas del negocio\r\n                collapsedPFunctions = {\r\n                    collapseAll: function(){\r\n                        const divcontent = document.getElementById("FormPanel");\r\n                        const clientlockdata = divcontent.getAttribute("clientlockdata");\r\n                        const panels = document.querySelectorAll("div.collapsible-body");                        \r\n                        let contpanel = 0;\r\n\r\n                        panels.forEach(panel => {\r\n                            if(clientlockdata==0){\r\n                                if(contpanel==0){\r\n                                    panel.style.display="block";\r\n                                }else{\r\n                                    panel.style.display="none";\r\n                                }\r\n                            }else{\r\n                                if(contpanel==1 ){\r\n                                    panel.style.display="block";\r\n                                }else{\r\n                                    panel.style.display="none";\r\n                                }\r\n                            }\r\n                            contpanel++;\r\n\r\n                            elemFunctions.getTitlePanelByFieldEdited(panel);\r\n\r\n                        });\r\n                        let iSEC_REPORT_iframe = window.parent.document.getElementById("SEC_REPORT_iframe");  \r\n                            iSEC_REPORT_iframe.contentWindow.scrollTo({ top: 0, behavior: "smooth"});\r\n\r\n                    },\r\n                    expandAll:function(){\r\n                        const divcontent = document.getElementById("FormPanel");\r\n                        const clientlockdata = divcontent.getAttribute("clientlockdata");\r\n                        const panels = document.querySelectorAll("div.collapsible-body");\r\n                        let contpanel = 0;\r\n\r\n                        panels.forEach(panel => { \r\n                            \r\n                            const fields = elemFunctions.getTitlePanelByFieldEdited(panel);\r\n                            const fieldsEdited = fields.edited;\r\n                            const invalidField = elemFunctions.getCountInvalidField(panel); \r\n\r\n                            if(fieldsEdited>0 || invalidField>0){\r\n                                if(clientlockdata==-1 && contpanel==0){\r\n                                    panel.style.display="none";\r\n                                } else {\r\n                                    panel.style.display="block";\r\n                                }                                \r\n                            }else{\r\n                                panel.style.display="none";\r\n                            }\r\n                            contpanel++;   \r\n                        });\r\n                        utilFunctions.fitIframe();\r\n                    },\r\n                    collapse: function(_this){\r\n                        _this.parentElement.nextElementSibling.style.display="none";\r\n                        //_this.parentElement.style.background="transparent";\r\n                        _this.textContent = "keyboard_arrow_down";\r\n                        _this.setAttribute("onclick","collapsedPFunctions.expand(this);");\r\n                        utilFunctions.fitIframe();\r\n                    },\r\n                    expand:function(_this){\r\n                        _this.parentElement.nextElementSibling.style.display="block";                \r\n                        //_this.parentElement.style.background="white";\r\n                        _this.textContent = "keyboard_arrow_up";\r\n                        _this.setAttribute("onclick","collapsedPFunctions.collapse(this);");\r\n                        utilFunctions.fitIframe();\r\n                    },\r\n                    collapseByPanelID: function(panelID){\r\n                        let _this = document.getElementById(panelID).querySelector(".collapsible-body");\r\n                        _this.style.display="none";\r\n                        _this.textContent = "keyboard_arrow_down";\r\n                        _this.setAttribute("onclick","collapsedPFunctions.expand(this);");\r\n                        utilFunctions.fitIframe();\r\n                    }\r\n                };\r\n                \r\n                //Funciones que definen acciones dentro del registro y formulario de consulta\r\n                actionFunctions= {\r\n\r\n                    ShowPanelClienteDataForm: function (typeform,diarydate="",siresservice=-2,diarygid=0,reloadform=0){\r\n\r\n                        //Variables auxiliares\r\n                        const \r\n                            iClientID = window.parent.gsClientID, \r\n                            iUserID = "<%=sS_UserID%>",\r\n                            iStaffType = "<%=sS_StaffType%>",\r\n                            sUserCurp = "<%=sUserCurp%>",\r\n                            iStaffTypeByDiary = "<%=sS_StaffTypeByDiary%>",\r\n                            today = new Date(),\r\n                            year = today.getFullYear(),\r\n                            month = String(today.getMonth() + 1).padStart(2, "0"), \r\n                            day = String(today.getDate()).padStart(2, "0"),\r\n                            dDate = `${year}-${month}-${day}`; \r\n                            dDiaryDate = (diarydate=="")?dDate:diarydate; \r\n\r\n                        //Se muestra el spinner\r\n                        spinnerFunctions.showSpinner();                   \r\n\r\n                        //Se realiza la petición al servidor\r\n                        $.ajax({\r\n                                    url: "",\r\n                                    method: "POST",\r\n                                    dataType: "JSON",\r\n                                    data: { form: "show_client_data",\r\n                                            cid:iClientID,                                    \r\n                                            did:diarygid,\r\n                                            dd:dDiaryDate,\r\n                                            ss:siresservice,\r\n                                            tf:typeform                                   \r\n                                        },\r\n                                    success:function(data){\r\n\r\n                                        //Se obtienen los datos enviados por la petición                                        \r\n                                        let jsonString = JSON.stringify(data), \r\n                                            personaldata = JSON.parse(jsonString).personaldata,                                \r\n                                            results = JSON.parse(jsonString).results,                                \r\n                                            sections = JSON.parse(jsonString).sections, \r\n                                            diarydata = JSON.parse(jsonString).diarydata; \r\n                                        \r\n                                        //Se verifica si no se encuentran validos los datos tanto del prestador como del paciente y si el usuario tiene acceso a gestionar la guia de consulta seleccionada para el cliente activo.\r\n                                        if (personaldata[0].uservalidated=="0" || personaldata[0].clientvalidated=="0" ){\r\n                                            \r\n                                            let msgpersonaldata = "";\r\n                                                msgpersonaldata = (personaldata[0].uservalidated=="0") ? "\\n<%=slbl_update_data_users%>\\n" + personaldata[0].usermsgreturned:"";\r\n                                                msgpersonaldata += (personaldata[0].clientvalidated=="0")? "\\n<%=slbl_update_data_clients%>\\n" + personaldata[0].clientmsgreturned:"";\r\n                                            alert(msgpersonaldata);                                            \r\n                                            parent.fClearBack();\r\n\r\n                                            if(personaldata[0].uservalidated=="0" ){  \r\n                                                parent.fUserEdit(iUserID);   \r\n                                            }else {\r\n                                                parent.fMenuTabsClient("TAB_CLIENT", iClientID);\r\n                                            }                                            \r\n                                            return;\r\n                                        }\r\n                                        \r\n                                        //Si la consulta a mostrar es nueva consulta (no tiene variables registradas) no se recarga el formulario para no perder los datos ya registrados\r\n                                        if((diarydata[0].diarysgid=="0" && reloadform==1) /*|| diarydata[0].diarysgidexport!="0"*/){\r\n                                          \r\n                                           //Se oculta el spinner.\r\n                                           spinnerFunctions.hideSpinner();  \r\n                                           return;\r\n                                        }\r\n                                        \r\n                                        //Si los datos mínimos de personas están validados se muestran las variables de la consulta y se agrupan la variables por secciones                                    \r\n                                        const arrFieldBySections = results.reduce((arr, obj) => {\r\n                                            // Si la sección no existe en el acumulador, la creamos como un arreglo vacío\r\n                                            if (!arr[obj.fieldsectionid]) {\r\n                                                arr[obj.fieldsectionid] = [];\r\n                                            }\r\n                                            // Se agraga el objeto al arreglo de la sección correspondiente\r\n                                            arr[obj.fieldsectionid].push(obj);\r\n                                            return arr;\r\n                                        }, {});     \r\n\r\n                                        //Se determina el div contenedor donde se colocan los paneles      \r\n                                        const divcontent = document.getElementById("FormPanel");\r\n                                        divcontent.setAttribute("clientlockdata", diarydata[0].clientlockdata );\r\n                                        divcontent.innerHTML = "";\r\n                                            \r\n                                        // Se crean los paneles por sección y la tabla de  variables correspondiente \r\n                                        for (var i = 0; i < sections.length; i++) {\r\n\r\n                                            if(arrFieldBySections[sections[i].fieldsectionid] !== undefined){                                        \r\n                                        \r\n                                                //Se crea div contenedor \r\n                                                const divsection = document.createElement("div");\r\n                                                divsection.setAttribute("id", "fieldsectionid"+sections[i].fieldsectionid);\r\n                                                divsection.setAttribute("style", "padding:0.5px !important");\r\n                                                divsection.classList.add("main__container");\r\n                                                divsection.classList.add("collapsible");                                          \r\n\r\n                                                //Se crea la tabla con las variables de la sección\r\n                                                tablesection = elemFunctions.getTableWithSiresField(arrFieldBySections[sections[i].fieldsectionid]);\r\n\r\n                                                //Se coloca la tabla y título del panel\r\n                                                let divsectionouterhtml = \'<div class="collapsible-header">\';\r\n                                                    divsectionouterhtml += \'<i class="material-icons">list</i>\';\r\n                                                    divsectionouterhtml += \'<span style="margin-left: 5px;">\' + sections[i].fieldsectiondesc +\'</span>\';\r\n                                                    divsectionouterhtml += \'<i id="collapsible-arrow-data-acq" class="material-icons" onclick="collapsedPFunctions.expand(this);">keyboard_arrow_down</i>\';\r\n                                                    divsectionouterhtml += \'</div>\';                                            \r\n                                                    divsectionouterhtml += \'<div class="collapsible-body" style="display: block;">\';                                            \r\n                                                    divsectionouterhtml += tablesection.outerHTML;                                            \r\n                                                    divsectionouterhtml += \'</div>\';                                            \r\n                                                    divsection.innerHTML = divsectionouterhtml;\r\n\r\n                                                // Se agrega el div de la sección al body del documento\r\n                                                //document.body.appendChild(divsection);\r\n                                                divcontent.appendChild(divsection);\r\n                                            }\r\n                                        }\r\n\r\n                                        //Se habilitan los valores seleccionados de todos los elementos mutliselect.\r\n                                        const multiselectElems = divcontent.getElementsByClassName("__multiselect_container");\r\n                                        Array.from(multiselectElems).map(item => {\r\n                                                multiselectFunctions.check(null,item.id);\r\n                                        });      \r\n                                        \r\n                                        //Se oculta el spinner.\r\n                                        spinnerFunctions.hideSpinner();  \r\n\r\n                                        //Se captura el valor anterior del campo fecha de consulta y servicio para control de datos introducidos\r\n                                        const fechaConsulta = document.getElementById("fechaConsulta");   \r\n                                        const servicioAtencion = document.getElementById("servicioAtencion");   \r\n                                        \r\n                                        if (fechaConsulta!=undefined && servicioAtencion!=undefined){                                        \r\n                                            fechaConsulta.addEventListener("focus", (e) => { e.target.setAttribute("valuebeforechange",e.target.value ); });\r\n                                            servicioAtencion.addEventListener("focus", (e) => { e.target.setAttribute("valuebeforechange",e.target.value);});\r\n                                        }\r\n\r\n                                        //Se inhabilita el campo PrimeraVezAnio ya se autodetermina \r\n                                        actionFunctions.SetReadOnlyAttPrimeraVezAnio();\r\n                                        \r\n                                        //Se definen los datos personales a gestionar\r\n                                        if(personaldata[0].clientlockdata=="-1"){\r\n\r\n                                            //Se marca el CURP del cliente como válido para que no solicite validación en RENAPO.\r\n                                            let inputcurpPaciente = document.getElementById("curpPaciente").setAttribute("validated","true");\r\n                                            \r\n                                            if(diarydata[0].totaldiarygid=="0"){ \r\n                                                //Se desahabilitan solo los datos mínimos de personas\r\n                                                actionFunctions.SetReadOnlyPersonalData();\r\n                                            }else{\r\n                                                //Se desahabilitan todos los datos personales\r\n                                                actionFunctions.SetReadOnlyAllPersonalData();\r\n                                            }\r\n                                        }else{\r\n                                            //Se ponen como solo lectura los datos de clientes ya gestionados en la ficha de cliente para que no se puedan modificar\r\n                                            actionFunctions.SetReadOnlyPersonalData();\r\n                                        }\r\n                                                                                \r\n                                        //Si la consulta ha sido exportada al SIRES de ocultan los botones guardar y eliminar\r\n                                        const diarysgidexport = parseInt(diarydata[0].diarysgidexport);\r\n                                        const diarysgid = parseInt(diarydata[0].diarysgid);\r\n                                        let btnSDelete = document.getElementById("btnSDelete");\r\n                                        let btnSSave = document.getElementById("btnSSave");\r\n\r\n                                        if(diarysgidexport>0){\r\n                                            actionFunctions.SetReadOnlyDiaryData();                                          \r\n                                        }else{\r\n                                            if(diarysgid>0){                                                \r\n                                                btnSDelete.disabled  = false;                                                \r\n                                                btnSSave.disabled  = false;\r\n                                            }else {\r\n                                                btnSSave.disabled = false;\r\n                                                btnSDelete.disabled = true;\r\n                                            }\r\n                                        } \r\n\r\n                                        //Si es servicio de atención no está entre los del tipo de personal del usuario activo se deshebilita la opción de eliminar.\r\n                                        let readOnlyDiary = servicioAtencion.getAttribute("state");\r\n                                        if(readOnlyDiary=="readonly"){\r\n                                            actionFunctions.SetReadOnlyDiaryData();\r\n                                        }\r\n\r\n                                        //Se muestran todos los paneles collapsados\r\n                                        if(diarygid>0){\r\n                                            collapsedPFunctions.expandAll();\r\n                                        }else{\r\n                                            collapsedPFunctions.collapseAll();\r\n                                        }\r\n                                    \r\n                                    },//success\r\n                                    error: function(xhr, status, error) {\r\n                                        alert("Error:" + status + " " + error);\r\n                                    }\r\n\r\n                        });\r\n                    },\r\n                    SaveInformation: function(typeform){\r\n\r\n                                            //Se muestra el spinner\r\n                                            spinnerFunctions.showSpinner();\r\n\r\n                                            //Variables auxiliares\r\n                                            let formPanel = document.getElementById("FormPanel");\r\n                                            let formData = new FormData(formPanel);\r\n                                            const iClientID=window.parent.gsClientID; \r\n                                            const iUserID = "<%=sS_UserID%>"; \r\n                                            const notifFnCheckFromSave = ["servicioAtencion","fechaConsulta"];                  \r\n                                            const arrFieldMinValueByGroup = ["servicioAtencion","fechaConsulta"];                  \r\n                                            let sInvalidValues = "";\r\n                                            let sreloadform = [];\r\n                                            let objValues = {};\r\n                                            let diarygdate = formData.get("fechaConsulta");\r\n\r\n                                            //Se recorren los datos recopilados en el formulario\r\n                                            for (let [field, value] of formData.entries()) {\r\n\r\n                                                // Se ejecuta la función de validación\r\n                                                if (typeof checkFunctions[field] === "function") {\r\n\r\n                                                    if(notifFnCheckFromSave.includes(field)){\r\n                                                        checkFunctions[field](true);\r\n                                                    }else {\r\n                                                        checkFunctions[field]();\r\n                                                    }\r\n                                                }\r\n\r\n                                                //Identificado los campos no validados\r\n                                                let input = document.getElementById(field);\r\n                                                let lbl = document.getElementById("lbl"+field);\r\n                                                let validated = input.getAttribute("validated");\r\n                                                let msgTitle = input.getAttribute("title");\r\n                                                let reloadform = input.getAttribute("reloadform");\r\n\r\n                                                if(validated=="false"){\r\n                                                    sInvalidValues+=` -  ${lbl.textContent}: ${msgTitle} \\n\\n`\r\n                                                }\r\n\r\n                                                //Se determinan si alguno de los campos indica que se debe anular la opción de guardar porque se debe recargar el formulario.\r\n                                                sreloadform[sreloadform.length]=reloadform;                                        \r\n\r\n                                                //Se guardan los datos recopilados                                            \r\n                                                objValues[field]=value;\r\n\r\n                                                //Se determina si el elemento es un MULTISELECT\r\n                                                if (input.classList.contains("__multiselect_container")) {\r\n                                                    \r\n                                                    //Se obtienen los valores recogidos en el multiselect\r\n                                                    let sValues = input.getAttribute("values") || "";\r\n                                                    let sValuesRw = sValues.replace(/,/g, "|");\r\n                                                    objValues[field]=sValuesRw;\r\n                                                } \r\n                                                //Se determina si elemento es un SEARCHSELECT\r\n                                                if (input.classList.contains("__search_box")) {\r\n                                                    \r\n                                                    //Se obtienen los valores recogidos en el multiselect\r\n                                                    let searchcode = input.getAttribute("code") || ""; \r\n                                                    objValues[field]=searchcode;\r\n                                                } \r\n                                            }\r\n                                            /*\r\n                                            if (sreloadform.includes("true")){ alert(sreloadform);\r\n                                                spinnerFunctions.hideSpinner(); \r\n                                                return;\r\n                                            }*/\r\n\r\n                                            if(sInvalidValues.length>0){\r\n                                                alert("<%=slbl_InvalidFields%>"+sInvalidValues);\r\n                                                spinnerFunctions.hideSpinner();\r\n                                                collapsedPFunctions.expandAll(); \r\n                                                return;\r\n                                            }\r\n\r\n                                            //Se validan las condiciones para Salud Bucal(Section5)\r\n                                            if(typeform==1){\r\n                                                const msgCheckfieldsectionid5 = checkFunctions.checkfieldsectionid5();\r\n                                                if(msgCheckfieldsectionid5!=""){\r\n                                                    alert(msgCheckfieldsectionid5);\r\n                                                    spinnerFunctions.hideSpinner();   \r\n                                                    return;\r\n                                                }\r\n                                            }\r\n\r\n                                            //Se serializan los datos\r\n                                            const data = JSON.stringify(objValues);\r\n\r\n                                            //Se realiza la petición al servidor\r\n                                            $.ajax({\r\n                                                            url: "",\r\n                                                            method: "POST",\r\n                                                            dataType: "JSON",\r\n                                                            data: { form: "save_data",\r\n                                                                    cid:iClientID,                                    \r\n                                                                    dt:data,                                                                \r\n                                                                    tf:typeform,\r\n                                                                    dd:diarygdate                                   \r\n                                                                },\r\n                                                            success:function(data){  \r\n\r\n                                                                spinnerFunctions.hideSpinner();   \r\n\r\n                                                                //Se obtienen los datos enviados por la petición                                        \r\n                                                                let jsonString = JSON.stringify(data), \r\n                                                                    results = JSON.parse(jsonString).results;\r\n\r\n                                                                //Se verifica si no se encuentran validos los datos tanto del prestador como del paciente y si el usuario tiene acceso a gestionar la guía de consulta seleccionada para el cliente activo.\r\n                                                                if (results?.[0]?.uservalidated=="0" || results?.[0]?.clientvalidated=="0" ){\r\n                                                                    \r\n                                                                    let msgpersonaldata="";\r\n                                                                    let personaldata=results;\r\n\r\n                                                                    if(personaldata[0].uservalidated=="0" ){\r\n                                                                        msgpersonaldata= "\\n<%=slbl_update_data_users%>\\n" + personaldata[0].usermsgreturned;\r\n                                                                    }\r\n\r\n                                                                    if(personaldata[0].clientvalidated=="0" ){\r\n                                                                        msgpersonaldata+= "\\n<%=slbl_update_data_clients%>\\n" + personaldata[0].clientmsgreturned;\r\n                                                                    }\r\n                                                                    \r\n                                                                    alert(msgpersonaldata);                                            \r\n                                                                    parent.fClearBack();\r\n\r\n                                                                    if(personaldata[0].uservalidated=="0" ){  \r\n                                                                        parent.fUserEdit(iUserID);   \r\n                                                                    }else {\r\n                                                                        parent.fMenuTabsClient("TAB_CLIENT", iClientID);\r\n                                                                    }                                            \r\n                                                                    return;\r\n                                                                }\r\n\r\n                                                                //Si se encuentran validos se emite el mensaje especifico de la acción de guardar.\r\n                                                                alert(results[0].msg);\r\n                                                                \r\n                                                                //Se recarga nuevo formulario en blanco\r\n                                                                spinnerFunctions.showSpinner();\r\n                                                                actionFunctions.ShowRegistryInformation(typeform); \r\n                                                                actionFunctions.ShowRegistryPanel();\r\n\r\n                                                            },//success\r\n                                                            error: function(xhr, status, error) {\r\n                                                                alert("Error:" + status + " " + error);\r\n                                                                spinnerFunctions.hideSpinner();  \r\n                                                            }\r\n                                                });\r\n\r\n                                            \r\n                    },\r\n                    DeleteInformation:function(typeform,diarygid=0){\r\n                                                    //Se muestra el spinner\r\n                                                    spinnerFunctions.showSpinner();\r\n\r\n                                                    //Se notifica al usuario sobre la acción a realizar.\r\n                                                    let result = confirm("<%=slbl_notice_before_delete%>");\r\n\r\n                                                    if(result && diarygid>0){\r\n                                                        \r\n                                                        //Variables auxiliares                                                \r\n                                                        const fechaConsulta = (diarygid==0) ? document.getElementById("fechaConsulta").value : "";   \r\n                                                        const servicioAtencion = (diarygid==0) ? document.getElementById("servicioAtencion").value : "0";  \r\n                                                        const iClientID=window.parent.gsClientID; \r\n\r\n                                                        //Se realiza la petición al servidor\r\n                                                        $.ajax({\r\n                                                                url: "",\r\n                                                                method: "POST",\r\n                                                                dataType: "JSON",\r\n                                                                data: { form: "delete_data",\r\n                                                                        cid:iClientID,                                    \r\n                                                                        dd:fechaConsulta,                                                                \r\n                                                                        ss:servicioAtencion,\r\n                                                                        tf:typeform,\r\n                                                                        did:diarygid                                  \r\n                                                                    },\r\n                                                                success:function(data){\r\n\r\n                                                                    //Se oculta spinner\r\n                                                                    spinnerFunctions.hideSpinner();   \r\n\r\n                                                                    //Se obtienen los datos enviados por la petición                                        \r\n                                                                    let jsonString = JSON.stringify(data), \r\n                                                                        results = JSON.parse(jsonString).results;\r\n\r\n                                                                    alert(results[0].msg);\r\n                                                                    \r\n                                                                    //Se recarga el registro de consultas\r\n                                                                    actionFunctions.ShowRegistryInformation(typeform)\r\n\r\n                                                                },//success\r\n                                                                error: function(xhr, status, error) {\r\n                                                                    alert("Error:" + status + " " + error);\r\n                                                                    spinnerFunctions.hideSpinner();  \r\n                                                                }\r\n                                                        });\r\n                                                    }\r\n                    },            \r\n                    ShowAllPanels:function(){                \r\n                        document.getElementById("FormPanel").style.display="block";\r\n                        document.getElementById("FormPanelActionBar").style.display="block";\r\n                        window.parent.document.getElementById("SEC_REPORT_iframe").style="height:9964px !important;";\r\n                        //utilFunctions.fitIframe();\r\n                        \r\n                    },\r\n                    HideAllPanels:function(){                    \r\n                        /*Array.from(document.querySelectorAll("#FormPanel div .main__container.collapsible")).map(pn=>{\r\n                            if(pn.id != "fieldsectionid3"){\r\n                                pn.style.display="none";\r\n                            }});*/\r\n                        document.getElementById("FormPanel").style.display="none";\r\n                        document.getElementById("FormPanelActionBar").style.display="none";\r\n                    },\r\n                    ShowRegistryInformation:function(typeform,nextpage=0,xpt=0){\r\n\r\n                        //Variables auxiliares\r\n                        const \r\n                            iClientID=window.parent.gsClientID,  \r\n                            sServiceID = multiselectFunctions.getValues("ServiceID"),\r\n                            iUserID = "<%=sS_UserID%>",\r\n                            dStart = document.getElementById("StatsStartDate").value,\r\n                            dEnd = document.getElementById("StatsEndDate").value;\r\n\r\n                        //Se definen los registros a cargar en la página actual\r\n                        const\r\n                            selectRowsPag = document.getElementById("tdatainfo_numpag"), \r\n                            iRowsPag = selectRowsPag.value,\r\n                            sR_Limit = iRowsPag,                    \r\n                            sR_Start = 0,\r\n                            tdatainfo_pag_Current = document.getElementById("tdatainfo_pag_Current"),\r\n                            icurpage = tdatainfo_pag_Current.getAttribute("data-curpage");\r\n\r\n                            switch (nextpage) {\r\n                                case 1:  sR_Start = (parseInt(icurpage) * sR_Limit); \r\n                                    break;\r\n                                case 2:  sR_Start = ((parseInt(icurpage)-2) * sR_Limit);\r\n                                    break;\r\n                            } \r\n\r\n                        //Se evalúa que las fechas del período de búsqueda\r\n                        if(dStart != ""  && dEnd != ""){\r\n                            let dStatsStartDate = Date.parse(dStart),\r\n                                dStatsEndDate = Date.parse(dEnd),                                               \r\n                                msgCheckDate = "";     \r\n\r\n                                if(dStatsStartDate > dStatsEndDate) { msgCheckDate = "<% = slbl_rpt_check_date %>"}                                                            \r\n                                if( msgCheckDate != ""){ alert(msgCheckDate); return;}\r\n                        }                      \r\n\r\n                        //Se muestra el spinner\r\n                        spinnerFunctions.showSpinner(); \r\n\r\n                        //Se realiza la petición al servidor\r\n                        $.ajax({\r\n                                    url: "",\r\n                                    method: "POST",\r\n                                    dataType: "JSON",\r\n                                    data: { form: "show_registry_data",\r\n                                            cid:iClientID, \r\n                                            ds:dStart,\r\n                                            de:dEnd,\r\n                                            si:sServiceID,\r\n                                            uid:iUserID,\r\n                                            tf:typeform,\r\n                                            st:sR_Start,\r\n                                            lm:sR_Limit,\r\n                                            csv:xpt                                  \r\n                                        },\r\n                                    success:function(data){\r\n\r\n                                        //Se oculta spinner\r\n                                        spinnerFunctions.hideSpinner(); \r\n\r\n                                        //Se obtienen los datos enviados por la petición                                        \r\n                                        let jsonString = JSON.stringify(data), \r\n                                            results = JSON.parse(jsonString).results,\r\n                                            totals = JSON.parse(jsonString).totals; \r\n                                        \r\n                                        //Se obtiene la tabla html en la que se mostrarán los resultados\r\n                                        let table = document.getElementById("tdatainfo"),\r\n                                            tablebody = table.getElementsByTagName("tbody")[0];\r\n\r\n                                        //Se comprueba si hay resultado para mostrar\r\n                                        if (results.length == 0 ) {                                \r\n                                            tablebody.innerHTML = "";  \r\n                                            let row = document.createElement("tr");                                     \r\n                                            let td_nodata = document.createElement("td");\r\n                                            td_nodata.setAttribute("class", "thCenterVertically");\r\n                                            td_nodata.setAttribute("colspan", "100%");\r\n                                            td_nodata.innerHTML = "<% = fsGetLabel("rep_without_results") %>"; \r\n                                            row.appendChild(td_nodata); \r\n                                            tablebody.appendChild(row);   \r\n                                            return;                \r\n                                        } \r\n\r\n                                        // Si hay resultados se muestran \r\n                                        table.removeAttribute("hidden");                                \r\n                                        tablebody.innerHTML = "";\r\n\r\n                                        //Se determina la página activa y total de páginas de la petición\r\n                                        getPageCurrent(sR_Limit, sR_Start, totals[0].rows);\r\n\r\n                                        for (var i = 0; i < results.length; i++) {                                        \r\n\r\n                                            let diarygid = results[i].diarygid;\r\n\r\n                                            // Se definen las columnas a mostrar en la tabla\r\n                                            let row = document.createElement("tr"),\r\n                                                diarydate = document.createElement("td"),                                        \r\n                                                service = document.createElement("td"),\r\n                                                diarygusername = document.createElement("td"),\r\n                                                clinicname = document.createElement("td"),\r\n                                                diarygdatetime = document.createElement("td"),\r\n                                                diarygdatetimeexport = document.createElement("td"),\r\n                                                see = document.createElement("td"),\r\n                                                dlte = document.createElement("td");\r\n\r\n                                            //Se añaden los valores a mostrar en cada columna\r\n                                            diarydate.innerHTML = results[i].diarydate;  \r\n                                            service.innerHTML = results[i].service;  \r\n                                            diarygusername.innerHTML = results[i].diarygusername;\r\n                                            clinicname.innerHTML = results[i].clinicname;  \r\n                                            diarygdatetime.innerHTML = results[i].diarygdatetime;  \r\n                                            diarygdatetimeexport.innerHTML = results[i].diarygdatetimeexport;  \r\n\r\n                                            //Se alinean columnas numéricas                                    \r\n                                            diarydate.style.width="10%";\r\n                                            service.style.width="10%";\r\n                                            diarygusername.style.width="10%";\r\n                                            clinicname.style.width="10%";\r\n                                            diarygdatetime.style.width="10%";\r\n                                            diarygdatetimeexport.style.width="10%";\r\n                                            diarygdatetime.style.align="center";\r\n                                            diarygdatetimeexport.style.align="center";\r\n                                            service.style.align="center";\r\n                                            diarygusername.style.align="center";\r\n                                        \r\n                                            //Se coloca iconos borrar y ver de cada registro\r\n                                            let typeclassbtndelete = (results[i].diarygdatetimeexport == "")?" btn__action_delete":" btn__action_deleteoff";\r\n\r\n                                            see.innerHTML = \'<a href="#" onclick="actionFunctions.UpdateDiary(\'+typeform+\',\\\'\\\',-2,\'+diarygid+\')"><!--img src="images/action_look.gif"--></a>\';   \r\n                                            see.setAttribute("class", "thCenterVertically btn__action btn__action_look");     \r\n                                            see.style.width="1%";\r\n                                            see.style.align="center";\r\n                                            \r\n                                            dlte.innerHTML = \'<a href="#" onclick="actionFunctions.DeleteDiary(\'+typeform+\',\'+diarygid+\')"><!--img src="images/action_delete.gif"--></a>\';   \r\n                                            dlte.setAttribute("class", "thCenterVertically btn__action"+typeclassbtndelete);     \r\n                                            dlte.style.width="1%";\r\n                                            dlte.style.align="center";\r\n                                            \r\n                                            //Se añaden las columnas a la fila a mostrar\r\n                                            row.appendChild(diarydate);\r\n                                            row.appendChild(service);\r\n                                            row.appendChild(diarygusername);                              \r\n                                            row.appendChild(clinicname);                              \r\n                                            row.appendChild(diarygdatetime);                              \r\n                                            row.appendChild(diarygdatetimeexport); \r\n                                            row.appendChild(see);                              \r\n                                            row.appendChild(dlte);    \r\n\r\n                                            //Se añade fila a la tabla\r\n                                            tablebody.appendChild(row);\r\n\r\n                                            // Se ajusta tamaño del marco del reporte con cada línea insertada\r\n                                            utilFunctions.fitIframe(table);      \r\n\r\n                                        }\r\n\r\n                                    },//success\r\n                                    error: function(xhr, status, error) {\r\n                                        alert("Error:" + status + " " + error);\r\n                                    }\r\n                        });\r\n                    },\r\n                    CreateNewDiary:function(typeform){\r\n                        actionFunctions.ShowPanelClienteDataForm(typeform);\r\n                        actionFunctions.ShowAllPanels();\r\n                        actionFunctions.HideRegistyPanel();\r\n                    },\r\n                    UpdateDiary:function(typeform,diarydate="",siresservice=-2,diarygid=0){\r\n                        actionFunctions.ShowPanelClienteDataForm(typeform,diarydate,siresservice,diarygid);\r\n                        actionFunctions.ShowAllPanels();\r\n                        actionFunctions.HideRegistyPanel();\r\n                    },\r\n                    DeleteDiary:function(typeform,diarygid=0){\r\n                        actionFunctions.DeleteInformation(typeform,diarygid);                    \r\n                        actionFunctions.ShowRegistryInformation(typeform);\r\n                        actionFunctions.ShowRegistryPanel();\r\n                    },\r\n                    HideRegistyPanel:function(){                    \r\n                        document.getElementById("RegistryPanel").style.display="none"; \r\n                    },\r\n                    ShowRegistryPanel:function(){                    \r\n                        document.getElementById("RegistryPanel").style.display="block"; \r\n                        actionFunctions.HideAllPanels();\r\n                        window.parent.document.getElementById("SEC_REPORT_iframe").style="height:1400px !important;";\r\n                        window.parent.document.querySelector("main").scrollTo({top: 0,behavior: "smooth"});\r\n                    },\r\n                    SetReadOnlyPersonalData:function(){ \r\n                        /*\r\n                        const elem_curpPaciente = document.getElementById("curpPaciente");\r\n                        const elem_nombre = document.getElementById("nombre");\r\n                        const elem_primerApellido = document.getElementById("primerApellido");\r\n                        const elem_segundoApellido = document.getElementById("segundoApellido");\r\n                        const elem_fechaNacimiento = document.getElementById("fechaNacimiento");\r\n                        const elem_paisNacPaciente = document.getElementById("paisNacPaciente");\r\n                        const elem_entidadNacimiento = document.getElementById("entidadNacimiento");\r\n                        const elem_sexoCURP = document.getElementById("sexoCURP");\r\n                        const elem_sexoBiologico = document.getElementById("sexoBiologico");\r\n                        const elem_primeraVezAnio = document.getElementById("primeraVezAnio");\r\n\r\n                        elem_nombre.setAttribute("readonly",true);\r\n                        elem_primerApellido.setAttribute("readonly",true);\r\n                        elem_segundoApellido.setAttribute("readonly",true);\r\n                        elem_fechaNacimiento.setAttribute("readonly",true); \r\n                        elem_curpPaciente.setAttribute("readonly",true); \r\n\r\n                        if (parseInt(elem_paisNacPaciente.value)>0){\r\n                            elem_paisNacPaciente.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_paisNacPaciente.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n\r\n                        if (parseInt(elem_entidadNacimiento.value)>0){\r\n                            elem_entidadNacimiento.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_entidadNacimiento.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n\r\n                        if (parseInt(elem_sexoCURP.value)>0){\r\n                            elem_sexoCURP.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_sexoCURP.addEventListener("keydown", e => e.preventDefault());\r\n                        }                      \r\n\r\n                        if (parseInt(elem_sexoBiologico.value)>0){ // Ajustar luego de los agregue desarrollo.\r\n                            elem_sexoBiologico.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_sexoBiologico.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n\r\n                        elem_primeraVezAnio.addEventListener("mousedown", e => e.preventDefault());\r\n                        elem_primeraVezAnio.addEventListener("keydown", e => e.preventDefault());\r\n\r\n                        elem_nombre.classList.add("__readonly");\r\n                        elem_primerApellido.classList.add("__readonly");\r\n                        elem_segundoApellido.classList.add("__readonly");\r\n                        elem_fechaNacimiento.classList.add("__readonly");     \r\n                        elem_curpPaciente.classList.add("__readonly");   \r\n                        */ \r\n\r\n                        let arrInputs = document.querySelectorAll("#FormPanel #fieldsectionid3 input");  \r\n                        let arrSelect = document.querySelectorAll("#FormPanel #fieldsectionid3 select");\r\n                        let arrTypeInput = ["text", "number", "date"];\r\n                        let arrAtt = ["curpPaciente","nombre","primerApellido","segundoApellido","fechaNacimiento","paisNacPaciente","entidadNacimiento","sexoCURP","sexoBiologico"];                      \r\n\r\n                        // Inputs text, number, date, etc.\r\n                        arrInputs.forEach(el => {\r\n                            if (arrTypeInput.includes(el.type) && arrAtt.includes(el.id) ) {\r\n                                el.readOnly = true;\r\n                                el.classList.add("__readonly");\r\n                            }\r\n                        });\r\n\r\n                        // Select\r\n                        arrSelect.forEach(el => {\r\n                            if (arrAtt.includes(el.id) ) {\r\n                                el.addEventListener("mousedown", e => e.preventDefault());\r\n                                el.addEventListener("keydown", e => e.preventDefault());\r\n                            }\r\n                        });\r\n                    },\r\n                    SetReadOnlyAllPersonalData:function(){                        \r\n                        let arrInputs = document.querySelectorAll("#FormPanel #fieldsectionid3 input");  \r\n                        let arrSelect = document.querySelectorAll("#FormPanel #fieldsectionid3 select");                      \r\n\r\n                        // Inputs text, number, date, etc.\r\n                        arrInputs.forEach(el => {\r\n                            if (["text", "number", "date"].includes(el.type)) {\r\n                                el.readOnly = true;\r\n                            }\r\n                        });\r\n\r\n                        // Select\r\n                        arrSelect.forEach(el => {\r\n                            el.addEventListener("mousedown", e => e.preventDefault());\r\n                            el.addEventListener("keydown", e => e.preventDefault());\r\n                        });\r\n\r\n                    },\r\n                    SetReadOnlyDiaryData:function(){\r\n                        let form = document.getElementById("FormPanel");\r\n                        let btnSDelete = document.getElementById("btnSDelete");\r\n                        let btnSSave = document.getElementById("btnSSave");\r\n\r\n                        // Inputs text, number, date, etc.\r\n                        form.querySelectorAll("input").forEach(el => {\r\n                            if (["text", "number", "date"].includes(el.type)) {\r\n                                el.readOnly = true;\r\n                            }\r\n                        });\r\n\r\n                        // Select\r\n                        form.querySelectorAll("select").forEach(el => {\r\n                            el.addEventListener("mousedown", e => e.preventDefault());\r\n                            el.addEventListener("keydown", e => e.preventDefault());\r\n                        });\r\n                        \r\n                        //Se desahabilita la gestión del formulario\r\n                        btnSDelete.disabled  = true;\r\n                        btnSSave.disabled  = true; \r\n\r\n                    },\r\n                    SetReadOnlyAttPrimeraVezAnio:function(){\r\n                        const elem_primeraVezAnio = document.getElementById("primeraVezAnio");\r\n                        elem_primeraVezAnio.addEventListener("mousedown", e => e.preventDefault());\r\n                        elem_primeraVezAnio.addEventListener("keydown", e => e.preventDefault());\r\n                    } \r\n                };\r\n                \r\n                //Funciones de validación de las variables que se gestionan en cada consulta.\r\n                checkFunctions = {\r\n\r\n                    checkfieldsectionid5:function(){\r\n                        let sum = 0;\r\n                        let selectElements = document.querySelectorAll("#fieldsectionid5 select");\r\n\r\n                        selectElements.forEach(select => {\r\n                        let value = parseInt(select.value);\r\n                        let valuevalid = (value<0) ? 0 : value;\r\n                            if (!isNaN(valuevalid)) {\r\n                                sum += valuevalid;\r\n                            }\r\n                        });\r\n\r\n                        return (sum==0) ? "<%=slbl_invalid_fields%>":""\r\n                    },\r\n                    checkClientData: function(){\r\n\r\n                        checkFunctions.nombre();\r\n                        checkFunctions.primerApellido();\r\n                        checkFunctions.segundoApellido();\r\n                        checkFunctions.fechaNacimiento();\r\n\r\n                        const elem_curpPaciente = document.getElementById("curpPaciente");\r\n                        const elem_nombre = document.getElementById("nombre");\r\n                        const elem_primerApellido = document.getElementById("primerApellido");\r\n                        const elem_segundoApellido = document.getElementById("segundoApellido");\r\n                        const elem_fechaNacimiento = document.getElementById("fechaNacimiento");\r\n                        const elem_paisNacPaciente = document.getElementById("paisNacPaciente");\r\n                        const elem_entidadNacimiento = document.getElementById("entidadNacimiento");\r\n                        const elem_sexoCURP = document.getElementById("sexoCURP");\r\n                        const elem_sexoBiologico = document.getElementById("sexoBiologico");\r\n                        const elem_primeraVezAnio = document.getElementById("primeraVezAnio");\r\n\r\n                        const nombre = elem_nombre.getAttribute("validated");\r\n                        const primerApellido = elem_primerApellido.getAttribute("validated");\r\n                        const segundoApellido = elem_segundoApellido.getAttribute("validated");\r\n                        const fechaNacimiento = elem_fechaNacimiento.getAttribute("validated");\r\n                        \r\n                        const nombrettip = elem_nombre.getAttribute("title");\r\n                        const primerApellidottip = elem_primerApellido.getAttribute("title");\r\n                        const segundoApellidottip = elem_segundoApellido.getAttribute("title");\r\n                        const fechaNacimientottip = elem_fechaNacimiento.getAttribute("title");\r\n\r\n                        elem_nombre.setAttribute("readonly",true);\r\n                        elem_primerApellido.setAttribute("readonly",true);\r\n                        elem_segundoApellido.setAttribute("readonly",true);\r\n                        elem_fechaNacimiento.setAttribute("readonly",true); \r\n\r\n                        if (elem_curpPaciente.value!=""){\r\n                            elem_curpPaciente.setAttribute("readonly",true); \r\n                        }\r\n\r\n                        if (parseInt(elem_paisNacPaciente.value)>0){\r\n                            elem_paisNacPaciente.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_paisNacPaciente.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n\r\n                        if (parseInt(elem_entidadNacimiento.value)>0){\r\n                            elem_entidadNacimiento.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_entidadNacimiento.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n\r\n                        if (parseInt(elem_sexoCURP.value)>0){\r\n                            elem_sexoCURP.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_sexoCURP.addEventListener("keydown", e => e.preventDefault());\r\n                        }                      \r\n\r\n                        if (parseInt(elem_sexoBiologico.value)>0){ // Ajustar luego de los agregue desarrollo.\r\n                            elem_sexoBiologico.addEventListener("mousedown", e => e.preventDefault());\r\n                            elem_sexoBiologico.addEventListener("keydown", e => e.preventDefault());\r\n                        }\r\n                        \r\n                        elem_primeraVezAnio.addEventListener("mousedown", e => e.preventDefault());\r\n                        elem_primeraVezAnio.addEventListener("keydown", e => e.preventDefault());\r\n\r\n                        elem_nombre.classList.add("__readonly");\r\n                        elem_primerApellido.classList.add("__readonly");\r\n                        elem_segundoApellido.classList.add("__readonly");\r\n                        elem_fechaNacimiento.classList.add("__readonly");     \r\n                        elem_curpPaciente.classList.add("__readonly");    \r\n                \r\n                        \r\n                        const arrChecked = [nombre,primerApellido,segundoApellido,fechaNacimiento];\r\n                        const arrCheckedTitles = [nombrettip,primerApellidottip,segundoApellidottip,fechaNacimientottip];\r\n                        \r\n                        const result = {\r\n                            success: (arrChecked.includes("false")),\r\n                            messanges: arrCheckedTitles.filter(v => v).join("\\n ")\r\n                        }\r\n                    \r\n                        return result;\r\n                    },\r\n                    checkStaffByClientAgeCE: function(staffTypeUserID,sS_StaffTypeByDiary){\r\n\r\n                        const clientAge = checkFunctions.getAge();\r\n                        const arrStaffTypeMinAge = [15,16];\r\n                        const arrStaffTypeMaxAge = [25,27];\r\n                        const validatedStaffTypeDiary = checkFunctions.checkStaffByClientAge(staffTypeUserID,sS_StaffTypeByDiary);\r\n                \r\n                        const validated = (\r\n                                            (clientAge<6 && arrStaffTypeMinAge.includes(staffTypeUserID))\r\n                                            || (clientAge>60 && arrStaffTypeMaxAge.includes(staffTypeUserID))\r\n                                            || (\r\n                                                !(clientAge<6 && arrStaffTypeMinAge.includes(staffTypeUserID))\r\n                                                && !(clientAge>60 && arrStaffTypeMaxAge.includes(staffTypeUserID)) \r\n                                                && validatedStaffTypeDiary\r\n                                                )\r\n                                            );\r\n\r\n                        return validated;\r\n                    },\r\n                    checkStaffByClientAge: function(staffTypeUserID,sS_StaffTypeByDiary){                \r\n                        return (sS_StaffTypeByDiary.split("|")).includes(staffTypeUserID);\r\n                    },\r\n                    getAge:function(diarydate=true){\r\n                        const fechaNacimiento = document.getElementById("fechaNacimiento").value;\r\n                        const fechaConsulta = document.getElementById("fechaConsulta").value;\r\n                        const fechaDate = (diarydate) ? new Date(fechaConsulta):new Date();\r\n                        const dfechaNacimiento = new Date(fechaNacimiento);\r\n                        let age = fechaDate.getFullYear() - dfechaNacimiento.getFullYear();\r\n                        const month = fechaDate.getMonth() - dfechaNacimiento.getMonth(); \r\n                        let agemonth=month;              \r\n                    \r\n                        if (month < 0 || (month === 0 && fechaDate.getDate() < dfechaNacimiento.getDate())) {\r\n                            age-=1;\r\n                            agemonth+=12;     \r\n                        }\r\n                        return parseFloat(`${age}.${agemonth}`).toFixed(2);\r\n                    },\r\n                    curpPaciente:function (){\r\n                                        let input = document.getElementById("curpPaciente");\r\n                                        const entidadNacimiento = document.getElementById("entidadNacimiento");\r\n                                        const value = input.value;  \r\n                                        const sUserCurp = "<%=sUserCurp%>";\r\n                                        const strDF = Array.from(entidadNacimiento.options)\r\n                                            .map(option => option.getAttribute("abr"))\r\n                                            .filter(abr => abr !== null) \r\n                                            .join("|");\r\n                                        if(strDF.length==0){\r\n                                            const strDF = "AS|B[CS]|C[CLMSH]|D[FG]|G[TR]|HG|JC|M[CNS]|N[ETLA]|OC|PL|Q[TR]|S[PLR]|T[CSL]|VZ|YN|ZS";\r\n                                        }\r\n\r\n                                        const re = new RegExp(\r\n                                                "^([A-Z][AEIOUX][A-Z]{2}\\\\d{2}" +\r\n                                                "(?:0[1-9]|1[0-2])" +\r\n                                                "(?:0[1-9]|[12]\\\\d|3[01])" +\r\n                                                "[HM]" +\r\n                                                "(?:" + strDF + ")" +     \r\n                                                "[B-DF-HJ-NP-TV-Z]{3}[A-Z\\\\d])" +\r\n                                                "(\\\\d)$"\r\n                                                );                                                                                \r\n                                        const nombre = (document.getElementById("nombre")).value;\r\n                                        const primerApellido = (document.getElementById("primerApellido")).value;\r\n                                        const segundoApellido = (document.getElementById("segundoApellido")).value;\r\n                                        const fechaNacimiento = (document.getElementById("fechaNacimiento")).value;\r\n                                        const [year, month, day] = fechaNacimiento.split("-");\r\n                                        const str_datebirth = `${day}/${month}/${year}`;            \r\n                                        const str_datebirth_aux = `${year}${month}${day}`; \r\n                                        const str_datebirth_curp = str_datebirth_aux.substring(2,8)      \r\n\r\n                                        const str_nombre=nombre.substring(0,1),\r\n                                            str_primerApellido=primerApellido.substring(0,2),\r\n                                            str_segundoApellido=segundoApellido.substring(0,1),\r\n                                            str_curpPacienteNombre=value.substring(3,4),\r\n                                            str_curpPacientePrimerApellido=value.substring(0,2),\r\n                                            str_curpPacienteSegundoApellido=value.substring(2,3),\r\n                                            str_curpPacienteDateBirth=value.substring(4,10);\r\n                                \r\n                                        const validated = (\r\n                                                            value!=sUserCurp                                                            \r\n                                                            && value.match(re) \r\n                                                            && value.length==18\r\n                                                            // && (str_nombre==str_curpPacienteNombre || str_curpPacienteNombre=="X")\r\n                                                            // && (str_primerApellido==str_curpPacientePrimerApellido || str_curpPacientePrimerApellido=="XX")\r\n                                                            // && (str_segundoApellido==str_curpPacienteSegundoApellido || str_curpPacienteSegundoApellido=="X")\r\n                                                            && (str_datebirth_curp==str_curpPacienteDateBirth || str_curpPacienteDateBirth=="999999")\r\n                                                            ) \r\n                                                            || value=="XXXX999999XXXXXX99";\r\n                                        if(validated){\r\n                                            //Permitirá redirigir el focus.\r\n                                                (document.getElementById("paisNacPaciente")).focus();\r\n                                            \r\n                                            const att_validated = input.getAttribute("validated");\r\n                                            \r\n                                            /*if(value!="XXXX999999XXXXXX99" && (att_validated == null || att_validated==false)){\r\n                                                utilFunctions.checkCURP(value);\r\n                                            }*/\r\n                                        \r\n                                        }else {\r\n                                            input.setAttribute(\'validated\', false);\r\n                                            input.classList.add("__not_valid"); \r\n                                            input.setAttribute(\'title\', \'El CURP debe tener 18 caracteres y una estructura similar a XXXX999999XXXXXX99. Debe ser diferente al CURP del usuario que registra la consulta y corresponder con los datos personales.\');\r\n                                        }      \r\n                    },                    \r\n                    nombre: function (){\r\n                        let input = document.getElementById("nombre");\r\n                        const value = input.value;\r\n                        let names = [];                        \r\n\r\n                        //Se comprueba estructura del apellido\r\n                        //const regex = /^[A-Za-zÑñüÜ]{1,50}([ .,\\-/\'][A-Za-zÑñüÜ]{1,50})*$/;                                          \r\n                        const regex = /^[\']?[A-Za-zÑñüÜ]{1,50}(?:([ ]?[.,\\-/\']?[ ]?)[A-Za-zÑñüÜ]{1,50})*$/;                                          \r\n                        const validated = regex.test(value);  \r\n\r\n                        //Se obtienen por defecto la primera posición del nombre \r\n                        let str_value=value.substring(0,1);\r\n\r\n                        //Si es un nombre compuesto\r\n                        /*const regexcomplex = /[ .,\\-/\']/; \r\n                        const match = value.match(regexcomplex);\r\n                        const str_delimiter =  match ? match[0] : " ";\r\n                        \r\n                        if(str_delimiter.length>0){\r\n                            const arrExcludNames = ["MARIA","JOSE","M","J"];\r\n                            names = value.split(str_delimiter);\r\n                            str_value = (arrExcludNames.includes(names[0].toUpperCase())) ? names[1].substring(0,1) : str_value ;\r\n                        }*/\r\n\r\n                        //Se determina el CURP paciente\r\n                        let inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n                        const str_curpPaciente=curpPaciente.substring(3,4);                       \r\n\r\n                        if(validated && value.length<50 /*&& (str_value==str_curpPaciente || str_curpPaciente=="X" || str_curpPaciente=="")*/){\r\n                            input.setAttribute("validated", true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute("title", \'\');\r\n                        }else {\r\n                            input.setAttribute("validated", false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'El nombre debe tener de 2 a 50 caracteres.\\nSolo letras incluida a Ñ, sin caracteres con acentos y solo se permite como caracteres intermedios de una solo aparición .,/- y el espacio.\\nDebe corresponder con la cuarta posición del CURP.\');\r\n                        }      \r\n                    },\r\n                    primerApellido: function (){\r\n\r\n                        let input = document.getElementById("primerApellido");\r\n                        const value = input.value;\r\n                        \r\n                        //Se comprueba estructura del apellido\r\n                        const regex = /^[\']?[A-Za-zÑñüÜ]{1,50}(?:([ ]?[.,\\-/\']?[ ]?)[A-Za-zÑñüÜ]{1,50})*$/;\r\n                        const validated = regex.test(value);\r\n                        \r\n                        //Se comprueba la posición 1 del CURP.                        \r\n                        const str_curp_p1 = value.substring(0,1);\r\n                        \r\n                        //Se comprueba la posición 2 del CURP.\r\n                        const regexvocal1 = /[aeiouAEIOU]/;\r\n                        const match = value.match(regexvocal1);\r\n                        const str_curp_p2 =  match ? match[0] : "";\r\n                        \r\n                        //Se obtiene el CURP del paciente\r\n                        let inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n\r\n                        const str_value= `${str_curp_p1}${str_curp_p2}`;   // value.substring(0,2),\r\n                        const str_curpPaciente=curpPaciente.substring(0,2);\r\n\r\n                        if(validated && value.length<50 /*&& (str_value==str_curpPaciente || str_curpPaciente=="XX" || str_curpPaciente=="")*/){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'El primer apellido debe tener de 2 a 50 caracteres.\\nSolo letras incluida a Ñ, sin caracteres con acentos y solo se permita en como caracteres intermedios de una solo aparición .,/- y el espacio.\\nDebe corresponder con las 2 primeras posiciones del CURP.\');\r\n                        }      \r\n                    },\r\n                    segundoApellido: function (){\r\n\r\n                        let input = document.getElementById("segundoApellido");\r\n                        const value = input.value; \r\n                        \r\n                        const regex = /^[\']?[A-Za-zÑñüÜ]{1,50}(?:([ ]?[.,\\-/\']?[ ]?)[A-Za-zÑñüÜ]{1,50})*$/;\r\n                        const validated = regex.test(value) || value=="";\r\n                        \r\n                        let inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n\r\n                        let str_value=value.substring(0,1),\r\n                            str_curpPaciente=curpPaciente.substring(2,3);\r\n\r\n                        if(validated /*&& (str_value==""|| str_value==str_curpPaciente || str_curpPaciente=="X" || str_curpPaciente=="")*/){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'El segundo apellido debe tener de 2 a 50 caracteres.\\nSolo letras incluida a Ñ, sin caracteres con acentos y solo se permita como caracteres intermedios de una aparición .,/- y el espacio.\\nDebe corresponder con la tercera posición del CURP.\');\r\n                        }      \r\n                    },\r\n                    fechaNacimiento: function (){\r\n\r\n                        let input = document.getElementById("fechaNacimiento");\r\n                        const [year, month, day] = input.value.split("-");\r\n                        const str_value = `${day}/${month}/${year}`;            \r\n                        const str_date_curp = `${year}${month}${day}`;            \r\n                        const regex = /^(0[1-9]|[12][0-9]|3[01])\\/(0[1-9]|1[0-2])\\/\\d{4}$/;                    \r\n                        const inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n                        const str_curpPaciente=curpPaciente.substring(4,10);\r\n                        const age = checkFunctions.getAge();\r\n                        const validated = ( age < 121 && regex.test(str_value) && (str_date_curp.substring(2,8)==str_curpPaciente || str_curpPaciente=="999999" ||str_curpPaciente==""));\r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'La fecha de nacimiento debe tener 10 caracteres.\\nDebe corresponder con las posiciones de la quinta a la decima del CURP (XXXX______XXXXXX99).\\nLa edad máxima del paciente debe ser 120 años.\');\r\n                        } \r\n                    },\r\n                    paisNacPaciente: function (){\r\n                        let input = document.getElementById("paisNacPaciente");\r\n                        const validated = (input.value>0);\r\n\r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");                         \r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");                         \r\n                        } \r\n                    },\r\n                    entidadNacimiento: function (){\r\n\r\n                        let input = document.getElementById("entidadNacimiento");\r\n                        const selectedOption = input.options[input.selectedIndex];\r\n                        const abr = selectedOption.getAttribute("abr");                    \r\n                        const paisNacPaciente = parseInt(document.getElementById("paisNacPaciente").value);\r\n                        const arrAllowedValues = ["NA","NE","SI"];\r\n                        const inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n                        const str_curpPaciente=curpPaciente.substring(11,13);\r\n                    \r\n                        const validated = (\r\n                                            (input.value!="-2" && !arrAllowedValues.includes(abr) && paisNacPaciente == 142 && (abr==str_curpPaciente || str_curpPaciente=="XX" || str_curpPaciente==""))\r\n                                        || (arrAllowedValues.includes(abr) &&  paisNacPaciente != 142)\r\n                                        );\r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");                         \r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");  \r\n                            input.setAttribute(\'title\', \'Campo obligatorio.\\nDebe corresponder con las posiciones 11 y 13 del CURP (XXXX999999X__XXX99).\\nPuede colocar los valores SE IGNORA, NO ESPECIFICADO o NO APLICA (si el paciente es extranjero).\');\r\n                        } \r\n                    },\r\n                    sexoCURP:function (){\r\n\r\n                        let input = document.getElementById("sexoCURP");\r\n                        const value = input.value;\r\n                        const optionselected = input.querySelector(`option[value="${value}"]`);                    \r\n                        \r\n                        const abr = optionselected.getAttribute("abr");\r\n                        const validated = (value>=0);\r\n\r\n                        const inputcurpPaciente = document.getElementById("curpPaciente");\r\n                        const curpPaciente = inputcurpPaciente.value;\r\n                        const str_curpPaciente=curpPaciente.substring(10,11);\r\n\r\n                        if(validated && (abr==str_curpPaciente || str_curpPaciente=="X" || str_curpPaciente=="")){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");                         \r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");  \r\n                            input.setAttribute(\'title\', \'Debe corresponder con la posición 11 CURP (XXXX999999_XXXXX99).\');                                       \r\n                        } \r\n                    },\r\n                    sexoBiologico:function (){\r\n\r\n                        let input = document.getElementById("sexoBiologico");\r\n                        const validated = (input.value>0);\r\n\r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");                         \r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");                         \r\n                        } \r\n                    },\r\n                    seAutodenominaAfromexicano:function (){},\r\n                    seConsideraIndigena:function (){},\r\n                    migrante:function (){},\r\n                    paisProcedencia:function (){\r\n                        let input = document.getElementById("paisProcedencia");\r\n                        const value = parseInt(input.value);\r\n                        const migrante = parseInt(document.getElementById("migrante").value);                               \r\n                        const arrValueAllowed = [1,3];                  \r\n                    \r\n                        const validated = ( (value!=142 && value>0 && migrante==2)\r\n                                            || (value==142 && arrValueAllowed.includes(migrante))\r\n                                            || (value<0 && (migrante<0 || migrante==0)));\r\n                    \r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");                         \r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");  \r\n                            input.setAttribute(\'title\', \'Si ha selecionado la opción "Migrante - Internacional" debe seleccionar el pais de procedencia.\');                                       \r\n                        } \r\n                    },\r\n                    genero:function(){\r\n                            let input = document.getElementById("genero");\r\n                            const validated = (input.value>-1);\r\n\r\n                            if(validated==true){\r\n                                input.setAttribute(\'validated\', true);\r\n                                input.classList.remove("__not_valid");\r\n                                input.setAttribute("title","");                            \r\n                            }else {\r\n                                input.setAttribute(\'validated\', false);\r\n                                input.classList.add("__not_valid"); \r\n                                input.setAttribute("title","Campo obligatorio.");                   \r\n                                                \r\n                            } \r\n                    },\r\n                    derechohabiencia:function(){\r\n                            const sSetvalues = multiselectFunctions.getValues("derechohabiencia");\r\n                            const arrSetValues = sSetvalues.split(",");\r\n                            let input = document.getElementById("derechohabiencia");\r\n                            const validated = (arrSetValues.length==1 && !arrSetValues.includes(""))\r\n                                            ||(arrSetValues.length>1 && !arrSetValues.includes("0") && !arrSetValues.includes("") && !arrSetValues.includes("1") && !arrSetValues.includes("99"));\r\n                            \r\n                            if(validated){\r\n                                input.setAttribute(\'validated\', true);\r\n                                input.classList.remove("__not_valid");    \r\n                                input.setAttribute("title","");\r\n                                input.setAttribute("values",sSetvalues);\r\n                            }else{\r\n                                input.setAttribute(\'validated\', false);\r\n                                input.classList.add("__not_valid");      \r\n                                input.setAttribute("title","Se podrá registrar más de una afiliación excepto cuando se seleccione alguno de los siguientes valores: “No especificado”, “Ninguna” o “Se ignora”.");                   \r\n                            } \r\n                    },\r\n                    fechaConsulta: function (callfromsave=false){\r\n\r\n                        let input = document.getElementById("fechaConsulta");\r\n                        let sfechaConsulta_ValueBeforeChange = input.getAttribute("valuebeforechange") || "";\r\n                        let inputfechaNacimiento = document.getElementById("fechaNacimiento");\r\n                        const value = input.value;\r\n                        const [year, month, day] = value.split("-");\r\n                        const str_value = `${day}/${month}/${year}`;            \r\n                        const regex = /^(0[1-9]|[12][0-9]|3[01])\\/(0[1-9]|1[0-2])\\/\\d{4}$/;\r\n                        \r\n                        const fechaDate = new Date();\r\n                        const fechaNacimiento = new Date(inputfechaNacimiento.value);\r\n                        const fechaConsulta = new Date(value);\r\n                        const fechaConsulta_ValueBeforeChange = new Date(sfechaConsulta_ValueBeforeChange);\r\n\r\n                        const validated = (regex.test(str_value) && (fechaConsulta >= fechaNacimiento && fechaConsulta <= fechaDate));\r\n\r\n                        let checkIFExistsDiaryOnDate = (fechaConsulta_ValueBeforeChange.getTime() != fechaConsulta.getTime() && sfechaConsulta_ValueBeforeChange!="" && value!="" && fechaConsulta_ValueBeforeChange.getTime()!=0);\r\n                        const servicioAtencion = document.getElementById("servicioAtencion").value;\r\n                        \r\n                        if(checkIFExistsDiaryOnDate && validated && servicioAtencion>0 && !callfromsave){\r\n                            \r\n                            //Se redirige foco al siguiente input yse borra evento onblur para evitar ciclo en la llamada de la función de validación\r\n                            input.onblur = null;\r\n                            const inputpeso = document.getElementById("peso");\r\n                            inputpeso.focus();\r\n\r\n                            let result = confirm("<%=slbl_check_exists_diaryondate%>");\r\n                            \r\n                            if(result){\r\n                                const typeform = "<%=sSTypeDiary%>"; \r\n                                actionFunctions.ShowPanelClienteDataForm(typeform,value,servicioAtencion,0,1);                            \r\n                                input.setAttribute(\'reloadform\', true);\r\n                            } else {\r\n                                input.setAttribute(\'reloadform\', false);\r\n                            }  \r\n                            \r\n                        }else{                            \r\n                                if(validated){\r\n                                    input.setAttribute(\'validated\', true);\r\n                                    input.classList.remove("__not_valid"); \r\n                                    input.setAttribute(\'title\', \'\');\r\n                                }else {\r\n                                    input.setAttribute(\'validated\', false);\r\n                                    input.classList.add("__not_valid"); \r\n                                    input.setAttribute(\'title\', \'Debe tener 10 caracteres. El valor registrado no debe ser posterior a la fecha de registro y no puede ser anterior a la fecha de nacimiento.\');\r\n                                }\r\n                        }\r\n                    },\r\n                    servicioAtencion:function(callfromsave=false){\r\n                        \r\n                        let input = document.getElementById("servicioAtencion");\r\n                        const value = parseInt(input.value);\r\n                        const servicioAtencion_ValueBeforeChange = input.getAttribute("valuebeforechange") || "";\r\n                        const typeform = "<%=sSTypeDiary%>"; \r\n                        const staffType = parseInt("<%=sS_StaffType%>"); \r\n                        const sCluesFrendly = "<%=sCluesFrendly%>"; //identificar si la entidad aparece en el directorio de servicios amigables para adolecentes \r\n                        const age = checkFunctions.getAge();\r\n                        const arrStaffcheckedCEX = [16,39,62,22]\r\n                        const validated = ((value==16 && typeform==2 && age>18)  //Servicio de pediatría\r\n                                        || (value==22 && typeform==2 && age>9 && age<20 && sCluesFrendly!=0) //Servicio amigable\r\n                                        || ((value==39 || value==62) && typeform==2 && age>=60) //Servicio de geriatría y gerontología\r\n                                        || (value>0 && typeform==2 && !arrStaffcheckedCEX.includes(staffType))  \r\n                                        || (value==12 && typeform==1 && age<18) //Servicio de odontopetría\r\n                                        || (value!=12 && value>0 && typeform==1));\r\n                                        \r\n                        const checkIFExistsDiaryOnDate = (servicioAtencion_ValueBeforeChange != input.value && servicioAtencion_ValueBeforeChange!="" && input.value!="");\r\n                        const inputfechaConsulta = document.getElementById("fechaConsulta")\r\n                        const fechaConsulta = inputfechaConsulta.value;\r\n                        const checkfechaConsulta = inputfechaConsulta.getAttribute("validated");\r\n                    \r\n                        if(checkIFExistsDiaryOnDate && validated && (checkfechaConsulta=="true" || checkfechaConsulta==null) && !callfromsave){\r\n                            \r\n                            //Se redirige foco al siguiente input yse borra evento onblur para evitar ciclo en la llamada de la función de validación\r\n                            input.onblur = null;\r\n                            const inputpeso = document.getElementById("peso");\r\n                            inputpeso.focus();\r\n\r\n                            let result = confirm("<%=slbl_check_exists_diaryondate%>");\r\n                            \r\n                            if(result){\r\n                                const typeform = "<%=sSTypeDiary%>"; \r\n                                actionFunctions.ShowPanelClienteDataForm(typeform,fechaConsulta,input.value,0,1);\r\n                                input.setAttribute(\'reloadform\', true);\r\n                            } else {\r\n                                input.setAttribute(\'reloadform\', false);\r\n                            } \r\n                            //Se limpia validador \r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');        \r\n\r\n                        }else{\r\n                            if(validated){\r\n                                input.setAttribute(\'validated\', true);\r\n                                input.classList.remove("__not_valid"); \r\n                                input.setAttribute(\'title\', \'\');                        \r\n                            }else {\r\n                                input.setAttribute(\'validated\', false);\r\n                                input.classList.add("__not_valid"); \r\n                                \r\n                                let lblTitle = "";\r\n                                    lblTitle += (value<0) ? "Campo obligatorio.":"";\r\n                                    lblTitle += ((value==12 && typeform==1 && age>18) || (value==16 && typeform==2 && age>18))? "La edad del paciente debe ser menor a 18 años." : "";\r\n                                    lblTitle += (value==22 && typeform==2 && age<9 && age>19)? "El paciente debe tener entre 9 y 19 años de edad." : "";\r\n                                    lblTitle += (value==22 && typeform==2 && sCluesFrendly==0)? "El centro de atención deben pertenecer al DIRECTORIO DE SERVICIOS AMIGABLES." : "";\r\n                                    lblTitle += ((value==39 || value==62) && typeform==2 && age<60) ? "El paciente debe 60 años o más." : "";\r\n                                    lblTitle += (lblTitle=="") ? "El valor registrado debe corresponder con las opciones descritas en el catálogo de SERVICIOS DE ATENCIÓN POR TIPO DE PERSONAL SIS.":"";\r\n\r\n                                input.setAttribute("title", lblTitle);\r\n                            } \r\n                        }                        \r\n                    },\r\n                    peso: function (){\r\n\r\n                        let input = document.getElementById("peso"); \r\n                \r\n                        const regex = /^([1-9]{1}[0-9]{0,2}|400)(\\.[0-9]{1,3})?$/;\r\n                        const validated = (regex.test(input.value) && parseFloat(input.value)<=400) || parseInt(input.value)==999; \r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'Puede tener hasta 7 dígitos en formato ###.###. El valor registrado debe estar entre 1 y 400 Kg. \\nSi se desconoce el dato debe registrarse el valor 999.\');\r\n                        } \r\n                    },\r\n                    talla: function (){\r\n\r\n                        let input = document.getElementById("talla"); \r\n                        const value = parseFloat(input.value); \r\n                        const regex = /^([1-9]{1}[0-9]{1,2})?$/;           \r\n                    \r\n                        const validated = (value>=30 && value<=220 && regex.test(input.value)) || (value==999) ;\r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'Puede tener 3 dígito. El valor registrado debe estar entre 30 y 220 cm. \\nSi se desconoce el dato debe registrarse el valor 999.\');\r\n                        } \r\n                    },\r\n                    circunferenciaCintura: function (){\r\n\r\n