_valid"); \r\n                            input.setAttribute(\'title\', \'Puede tener 3 dígito. El valor registrado debe estar entre 50 y 300 mm/Hg si el valor de la diastólica es mayor a 0.\\nSi se desconoce el dato debe registrarse el valor 0.\');\r\n                        } \r\n                    },\r\n                    diastolica: function (){\r\n\r\n                        let input = document.getElementById("diastolica"); \r\n                        let inputsistolica = document.getElementById("sistolica");                  \r\n                        let sistolica = parseInt(document.getElementById("sistolica").value); \r\n                        const value = parseInt(input.value); \r\n                        \r\n                        const validated = (value>=20 && value<=200 && sistolica>=value) || ((value==0 || input.value=="") && (sistolica==0 || inputsistolica.value==""))\r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n\r\n                            checkFunctions.sistolica();\r\n\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', \'Puede tener 3 dígito. El valor registrado debe estar entre 20 y 200 mm/Hg. El valor no puede ser mayor que el registrado en la variable “sistolica”.\\nSi se desconoce el dato debe registrarse el valor 0.\');\r\n                        } \r\n                    },\r\n                    frecuenciaCardiaca: function (){\r\n\r\n                        let input = document.getElementById("frecuenciaCardiaca");\r\n                        const value = parseInt(input.value); \r\n                        const validated = ((value>=40 &