orio si se rellena el campo Primera vez.":"";\r\n                            input.setAttribute("title", lblTitle);\r\n                        } \r\n                    },\r\n                    primeraVezDiagnostico3:function(){\r\n                        checkFunctions.codigoCIEDiagnostico3();\r\n                    },\r\n                    \r\n                    codigoCIEDiagnostico3:function(){\r\n                            let input = document.getElementById("codigoCIEDiagnostico3");                     \r\n                            const inputprimeraVezDiagnostico3 = document.getElementById("primeraVezDiagnostico3");\r\n                            const inputcodigoCIEDiagnostico2 = document.getElementById("codigoCIEDiagnostico2");\r\n                            const inputcodigoCIEDiagnostico1 = document.getElementById("codigoCIEDiagnostico1");\r\n                            const primeraVezDiagnostico3 = inputprimeraVezDiagnostico3.value;                     \r\n                            const codigoCIEDiagnostico2 = inputcodigoCIEDiagnostico2.getAttribute("code") || "";                       \r\n                            const codigoCIEDiagnostico1 = inputcodigoCIEDiagnostico1.getAttribute("code") || "";     \r\n                            const value = input.getAttribute("code") || "";                            \r\n                            const staffType = parseInt("<%=sS_StaffType%>");\r\n                            const first2litters = value.substring(0, 2);\r\n                            const arrCheckFirst2Litters = ["MT","CP"];\r\n                    \r\n                            const mt = (first2litters=="MT" && staffType==10);\r\n                            const cp = (first2litters=="CP" && staffType==4);                \r\n                    \r\n                            const validated = (value.length==4 && input.value.length>0 && primeraVezDiagnostico3>-1 && ((value!=codigoCIEDiagnostico1 && value!=codigoCIEDiagnostico2 ) || 