io\');\r\n                        } \r\n                    },\r\n                    referidoPor:function(){\r\n\r\n                        let input = document.getElementById("referidoPor");                     \r\n                        const value = parseInt(input.value);                                       \r\n                        const contrarreferido = parseInt(document.getElementById("contrarreferido").value);                     \r\n                        const arrStaffTypeAllowed = [15,16];\r\n                        const staffType = parseInt("<%=sS_StaffType%>");\r\n                        const age = checkFunctions.getAge(); \r\n                        let options = input.options;   \r\n\r\n                        if (arrStaffTypeAllowed.includes(staffType)){\r\n                            for (let i = 0; i < options.length; i++) { \r\n                                let valOpt = parseInt(options[i].value);                           \r\n                                if (valOpt==5 || valOpt==-2) {\r\n                                    options[i].style.display = "block"; \r\n                                }else{\r\n                                    options[i].style.display = "none"; \r\n                                }\r\n                            }\r\n                        }\r\n                        // Se verifica para el caso de las mujeres embarazadas si es "Consulta externa"\r\n                        const typeform = "<%=sSTypeDiary%>"; \r\n                        let validateemb = false;\r\n\r\n                        if(typeform=="2"){\r\n                            const relacionTemporalEmbarazo = document.getElementById("relacionTemporalEmbarazo").value;\r\n                            const arrValuesAllowedWithRelTmpEmb = [1,7,8,9] ;\r\n                            let validateemb = (relacionTemporalEmbarazo>-1 && arrValuesAllowedWithRelTmpEmb.includes(value));\r\n                            title="Debe revisar la edad del paciente y si que se ha relladado el campo de identificación de que la paciente se encuentra embarazada y la relación temporal de la consulta respecto a esta condición.";\r\n                        }  else {\r\n                            title="Solo si el paciente no ha sido contrareferido puede registrar el valor: OTRAS.";\r\n                        }             \r\n                    \r\n                        const validated = (value>0 && contrarreferido==0 && typeform=="1")\r\n                                        || (value>0 && contrarreferido<0 && typeform=="2")\r\n                                        || validateemb\r\n                                        || (value==2 && age==18)\r\n                                        || value<0; \r\n\r\n                        if(validated){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid"); \r\n                            input.setAttribute(\'title\', \'\');\r\n                        }else {\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid"); \r\n                            input.setAttribute(\'title\', title);\r\n                        } \r\n\r\n                    },\r\n                    contrarreferido:function(){  \r\n                        let input = document.getElementById("contrarreferido");  \r\n                        const value = parseInt(input.value);                     \r\n                        const inputreferidoPor = parseInt(document.getElementById("referidoPor")); \r\n                        const referidoPor = inputreferidoPor.value;                 \r\n                    \r\n                        const validated = (value>-1 && inputreferidoPor<0) || value<=0;  \r\n\r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                     