                  }else{\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");      \r\n                            input.setAttribute("title","Campo obligatorio si es MUJER, tienen entre 9 y 59 años, si se ha completado la relación temporal de emparazo y no es puerpera.");                   \r\n                        } \r\n                    },\r\n                    riesgo:function(){\r\n                            const sSetvalues = multiselectFunctions.getValues("riesgo");\r\n                            const arrSetValues = sSetvalues.split(",");\r\n                            let input = document.getElementById("riesgo");\r\n                            const atencionPregestacionalRT = parseInt(document.getElementById("atencionPregestacionalRT").value);\r\n\r\n                            const validated = (sSetvalues!="" && arrSetValues.length>1 && atencionPregestacionalRT>0 && !arrSetValues.includes("9"))\r\n                                            || (sSetvalues!="" && arrSetValues.length==1 && atencionPregestacionalRT>0)\r\n                                            || (sSetvalues=="" && atencionPregestacionalRT<0);\r\n\r\n                            if(validated){\r\n                                input.setAttribute(\'validated\', true);\r\n                                input.classList.remove("__not_valid");    \r\n                                input.setAttribute("title","");\r\n                                input.setAttribute("values",sSetvalues);\r\n                            }else{\r\n                                input.setAttribute(\'validated\', false);\r\n                                input.classList.add("__not_valid");      \r\n                                input.setAttribute("title","Rellanar solo si la variable pregestacional ha sido marcada como SI. Si no se identificar antecedentes se deberá mascar solo la opción SIN ANTECEDENTES");           