e%>");\r\n                        const arrStaffTypeAllowed = [15,16];\r\n                        const arrSex = [2,3];     \r\n                        \r\n                        const validated = ((value>-1 && arrStaffTypeAllowed.includes(staffType) && arrSex.includes(sexoBiologico))\r\n                                            ||(value<0));                      \r\n                        \r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");    \r\n                            input.setAttribute("title","");\r\n                        }else{\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");      \r\n                            input.setAttribute("title","Rellenar solo si el sexo biológico es MUJER o INTERSEXUAL y el tipo personal es PASANTE DE PSICOLOGÍA o  PSICÓLOGA(O).");                   \r\n                        } \r\n                    },\r\n                    cancerCervicouterino: function(){ //VALIDAR VARIABLES DE LA UNIDAD DE SALUD(CENTRO)\r\n                        \r\n                        let input = document.getElementById("cancerCervicouterino");   \r\n                        const value = parseInt(input.value);   \r\n                        const sexoBiologico = document.getElementById("sexoBiologico").value;      \r\n                        const staffType = parseInt("<%=sS_StaffType%>");\r\n                        const arrStaffTypeAllowed = [15,16];\r\n                        const arrSex = [2,3];     \r\n                        \r\n                        const validated = ((value>-1 && arrStaffTypeAllowed.includes(staffType) && arrSex.includes(sexoBiologico))\r\n                                            ||(value<0));                      \r\n                        \r\n                        if(validated==true)