       \r\n                                options[i].style.display = "none"; \r\n                            }\r\n                        }\r\n                        \r\n                        if (pruebaEDI==1){\r\n                            for (let i = 0; i < options.length; i++) {                            \r\n                                if (parseInt(options[i].value) > 3) {\r\n                                    options[i].style.display = "none"; \r\n                                }else{\r\n                                    options[i].style.display = "block"; \r\n                                }\r\n                            }\r\n                        }\r\n                        if (pruebaEDI==2){\r\n                            for (let i = 0; i < options.length; i++) {                            \r\n                                if (parseInt(options[i].value) < 3 && parseInt(options[i].value) > 0) {\r\n                                    options[i].style.display = "none"; \r\n                                }else{\r\n                                    options[i].style.display = "block"; \r\n                                }\r\n                            }\r\n                        }\r\n                        const validated = ((value>-1 && pruebaEDI>-1) ||(value<0) && pruebaEDI<0);                      \r\n                        \r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");    \r\n                            input.setAttribute("title","");\r\n                        }else{\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");      \r\n                            input.setAttribute("title","Rellenar solo si tipo de aplicación de la prueba de Evaluación del Desarrollo Infantil (EDI) en niños menores de 6 años.");