                numeroSobresVSOPromocion: function(){ \r\n                        \r\n                        let input = document.getElementById("numeroSobresVSOPromocion"); \r\n                        const value = parseInt(input.value);                       \r\n                        const staffType = parseInt("<%=sS_StaffType%>");\r\n                        const arrStaffTypeAllowed = [15,16];\r\n                        \r\n                        const validated = ((value>-1  && value<10 && arrStaffTypeAllowed.includes(staffType))\r\n                                            ||(value<=0)\r\n                                            || input.value=="");                      \r\n                        \r\n                        if(validated==true){\r\n                            input.setAttribute(\'validated\', true);\r\n                            input.classList.remove("__not_valid");    \r\n                            input.setAttribute("title","");\r\n                        }else{\r\n                            input.setAttribute(\'validated\', false);\r\n                            input.classList.add("__not_valid");      \r\n                            input.setAttribute("title","Rellenar solo si la edad es mayor de 59 años y el tipo personal es PASANTE DENUTRICIÓN, NUTRIÓLOGA(O), HOMEÓPATA, MÉDICA(O)TRADICIONAL INDÍGENA,  TAPS, PARTERA(O) TÉCNICA(O), PROMOTOR(A) DE SALUD, o ACUPUNTURISTA.");                   \r\n                        } \r\n                    }\r\n                };\r\n\r\n            $(document).ready(function() {        \r\n\r\n                //Se redefine el tamaño del iframe según el formulario seleccionado    \r\n                const heightframe = "<%=sHeightframe%>"; \r\n                var iSEC_REPORT_iframe = window.parent.document.getElementById("SEC_REPORT_iframe");\r\n                iSEC_REPORT_iframe.setAttribute("style", "height: " + heightframe + " !important;");  \r\n                iSEC_REPORT_iframe.parentElement.style.padding="0px";    \r\n                \r\n                //Se carga el formulario de la consulta seleccionada\r\n                const typeform = "<%=sReportPar1%>"; \r\n                const sJsonServices = "<%=sServiceValues%>";\r\n                const sStaffTypeByDiary = "<%=sS_StaffTypeByDiary%>";\r\n                //const sJsonServicesByDiary = utilFunctions.filterServicesByStaff(sJsonServices,sStaffTypeByDiary); alert(sJsonServicesByDiary);\r\n                const sServiceHTML = elemFunctions.getElementMultiSelect("ServiceID", "",sJsonServices); //sJsonServicesByDiary\r\n                document.getElementById("MultiselectElem").innerHTML = sServiceHTML.outerHTML;\r\n                actionFunctions.ShowRegistryInformation(typeform); \r\n\r\n            });\r\n\r\n            </SCRIPT>\r\n        </HEAD>\r\n\r\n    <BODY>        \r\n        <DIV class="main__title"><%=slbl_ReportName%></DIV>\r\n        <DIV CLASS="spinner-container" id="spinnerContainer" style="display: none;"><DIV CLASS="spinner"></DIV></DIV>\r\n        <FORM ID="FormPanel"></FORM>\r\n        <DIV ID="FormPanelActionBar" CLASS="row" style="display:none;"> \r\n            <DIV CLASS="col s12 m6 l6"></DIV>\r\n            <DIV CLASS="col s12 m6 l6" STYLE="text-align: right; margin-button:10px">\r\n                <%                      \r\n                    Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.ShowRegistryPanel();"" title="""  & lbl_rpt_go_back & """>" & slbl_go_back & "</BUTTON>")\r\n                    Response.Write("<BUTTON ID=""btnSDelete"" CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.DeleteInformation(" & sReportPar1 & ");"" title="""  & slbl_delete & """>" & slbl_delete & "</BUTTON>")\r\n                    Response.Write("<BUTTON ID=""btnSSave"" CLASS=""btn__form btn__primary btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.SaveInformation(" & sReportPar1 & ");"" title=""" & slbl_update & """>" & slbl_update & "</BUTTON>")\r\n                %>\r\n            </DIV>       \r\n        </DIV>\r\n\r\n        <DIV ID="RegistryPanel" >\r\n            <DIV CLASS="main__container">\r\n              <FORM ID="FilterRegistryPanel">\r\n                <DIV CLASS="row">\r\n                    <DIV CLASS="col s12 m12 l12 input-field input-outlined">\r\n                        <FIELDSET CLASS="text_7">\r\n                            <LEGEND><%=fsGetLabel("lbl_filters")%></LEGEND>                            \r\n                                <DIV ID="MultiselectElem" CLASS="col s12 m6 l6">            \r\n                                 </DIV>                              \r\n                                <DIV CLASS="col s12 m6 l6">\r\n                                    <DIV CLASS="input-field input-outlined col s12 m6 l6">\r\n                                        <INPUT id="StatsStartDate" CLASS="datepicker" type="date" value=<% = sR_DateStart %>>\r\n                                        <LABEL FOR="StatsStartDate"><% = fsGetLabel("lbl_date_ini")%></LABEL>\r\n                                    </DIV>\r\n                                    <DIV CLASS="input-field input-outlined col s12 m6 l6">\r\n                                        <INPUT id="StatsEndDate" CLASS="datepicker" type="date" value=<% = sR_DateEnd%> >\r\n                                        <LABEL FOR="StatsEndDate"><% = fsGetLabel("lbl_date_fin")%></LABEL>\r\n                                    </DIV>                                    \r\n                                </DIV>                                                                                             \r\n                      </FIELDSET>\r\n                    </DIV>     \r\n                 </DIV> \r\n                <DIV CLASS="row">\r\n                    <DIV CLASS="col s12 m6 5"></DIV>\r\n                    <DIV CLASS="col s12 m6 5" STYLE="text-align: right; margin-button:10px">\r\n                        <%                      \r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""javascript:parent.fBack();"" title="""  & lbl_rpt_go_back & """>" & slbl_go_back & "</BUTTON>")\r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__second btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.CreateNewDiary(" & sReportPar1 & ");"" title=""" & slbl_add_new_diary & """>" & slbl_add_new_diary & "</BUTTON>")\r\n                            Response.Write("<BUTTON  CLASS=""btn__form btn__primary btn waves-effect waves-light"" type=""button"" ONCLICK=""actionFunctions.ShowRegistryInformation(" & sReportPar1 & ");"" title=""" & slbl_search_for & """>" & slbl_search_for & "</BUTTON>")\r\n                        %>\r\n                    </DIV>       \r\n                </DIV>\r\n              </FORM>\r\n            </DIV>\r\n            <DIV CLASS="main__container">\r\n                <DIV CLASS="table__responsive table__container">\r\n                    <TABLE id="tdatainfo" CLASS="table__list highlight" cellpadding="0" cellspacing="0" style="height: auto;">\r\n                        <THEAD>\r\n                            <TR style="height:65px;">                                              \r\n                            <%\r\n                                Response.Write("<TH title=""" & slbl_sires_diary_date &""" CLASS=""thWithSort thCenterVertically thIconGray"" STYLE=""width:10%; text-align:left!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_sires_diary_date & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',0,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_sires_service &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:20%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_sires_service & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_assistant &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:20%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_assistant  & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',1,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_clinic &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:10%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_clinic & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_registry_date &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:15%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_registry_date & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_registry_date_export &""" CLASS=""thWithSort th_amount thCenterVertically thIconGray"" STYLE=""width:15%; text-align:center!important;cursor: pointer;"" eventlistenersorttableinit=""true""><SPAN>" & slbl_registry_date_export & "</SPAN><i onclick=""sortFunctions.sortTable(this,\'tdatainfo\',2,true)"" CLASS=""material-icons"">unfold_more</i></TH>")\r\n                                Response.Write("<TH title=""" & slbl_see & """ class=""thCenter thVertical"" STYLE=""width:1% !important; top: -18px !important;left: 4px !important;text-align:right!important;""><SPAN>" & slbl_see & "</SPAN></TH>")\r\n                                Response.Write("<TH title=""" & slbl_delete & """ class=""thCenter thVertical"" STYLE=""width:1% !important; top: -18px !important;left: 4px !important;text-align:right!important;""><SPAN>" & slbl_delete & "</SPAN></TH>")                            \r\n                            %>\r\n                            </TR>\r\n                        </THEAD>\r\n                        <TBODY  style="height: auto;">                    \r\n                        <%\r\n                        If Not iLoadData Then\r\n                            Response.Write("<TR HEIGHT=""12"">")\r\n                            Response.Write("<TD CLASS=""thCenterVertically td_date"" COLSPAN=""100%"">" & fsGetLabel("rep_without_results") &"</TD>")       \r\n                            Response.Write("</TR>") \r\n                        End If \r\n                        %>                    \r\n                        </TBODY>\r\n                    </TABLE>\r\n                </DIV>	\r\n                <DIV id="tdatainfo_pag" name="tdatainfo_pag" CLASS="row pag">\r\n                    <ul CLASS="pagination" style="margin-top: -2px !important;width: 85% !important;">\r\n                        <li id="tdatainfo_pag_Prev_li" CLASS="disabled"><a id="tdatainfo_pag_Prev" name="tdatainfo_pag_Prev" href="javascript:actionFunctions.ShowRegistryInformation(""" & sReportPar1 & """,2);" tabindex="-1"><i CLASS="material-icons">chevron_left</i></a></li>\r\n                        <li CLASS="active"><a id="tdatainfo_pag_cur" name="tdatainfo_pag_cur" align="center" style="font-size:120%;">Página <%=CurPag%> de <%=icountpage%></a></li>\r\n                        <li id="tdatainfo_pag_Next_li" CLASS="waves-effect"><a id="tdatainfo_pag_Next" name="tdatainfo_pag_Next" href="javascript:actionFunctions.ShowRegistryInformation(""" & sReportPar1 & """,1);"><i CLASS="material-icons">chevron_right</i></a></li>\r\n                        <li CLASS="waves-effect"><a id="tdatainfo_pag_Current" name="tdatainfo_pag_Current" href="" data-curpage="1"></a></li>\r\n                    </ul>\r\n                    <LABEL FOR="tdatainfo_numpag" CLASS="lbl_rows_pag"><%=slbl_show_rows%></LABEL>\r\n                    <select id="tdatainfo_numpag" onchange="javascript:actionFunctions.ShowRegistryInformation(" & sReportPar1 & ");" CLASS="select_rows_pag">\r\n                        <option value="10">10</option>\r\n                        <option value="50">50</option>\r\n                        <option value="100">100</option>\r\n                    </select>                \r\n                </DIV>\r\n            </DIV>\r\n        </DIV>        \r\n	</BODY>\r\n</HTML>\r\n\r\n', NULL, NULL, -1);
